mapper.select:
select count(*)
from chb_invest_trade
where  TRADE_CODE = #{tradeCode,jdbcType=VARCHAR}

select ACCUQTY from CHB_ASSET_POSITION
where PROD_ID=#{prodId,jdbcType=VARCHAR}
and asset_code=#{assetCode,jdbcType=VARCHAR}

and  CDATE = #{cdate,jdbcType=DATE}


and  to_CHAR(CDATE,'yyyy-MM-dd') = #{cdateString,jdbcType=VARCHAR}


    and chl_id=#{chlId,jdbcType=VARCHAR}


    and chl_id is null

WITH rate as( SELECT info.* FROM MST_EXCHARGE_QUOTE info where info.QUOT_CYY = 'CNY' and info.DATASOURCE_TYPE='SAFE' and info.TRADE_DATE = (select max(t.TRADE_DATE) from MST_EXCHARGE_QUOTE t where t.EXCHARGE_CODE = info.EXCHARGE_CODE and t.DATASOURCE_TYPE='SAFE' ) ), ASSET_COUNTER AS( /*拆借*/ SELECT asset.REP_FINPROD_ID ASSET_ID, decode(infotp.TYPE_6,'D01',mstinfo.customer_id,depodetail.COUNTER_ID) COUNTER_ID, asset.REP_RATE_YEAR/100 asset_yeild, greatest(nvl(NVL(asset.UPDATE_TIME,asset.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(depodetail.UPDATE_TIME,depodetail.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME,decode(infotp.TYPE_6,'D01',asset.REP_TRADE_TARGET,depodetail.COUNTER_ID) countername FROM REP_ASSET_INTER_LEND asset left join fin_trade_product depodetail on depodetail.FINPROD_ID = asset.REP_FINPROD_ID and depodetail.branch = 0 AND depodetail.finprod_type2 IS NOT NULL left join REP_ASSET_DEPT assetdept on asset.REP_FINPROD_ID = assetdept.REP_FINPROD_ID left join fin_product info on info.FINPROD_ID=asset.REP_FINPROD_ID left join FIN_PRODUCT_TYPE infotp on nvl(info.P_FINPROD_ID,assetdept.REP_FINPROD_ID)=infotp.FINPROD_ID left join mst_customer_info mstinfo on info.issuer=mstinfo.customer_id where (infotp.TYPE_6!='D01' and depodetail.branch = 0 AND depodetail.finprod_type2 IS NOT NULL) or infotp.TYPE_6='D01' /*回购*/ union all SELECT asset.REP_FINPROD_ID ASSET_ID, depodetail.COUNTER_ID COUNTER_ID, asset.REP_ANNUAL_INTEREST_RATE/100 asset_yeild, greatest(nvl(NVL(asset.UPDATE_TIME,asset.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(depodetail.UPDATE_TIME,depodetail.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME,depodetail.COUNTER_ID countername FROM REP_LIABILITIES asset left join fin_trade_product depodetail on depodetail.FINPROD_ID = asset.REP_FINPROD_ID where depodetail.branch = 0 /*存放*/ UNION ALL SELECT asset.REP_FINPROD_ID ASSET_ID, assettail.ISSUER COUNTER_ID, asset.REP_RATE_YEAR/100 asset_yeild, greatest(nvl(NVL(asset.UPDATE_TIME,asset.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(assettail.UPDATE_TIME,assettail.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME,assettail.ISSUER countername FROM REP_ASSET_BANK_DEPOSIT asset left join fin_product assettail on assettail.FINPROD_ID = asset.REP_FINPROD_ID ), /* 增加股票和衍生品交易 add by gaojian 2019-07-19 begin */ /*债券借贷交易拆分临时表*/ TEMP_BOND_DEAL AS ( SELECT * FROM ( /*债券借贷交易买入*/ SELECT DEAL.*, '00' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN FIN_TRADE_PRODUCT ASET ON DEAL.FINPROD_ID=ASET.FINPROD_ID WHERE DEAL.FINPROD_TYPE2 IN ('F29', 'F30') AND DEAL.PS = 'T01' AND ASET.BRANCH=0 /*债券借贷到期本金交易*/ UNION ALL SELECT DEAL.*, '01' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 IN ('F29', 'F30') AND DEAL.PS = 'T07' /*债券借贷到期费用交易*/ UNION ALL SELECT DEAL.*, '02' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 IN ('F29', 'F30') AND DEAL.PS = 'T07' ) TEMP WHERE 1 = 1 AND EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = TEMP.TRADE_ID ) ), /*外汇即期交易拆分临时表*/ TEMP_FES_DEAL AS ( SELECT * FROM ( /*拆分的买入交易*/ SELECT DEAL.*, '01' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F11' AND DEAL.PS = 'T01' /*拆分的卖出交易*/ UNION ALL SELECT DEAL.*, '02' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F11' AND DEAL.PS = 'T01' /*其余交易(理论上没有数据)*/ UNION ALL SELECT DEAL.*, '00' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F11' AND DEAL.PS != 'T01' ) TEMP WHERE 1 = 1 AND EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = TEMP.TRADE_ID ) ), /*外汇远期交易拆分临时表*/ TEMP_FEF_DEAL AS ( SELECT * FROM ( /*外汇远期交易买入*/ SELECT DEAL.*, '00' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F12' AND DEAL.PS != 'T07' /*外汇远期到期本金交易*/ UNION ALL SELECT DEAL.*, '01' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F12' AND DEAL.PS = 'T07' /*外汇远期到期费用交易*/ UNION ALL SELECT DEAL.*, '02' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F12' AND DEAL.PS = 'T07' ) TEMP WHERE 1 = 1 AND EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = TEMP.TRADE_ID ) ), /*外汇掉期交易拆分临时表*/ TEMP_FESW_DEAL AS ( SELECT * FROM ( /*外汇掉期买入卖出交易*/ SELECT DEAL.*, '01' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F13' /*外汇掉期收益交易*/ UNION ALL SELECT DEAL.*, '02' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F13' ) TEMP WHERE 1 = 1 AND EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = TEMP.TRADE_ID ) ), /* 增加股票和衍生品交易 add by gaojian 2019-07-19 end */ INVESTDEAL AS( /*增加期权 add by zhengxiaolian 2020-01-15 start*/ select NULL TRADE_SEQNO/*交易UUID*/ ,DEAL.TRADE_ID TRADE_ID/*行内交易编码*/ ,'31' INVEST_VARIETY/*投资品种*/ ,NULL INVEST_TYPE/*投资类型*/ ,DEALADD.PORTFOLIO_ID PROD_ID/*产品代码*/ ,DEAL.regist_org REGIST_BANK_CODE/*登记银行编码*/ ,DEAL.FINPROD_ID ASSET_CODE /*行内资产/负债编码*/ ,DEAL.CCY CCY/*币种*/ ,NVL(DEAL.TRADE_AMT,0) AMT /*发生金额*/ ,NULL CNY_AMT/*折算人民币金额*/ ,DEAL.SHARE_AMT NUM/*数量*/ /****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ ,CASE WHEN DEAL.TG_BUSI_TYPE = '145' THEN '10' WHEN DEAL.TG_BUSI_TYPE = '146' THEN '09' WHEN DEAL.TG_BUSI_TYPE IN ('148','149') AND DEAL.PS_PAYMENT = '01' THEN '09' WHEN DEAL.TG_BUSI_TYPE IN ('148','149') AND DEAL.PS_PAYMENT = '02' THEN '10' END CUR_ASSET_TYPE/*资金流动类型*/ ,CASE WHEN DEAL.TG_BUSI_TYPE = '145' THEN '支付期权费用' WHEN DEAL.TG_BUSI_TYPE = '146' THEN '卖方收取期权费用' WHEN DEAL.TG_BUSI_TYPE IN ('148','149') AND DEAL.PS_PAYMENT = '01' THEN '场外期权收入' WHEN DEAL.TG_BUSI_TYPE IN ('148','149') AND DEAL.PS_PAYMENT = '02' THEN '场外期权支出' end CUR_ASSETDET_TYPE /*资金流动类型说明*/ /*,DECODE(DEAL.PS,'T01','01','T59','02','T60','02','T61','02') CUR_ASSET_TYPE资金流动类型 ,'无' CUR_ASSETDET_TYPE 资金流动类型说明*/ /****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ ,DEAL.SETTLE_DATE DEALDATE /*交易日*/ ,DECODE(DEAL.PS,'T22',SECASSET.REGIST_ORG,'T23',SECASSET.REGIST_ORG,TOTALDEAL.COUNTER_ID) TRADE_COUNTER/*交易对手*/
/****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ ,NULL UNIT_PRICE_FULL /*单位成交价格（全价）*/ ,NULL UNIT_PRICE_NET /*单位成交价格（净价）*/ ,DEAL.YIELD END_RATE /*到期收益率*/ ,DEAL.TRADE_ID CONTRACT_CODE /*成交编号/合同号*/ ,NULL REMARK /*备注*/ ,NULL CHL_CPCT_ID /*通道代码*/ ,'04' TRADE_TYPE /*交易类型*/ ,NULL CHL_AGRT_NAME /*通道名称*/ ,'02' IS_UNDER_TRADE /*是否底层交易流水 01 是/ 02 否*/ ,DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS /*数据状态*/ ,NULL ORG_CODE /*机构代码*/ ,NULL DEPT_CODE /*部门代码*/ ,deal.CREATE_USER CREATE_USER /*创建人*/ ,deal.CREATE_TIME CREATE_TIME /*创建时间*/ ,deal.UPDATE_USER UPDATE_USER /*更新人*/ ,greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME /*更新时间*/ ,NULL STATUS_DATE /*数据日期*/ ,REVDL.create_time REV_DATE/*撤销日*/ ,NULL DATA_SOURCE /*数据来源*/ ,NULL RATE /*利率*/ ,NULL BASIS /*计息基础*/ ,NULL FACEVALUE /*面值*/ ,DECODE(DEAL.PS,'T01','08','T59','09','T60','09','T61','09') DEALTYPE /*交易类型*/ ,deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID /****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ left join MST_COUNTER_PARTY party on DECODE(DEAL.PS,'T22',SECASSET.REGIST_ORG,'T23',SECASSET.REGIST_ORG,TOTALDEAL.COUNTER_ID) = party.COUNTER_ID left join MST_COUNTER_PARTY party2 on DECODE(DEAL.PS,'T22',SECASSET.REGIST_ORG,'T23',SECASSET.REGIST_ORG,TOTALDEAL.COUNTER_ID) = party2.LINK_ID
/****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ where 1=1 and DEAL.FINPROD_TYPE2='F35' AND nvl(deal.p_trade_id,'NOREV')='NOREV'/*不取撤销交易*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ and NVL(DEAL.TRADE_AMT,0) > 0 /****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/
/*增加期权 add by zhengxiaolian 2020-01-15 end*/ union all
/*债券+abs+行权 - 非还本不带息*/ SELECT NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '01' INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS','SELL','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/
NVL(fpd.FINPROD_ID,DEAL.FINPROD_ID) ASSET_CODE, DEAL.CCY CCY, deal.trade_amt AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ /*DECODE(DEAL.PS,'T29',NVL(DEAL.ACCR_NUM,0),NVL(DEAL.SHARE_AMT,0))*100 NUM,债券借贷按照计提份额*/ CASE WHEN DEAL.TG_BUSI_TYPE = '144' THEN CASE WHEN DEAL.PS = 'T22' THEN NVL(NVL(DEAL.ACCR_NUM,DEAL.SHARE_AMT),0) * 100 ELSE NVL(DEAL.SHARE_AMT,0) / NVL(PRODUCTASSET.M_PRIN_AMT,100) * 100 END ELSE NVL(NVL(DEAL.ACCR_NUM,DEAL.SHARE_AMT),0) * 100 END NUM, DECODE(DEAL.PS,'T01','01','T02','02','T03','02','T39','02','T22',DECODE(TOTALDEAL.PS,'T08','09','T09','09','T07','09'),'T23',DECODE(TOTALDEAL.PS,'T08','11','T07','02'),'T29','12') CUR_ASSET_TYPE,/*中间还本的利息需统计成11其他收入*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08','债券收息交易','T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08','债券中间还本交易','T07','到期'),'T29','融入债券付息还本') CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T29',DEAL.COUNTER_ID,'T39',party2.COUNTER_ID,'T22',party2.COUNTER_ID,'T23',party2.COUNTER_ID, 'T29', party2.COUNTER_ID, 'T32', party2.COUNTER_ID) TRADE_COUNTER, ROUND(DECODE(DEAL.PS,'T01',DEAL.UNIT_FPRICE,'T02',DEAL.UNIT_FPRICE,'T03',DEAL.UNIT_FPRICE,'T39',NVL(DEAL.UNIT_FPRICE, DECODE(DEAL.SHARE_AMT, 0, 0, DEAL.TRADE_AMT/DEAL.SHARE_AMT)),'T23',DECODE(TOTALDEAL.PS,'T08',DECODE(DEAL.TG_BUSI_TYPE,'144',NVL(PRODUCTASSET.M_PRIN_AMT,0) * -1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT*-1)),'T07',DECODE(DEAL.TG_BUSI_TYPE,'144',NVL(PRODUCTASSET.M_PRIN_AMT,0),DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)))),4) UNIT_PRICE_FULL, ROUND(DECODE(DEAL.PS,'T01',DEAL.UNIT_CPRICE,'T02',DEAL.UNIT_CPRICE,'T03',DEAL.UNIT_CPRICE,'T39',NVL(DEAL.UNIT_CPRICE, DECODE(DEAL.SHARE_AMT, 0, 0, DEAL.CPRICE_AMT/DEAL.SHARE_AMT)),'T23',DECODE(TOTALDEAL.PS,'T08',DECODE(DEAL.TG_BUSI_TYPE,'144',NVL(PRODUCTASSET.M_PRIN_AMT,0) * -1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT*-1)),'T07',DECODE(DEAL.TG_BUSI_TYPE,'144',NVL(PRODUCTASSET.M_PRIN_AMT,0),DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)))),4) UNIT_PRICE_NET, DECODE(DEAL.PS,'T01',DEAL.YIELD,'T02',DEAL.YIELD,'T03',DEAL.YIELD,'T39',DEAL.YIELD,'T23',decode(TOTALDEAL.ps,'T07',DEAL.YIELD)) END_RATE, DEAL.TRADE_ID CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(DEAL.IS_CANCEL, 'Y', 'D', 'E') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ decode(deal.ps,'T23',decode(totaldeal.ps,'T07',decode(deal.SHARE_AMT,0,0,DEAL.TRADE_AMT/deal.SHARE_AMT),deal.par_value),DEAL.PAR_VALUE) FACEVALUE,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T03','09','T39','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01')) DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID left join mst_customer_info customer on SECASSET.ISSUER = customer.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT PRODUCTASSET ON PRODUCTASSET.FINPROD_ID=TOTALDEAL.FINPROD_ID AND PRODUCTASSET.BRANCH=DEAL.BRANCH
LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T39',DEAL.COUNTER_ID,'T22',customer.customer_id,'T23',customer.customer_id) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T39',NVL(DEAL.COUNTER_ID,secASSET.Issuer),'T22',customer.customer_id,'T23',customer.customer_id, 'T29', secASSET.Issuer, 'T32', secASSET.Issuer)
left join FIN_PRODUCT_ADD fpd on secASSET.finprod_market_id = fpd.appear_market_id LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fpd.FINPROD_ID WHERE 1=1 /*债券借贷现金交易融出券生成的交易暂时先放这里统计*/ AND (DEAL.BUSI_TYPE IN ( '02', '29') or (DEAL.BUSI_TYPE = '14' and DEAL.PS = 'T02') or (DEAL.BUSI_TYPE = '37' and DEAL.FINPROD_TYPE2 = 'F01')) and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' and (DEAL.TG_BUSI_TYPE!='141' OR DEAL.TG_BUSI_TYPE IS NULL) /***非还本不带息数据筛选***/ AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = deal.TRADE_ID ) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26','T41') ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) union all /*债券+abs+行权 -还本不带息数据*/ SELECT NULL TRADE_SEQNO, deal.TOTLE_TRADE_ID TRADE_ID, '01' INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS','SELL','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ ORG.regist_org REGIST_BANK_CODE,/*登记银行编码*/
NVL(fpd.FINPROD_ID,DEAL.FINPROD_ID) ASSET_CODE, DEAL.CCY CCY, deal.trade_amt AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DEAL.SHARE_AMT*100 NUM, DECODE(DEAL.PS,'T01','01','T02','02','T03','02','T39','02','T22',DECODE(TOTALDEAL.PS,'T08','11','T09','09','T07','09'),'T23',DECODE(TOTALDEAL.PS,'T08','11','T07','02')) CUR_ASSET_TYPE,/*中间还本的利息需统计成11其他收入*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08','部分到期-收息','T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08','部分到期','T07','到期')) CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE,
DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T39',DEAL.COUNTER_ID,'T22',customer.CUSTOMER_NAME,'T23',customer.CUSTOMER_NAME) TRADE_COUNTER, DECODE(DEAL.PS,'T01',DEAL.UNIT_FPRICE,'T02',DEAL.UNIT_FPRICE,'T03',DEAL.UNIT_FPRICE,'T39',DEAL.UNIT_FPRICE,'T23',DECODE(TOTALDEAL.PS,'T08',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT*-1),'T07',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT))) UNIT_PRICE_FULL, DECODE(DEAL.PS,'T01',DEAL.UNIT_CPRICE,'T02',DEAL.UNIT_CPRICE,'T03',DEAL.UNIT_CPRICE,'T39',DEAL.UNIT_CPRICE,'T23',DECODE(TOTALDEAL.PS,'T08',decode(deal.SHARE_AMT,0,0,DEAL.trade_amt/DEAL.SHARE_AMT*-1),'T07',decode(deal.SHARE_AMT,0,0,DEAL.trade_amt/DEAL.SHARE_AMT))) UNIT_PRICE_NET, DECODE(DEAL.PS,'T01',DEAL.YIELD,'T02',DEAL.YIELD,'T03',DEAL.YIELD,'T39',DEAL.YIELD,'T23',decode(TOTALDEAL.ps,'T07',DEAL.YIELD)) END_RATE, DEAL.TOTLE_TRADE_ID CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.P_TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ decode(deal.ps,'T23',decode(totaldeal.ps,'T07',decode(deal.SHARE_AMT,0,0,DEAL.TRADE_AMT/deal.SHARE_AMT),deal.par_value),DEAL.PAR_VALUE) FACEVALUE,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T03','09','T39','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01')) DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL REVDL ON deal.TOTLE_TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID left join mst_customer_info customer on SECASSET.ISSUER = customer.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT PRODUCTASSET ON PRODUCTASSET.FINPROD_ID=TOTALDEAL.FINPROD_ID AND PRODUCTASSET.BRANCH=0 LEFT JOIN trd_deal_total_add TRDADD ON TRDADD.TOTLE_TRADE_ID=TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT PRODUCTASSET1 ON PRODUCTASSET1.FINPROD_ID=TRDADD.MP_FINPROD_ID AND PRODUCTASSET1.BRANCH=0 LEFT JOIN (SELECT DEAL.TOTLE_TRADE_ID, DEALADD.PORTFOLIO_ID, SUM(NVL(DEALADD.REG_DATE_AMT,0)) REG_DATE_AMT FROM TRD_PRODUCT_DEAL_ADD DEALADD LEFT JOIN TRD_PRODUCT_DEAL DEAL ON DEALADD.TRADE_ID = DEAL.TRADE_ID GROUP BY DEAL.TOTLE_TRADE_ID, DEALADD.PORTFOLIO_ID ) DEALADD ON DEALADD.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID LEFT JOIN (SELECT TOTLE_TRADE_ID , regist_org FROM TRD_PRODUCT_DEAL GROUP BY TOTLE_TRADE_ID , regist_org ) ORG ON ORG.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T39',DEAL.COUNTER_ID,'T22',customer.customer_id,'T23',customer.customer_id) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T39',DEAL.COUNTER_ID,'T22',customer.customer_id,'T23',customer.customer_id)
left join FIN_PRODUCT_ADD fpd on secASSET.finprod_market_id = fpd.appear_market_id LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fpd.FINPROD_ID WHERE 1=1 AND EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID /*债券借贷现金交易融出券生成的交易暂时先放这里统计*/ AND (DEAL.BUSI_TYPE IN ( '02', '29') or (DEAL.BUSI_TYPE = '14' and DEAL.PS = 'T02') or (DEAL.BUSI_TYPE = '37' and DEAL.FINPROD_TYPE2 = 'F01')) and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') AND NVL(AD.UPDATE_TIME,AD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = a.TRADE_ID ) and (A.TG_BUSI_TYPE!='141' OR A.TG_BUSI_TYPE IS NULL) ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*计划类资产-非还本不带息数据*/ union all SELECT NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01','04','02','03','03','05') INVEST_VARIETY,/*投资品种根据收益类型分类*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ nvl(PLANASSET.FINPROD_ID,PLANASSETDETAIL.FINPROD_ID) ASSET_CODE, DEAL.CCY CCY, /*decode(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01',decode(deal.ps,'T12',deal.int_amt,DEAL.TRADE_AMT),DEAL.TRADE_AMT) AMT,*/ /*利率型单独一类、货币性和净值型一类*/ decode(deal.ps,'T01',deal.trade_amt,'T11',deal.int_amt,'T12',deal.int_amt,DEAL.TRADE_AMT) AMT,/*对于计划类资产，红利再投及分红 发生金额直接取int_amt*/ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ decode(deal.ps,'T22',decode(totaldeal.ps,'T09',TOTALDEALPA.REMAIN_PRIN_AMT,TOTALDEAL.SHARE_AMT),'T23',TOTALDEAL.SHARE_AMT,DEAL.SHARE_AMT) NUM,
DECODE(DEAL.PS,'T01','01','T02','02','T22','09','T23','02','T05','01','T19','02','T11','09','T12','01','C3','01','C06','02') CUR_ASSET_TYPE,/*计划类资产红利再投另加一笔投资收益*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08','部分到期-收息','T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08','部分到期','T07','到期'),'T11','资产分红') CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, decode(deal.ps,'T22',custinfo.CUSTOMER_NAME,'T23',custinfo.CUSTOMER_NAME,'T11',custinfo.CUSTOMER_NAME,'T12',custinfo.CUSTOMER_NAME,DEAL.COUNTER_ID) TRADE_COUNTER,/*对手方*/
ROUND(DECODE( DEAL.PS, 'T01',DECODE( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)*100), 'T02',DECODE( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE), '03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)*100), 'T23',100, 'T05',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T19',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T12',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01',decode(nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT),0,0,DEAL.INT_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT)),'03',1,DEAL.TRADE_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.TRADE_AMT,DEAL.SHARE_AMT),deal.TRADE_AMT)) ),4) UNIT_PRICE_FULL,
ROUND(DECODE( DEAL.PS, 'T01',decode( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',100 ), 'T02',decode( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',100),
'T23',100, 'T05',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T19',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T12',decode(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01',decode(nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT),0,0,DEAL.INT_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT)),'03',1,DEAL.TRADE_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.TRADE_AMT,DEAL.SHARE_AMT),deal.TRADE_AMT)) ),4) UNIT_PRICE_NET, DECODE(DEAL.PS,'T23',DECODE(TOTALDEAL.PS,'T07',DEAL.YIELD)) END_RATE, nvl(nvl(PLANASSET.CONTRACT_NO,PLANASSETDETAIL.CONTRACT_NO),DEAL.TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(DEAL.IS_CANCEL,'N','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ null faceValue,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01'),'T05','12','T19','15','T11','20','T12','05','C3','04','C06','03') DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, DEALADD.REG_DATE_AMT INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID /* ASSETPOSITION.AMOUNT INTPAYAMT */ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT PLANASSETDETAIL on deal.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID LEFT JOIN FIN_PRODUCT PLANASSET on PLANASSETDETAIL.P_FINPROD_ID = PLANASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO custinfo on nvl(PLANASSET.MANAGER,PLANASSETDETAIL.MANAGER) = custinfo.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID)
WHERE 1=1 /*过滤项目类资产、计划类资产、基金重复项*/ AND DEAL.BUSI_TYPE IN( '07','09','06', '37') AND DEAL.FINPROD_TYPE2 = 'F17' /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /***添加非还本不带息拆分数据***/
AND (DEAL.PS = 'T22' OR (DEAL.PS != 'T22' and EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = deal.TRADE_ID )))
AND not EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') ) and (DEAL.TG_BUSI_TYPE!='141' OR DEAL.TG_BUSI_TYPE IS NULL) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP})
/*计划类资产-还本不带息数据*/ union all
SELECT NULL TRADE_SEQNO, deal.TOTLE_TRADE_ID TRADE_ID, DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01','04','02','03','03','05') INVEST_VARIETY,/*投资品种根据收益类型分类*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ ORG.regist_org REGIST_BANK_CODE,/*登记银行编码*/ nvl(PLANASSET.FINPROD_ID,PLANASSETDETAIL.FINPROD_ID) ASSET_CODE, DEAL.CCY CCY, decode(deal.ps,'T01',deal.trade_amt,'T11',deal.int_amt,'T12',deal.int_amt,'T23',totaldeal.trade_amt,DEAL.TRADE_AMT) AMT,/*对于计划类资产，红利再投及分红 发生金额直接取int_amt*/ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ decode(deal.ps,'T22',decode(totaldeal.ps,'T09',TOTALDEALPA.REMAIN_PRIN_AMT,TOTALDEAL.SHARE_AMT),'T23',TOTALDEAL.SHARE_AMT,DEAL.SHARE_AMT) NUM, DECODE(DEAL.PS,'T01','01','T02','02','T22','09','T23','02','T05','01','T19','02','T11','09','T12','01','C3','01','C06','02') CUR_ASSET_TYPE,/*计划类资产红利再投另加一笔投资收益*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08','部分到期-收息','T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08','部分到期','T07','到期'),'T11','资产分红') CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, decode(deal.ps,'T22',custinfo.CUSTOMER_NAME,'T23',custinfo.CUSTOMER_NAME,'T11',custinfo.CUSTOMER_NAME,'T12',custinfo.CUSTOMER_NAME,DEAL.COUNTER_ID) TRADE_COUNTER,/*对手方*/ ROUND(DECODE( DEAL.PS, 'T01',DECODE( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)*100), 'T02',DECODE( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE), '03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)*100), 'T23',100, 'T05',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T19',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T12',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01',decode(nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT),0,0,DEAL.INT_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT)),'03',1,DEAL.TRADE_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.TRADE_AMT,DEAL.SHARE_AMT),deal.TRADE_AMT)) ),4) UNIT_PRICE_FULL, ROUND(DECODE( DEAL.PS, 'T01',decode( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',100 ), 'T02',decode( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',100),
'T23',100, 'T05',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T19',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T12',decode(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01',decode(nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT),0,0,DEAL.INT_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT)),'03',1,DEAL.TRADE_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.TRADE_AMT,DEAL.SHARE_AMT),deal.TRADE_AMT)) ),4) UNIT_PRICE_NET, DECODE(DEAL.PS,'T23',DECODE(TOTALDEAL.PS,'T07',DEAL.YIELD)) END_RATE, nvl(nvl(PLANASSET.CONTRACT_NO,PLANASSETDETAIL.CONTRACT_NO),DEAL.TOTLE_TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.P_TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ null faceValue,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01'),'T05','12','T19','15','T11','20','T12','05','C3','04','C06','03') DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, DEALADD.REG_DATE_AMT INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ /* ASSETPOSITION.AMOUNT INTPAYAMT */ FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL REVDL ON deal.TOTLE_TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT PLANASSETDETAIL on deal.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID LEFT JOIN FIN_PRODUCT PLANASSET on PLANASSETDETAIL.P_FINPROD_ID = PLANASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO custinfo on nvl(PLANASSET.MANAGER,PLANASSETDETAIL.MANAGER) = custinfo.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN ( SELECT DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID,sum(nvl(DEALADD.REG_DATE_AMT,0)) REG_DATE_AMT FROM TRD_PRODUCT_DEAL_ADD DEALADD LEFT JOIN TRD_PRODUCT_DEAL DEAL ON DEALADD.TRADE_ID = DEAL.TRADE_ID group by DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID) DEALADD ON DEALADD.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID LEFT JOIN ( SELECT TOTLE_TRADE_ID ,regist_org FROM TRD_PRODUCT_DEAL GROUP BY TOTLE_TRADE_ID ,regist_org ) ORG ON ORG.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID)
WHERE 1=1
/***添加还本不带息拆分数据***/ AND EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID /*过滤项目类资产、计划类资产、基金重复项*/ AND A.BUSI_TYPE IN( '07','09','06', '37') AND A.FINPROD_TYPE2 = 'F17' /*只接入原始交易数据*/ /*AND A.TRADE_STATUS = '01'*/ /**TG_BUSI_TYPE141先不处理，下面一并处理*/ and (A.TG_BUSI_TYPE!='141' OR A.TG_BUSI_TYPE IS NULL) and nvL(A.p_trade_id,'NOREV') = 'NOREV' AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') AND NVL(AD.UPDATE_TIME,AD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = a.TRADE_ID )) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}
or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP})
/*存款类资产、拆借类资产 -非还本不带息数据*/ union all SELECT NULL TRADE_SEQNO, DEAL.TRADE_ID TRADE_ID, DECODE(DEAL.FINPROD_TYPE2,'F08','07','F09','08','F21','08','F25','07','06') INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, decode(deal.ps,'T12',deal.int_amt,DEAL.TRADE_AMT) AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ nvl(DEAL.SHARE_AMT,t3.amount) NUM, /*01 拆借(包含F08 普通拆借拆入 和 F25 特拆拆入) 03 存款 37 逾期*/ CASE WHEN DEAL.BUSI_TYPE = '01' THEN (CASE WHEN DEAL.FINPROD_TYPE2 = 'F08' or DEAL.FINPROD_TYPE2 = 'F25' THEN DECODE(DEAL.PS,'T01','06','T02','08','T23','08','T22','10') ELSE DECODE(DEAL.PS,'T01','05','T02','07','T23','07','T22','09') END) WHEN DEAL.BUSI_TYPE = '03' THEN DECODE(DEAL.PS,'T01','03','T02','04','T12','03','T22','09','T23',DECODE(TOTALDEAL.PS,'T08','04','T07','04'),'T38','04') WHEN DEAL.BUSI_TYPE = '37' THEN '09' ELSE NULL END AS CUR_ASSET_TYPE,
DECODE(DEAL.BUSI_TYPE,'01',DECODE(DEAL.PS,'T22',DECODE(DEAL.FINPROD_TYPE2,'F08','付息','F25','付息','收息'),'T23','到期'),DECODE(DEAL.PS,'T22',DECODE(TOTALDEAL.PS,'T08','收息','T09','收息','T07','收息'),'T23',DECODE(TOTALDEAL.PS,'T08','部分到期','T07','到期'))) CUR_ASSETDET_TYPE, DEAL.SETTLE_DATE DEALDATE,
case when DEAL.BUSI_TYPE = '03' then DECODE(DEAL.PS,'T22',mst.customer_name,'T23',mst.customer_name,'T38',mst.customer_name,'T12',mst.customer_name,DECODE(TOTALDEAL.PS,'T09',mst.customer_name,deal.counter_id)) when DEAL.BUSI_TYPE = '37' then DECODE(DEAL.PS,'T22',mst.customer_name,'T23',mst.customer_name,'T38',mst.customer_name,'T12',mst.customer_name,DECODE(TOTALDEAL.PS,'T09',mst.customer_name,deal.counter_id)) when DEAL.BUSI_TYPE = '01' and DEAL.FINPROD_TYPE2 = 'F07' then NVL(deal.counter_id,party2.COUNTER_ID) when DEAL.BUSI_TYPE = '01' and DEAL.FINPROD_TYPE2 != 'F07' then NVL(deal.counter_id,assetcounter.COUNTER_ID) else null end as TRADE_COUNTER,
/* DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T22',assetcounter.COUNTER_ID,'T23',assetcounter.COUNTER_ID,'T38',assetcounter.COUNTER_ID,decode(TOTALDEAL.PS,'T09',assetcounter.COUNTER_ID,deal.counter_id)),'01',decode(deal.finprod_id,'F07',DECODE(DEAL.PS,'T22',assetcounter.COUNTER_ID,'T23',assetcounter.COUNTER_ID,'T38',assetcounter.COUNTER_ID,decode(TOTALDEAL.PS,'T09',assetcounter.COUNTER_ID,deal.counter_id),DECODE(DEAL.PS,'T22',assetcounter.COUNTER_ID,'T23',assetcounter.COUNTER_ID,deal.counter_id)))) TRADE_COUNTER, */ /*到期收息的对手方要为空*/ NULL UNIT_PRICE_FULL, NULL UNIT_PRICE_NET, DECODE(DEAL.BUSI_TYPE,'01',assetcounter.asset_yeild,'03',assetcounter.asset_yeild) END_RATE, nvl(DEPOASSET.CONTRACT_NO,DEAL.TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(DEAL.IS_CANCEL, 'Y', 'D', 'E') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEPOASSET.UPDATE_TIME,DEPOASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(ASSETCOUNTER.UPDATE_TIME,to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ null faceValue,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T38','09','T22',DECODE(TOTALDEAL.PS,'T08','25','T09','23','T07','02','C7','23'),'T23',DECODE(TOTALDEAL.PS,'T08','24','T07','01'),'T12','05') DEALTYPE, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, DECODE(DEAL.PS,'T12',AMOUNT,null) INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN ASSET_COUNTER ASSETCOUNTER/*资产交易对手*/ on assetcounter.asset_id = DEAL.FINPROD_ID LEFT JOIN FIN_PRODUCT DEPOASSET ON DEPOASSET.FINPROD_ID = DEAL.FINPROD_ID left join MST_CUSTOMER_INFO mst on DEPOASSET.ISSUER = mst.customer_id LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON deal.TRADE_ID = T2.TRADE_ID LEFT JOIN ptl_sec_position T3 ON deal.mdate -1 = T3.CDATE AND deal.FINPROD_ID = T3.FINPROD_ID and T2.PORTFOLIO_ID = T3.PORTFOLIO_ID and T3.HODING_TYPE='03' left join MST_COUNTER_PARTY party on party.COUNTER_ID= DECODE(DEAL.BUSI_TYPE,'01',NVL(deal.counter_id,assetcounter.COUNTER_ID),DECODE(DEAL.PS,'T22',mst.customer_id,'T23',mst.customer_id,'T38',mst.customer_id,decode(TOTALDEAL.PS,'T09',mst.customer_id,NVL(deal.counter_id, assetcounter.COUNTER_ID)))) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= DECODE(DEAL.BUSI_TYPE,'01',NVL(deal.counter_id,assetcounter.COUNTER_ID),DECODE(DEAL.PS,'T22',mst.customer_id,'T23',mst.customer_id,'T38',mst.customer_id,decode(TOTALDEAL.PS,'T09',mst.customer_id,NVL(deal.counter_id, assetcounter.COUNTER_ID))))
WHERE 1=1 and (deal.BUSI_TYPE in( '03','01') or (DEAL.BUSI_TYPE = '37' and DEAL.FINPROD_TYPE2 = 'F07')) /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /***添加非还本不带息拆分数据***/ AND EXISTS (SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = deal.TRADE_ID ) AND NOT EXISTS (SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID AND AD.PORTFOLIO_ID =T2.PORTFOLIO_ID AND A.PS IN ('T25','T26') ) and (DEAL.TG_BUSI_TYPE!='141' OR DEAL.TG_BUSI_TYPE IS NULL) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEPOASSET.UPDATE_TIME,DEPOASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ASSETCOUNTER.UPDATE_TIME > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) union all /*存款类资产、拆借类资产 -还本不带息数据*/ SELECT NULL TRADE_SEQNO, DEAL.TOTLE_TRADE_ID TRADE_ID, DECODE(DEAL.FINPROD_TYPE2,'F08','07','F09','08','F21','08','F25','07','06') INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ org.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, decode(deal.ps,'T12',deal.int_amt,DEAL.TRADE_AMT) AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ nvl(DEAL.SHARE_AMT,t3.amount) NUM, DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T01','03','T02','04','T12','01','T22','09','T23',DECODE(TOTALDEAL.PS,'T08','04','T07','04'),'T38','04'),'01',DECODE(DEAL.FINPROD_TYPE2,'F08',DECODE(DEAL.PS,'T01','06','T02','08','T22','10','T23','08'),DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07'))) CUR_ASSET_TYPE, DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T22',DECODE(TOTALDEAL.PS,'T08','收息','T09','收息','T07','收息'),'T23',DECODE(TOTALDEAL.PS,'T08','部分到期','T07','到期')),'01',DECODE(DEAL.PS,'T22',DECODE(DEAL.FINPROD_TYPE2,'F08','付息','收息'),'T23','到期')) CUR_ASSETDET_TYPE, DEAL.SETTLE_DATE DEALDATE, DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T22',mst.customer_name,'T23',mst.customer_name,'T38',mst.customer_name,'T12',mst.customer_name,DECODE(TOTALDEAL.PS,'T09',mst.customer_name,deal.counter_id)),'01',NVL(deal.counter_id,assetcounter.COUNTER_ID)) TRADE_COUNTER,
/*到期收息的对手方要为空*/ NULL UNIT_PRICE_FULL, NULL UNIT_PRICE_NET, DECODE(DEAL.BUSI_TYPE,'01',assetcounter.asset_yeild,'03',assetcounter.asset_yeild) END_RATE, nvl(DEPOASSET.CONTRACT_NO,DEAL.TOTLE_TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.P_TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEPOASSET.UPDATE_TIME,DEPOASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(ASSETCOUNTER.UPDATE_TIME,to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ null faceValue,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T38','09','T22',DECODE(TOTALDEAL.PS,'T08','25','T09','23','T07','02','C7','23'),'T23',DECODE(TOTALDEAL.PS,'T08','24','T07','01'),'T12','05') DEALTYPE, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, DECODE(DEAL.PS,'T12',AMOUNT,null) INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL REVDL ON deal.TOTLE_TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN ASSET_COUNTER ASSETCOUNTER/*资产交易对手*/ on assetcounter.asset_id = DEAL.FINPROD_ID LEFT JOIN FIN_PRODUCT DEPOASSET ON DEPOASSET.FINPROD_ID = DEAL.FINPROD_ID left join MST_CUSTOMER_INFO mst on DEPOASSET.ISSUER = mst.customer_id LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON deal.TOTLE_TRADE_ID = T2.TRADE_ID LEFT JOIN ptl_sec_position T3 ON deal.mdate -1 = T3.CDATE AND deal.FINPROD_ID = T3.FINPROD_ID and T2.PORTFOLIO_ID = T3.PORTFOLIO_ID and T3.HODING_TYPE='03' LEFT JOIN (SELECT DEAL.TOTLE_TRADE_ID, DEALADD.PORTFOLIO_ID, SUM(NVL(DEALADD.REG_DATE_AMT,0)) REG_DATE_AMT FROM TRD_PRODUCT_DEAL_ADD DEALADD LEFT JOIN TRD_PRODUCT_DEAL DEAL ON DEALADD.TRADE_ID = DEAL.TRADE_ID GROUP BY DEAL.TOTLE_TRADE_ID, DEALADD.PORTFOLIO_ID ) DEALADD ON DEALADD.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID LEFT JOIN (SELECT TOTLE_TRADE_ID , regist_org FROM TRD_PRODUCT_DEAL GROUP BY TOTLE_TRADE_ID , regist_org ) ORG ON ORG.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= DECODE(DEAL.BUSI_TYPE,'01',NVL(deal.counter_id,assetcounter.COUNTER_ID),DECODE(DEAL.PS,'T22',mst.customer_id,'T23',mst.customer_id,'T38',mst.customer_id,decode(TOTALDEAL.PS,'T09',mst.customer_id,deal.counter_id))) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= DECODE(DEAL.BUSI_TYPE,'01',NVL(deal.counter_id,assetcounter.COUNTER_ID),DECODE(DEAL.PS,'T22',mst.customer_id,'T23',mst.customer_id,'T38',mst.customer_id,decode(TOTALDEAL.PS,'T09',mst.customer_id,deal.counter_id)))
WHERE 1=1 /***添加还本不带息拆分数据***/ AND EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID and (deal.BUSI_TYPE in( '03','01') or (DEAL.BUSI_TYPE = '37' and DEAL.FINPROD_TYPE2 = 'F07')) /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ /**TG_BUSI_TYPE141先不处理，下面一并处理*/ and (A.TG_BUSI_TYPE!='141' OR A.TG_BUSI_TYPE IS NULL) and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND AD.PORTFOLIO_ID =DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') AND NVL(AD.UPDATE_TIME,AD.CREATE_TIME) > #{interfDate, jdbcType=TIMESTAMP} AND EXISTS (SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = a.TRADE_ID ) ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEPOASSET.UPDATE_TIME,DEPOASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ASSETCOUNTER.UPDATE_TIME > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*回购交易*/ union all SELECT NULL TRADE_SEQNO, DEAL.TRADE_ID TRADE_ID, DECODE(DEAL.FINPROD_TYPE2,'F02','09','F03','10','F04','11','F05','12') INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, deal.TRADE_AMT AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DEAL.SHARE_AMT NUM, DECODE(DEAL.FINPROD_TYPE2,'F02',DECODE(DEAL.PS,'T01','06','T02','08','T22','10','T23','08'), 'F03',DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07'), 'F04',DECODE(DEAL.PS,'T01','06','T02','08','T22','10','T23','08'), 'F05',DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07')) CUR_ASSET_TYPE, DECODE(DEAL.FINPROD_TYPE2,'F02',DECODE(DEAL.PS,'T22','付息','T23','到期'), 'F03',DECODE(DEAL.PS,'T22','收息','T23','到期'), 'F04',DECODE(DEAL.PS,'T22',DECODE(TOTALDEAL.PS,'T08','部分到期-付息','T07','付息'),'T23',DECODE(TOTALDEAL.PS,'T08','部分到期','T07','到期')), 'F05',DECODE(DEAL.PS,'T22',DECODE(TOTALDEAL.PS,'T08','部分到期-收息','T07','收息'),'T23',DECODE(TOTALDEAL.PS,'T08','部分到期','T07','到期'))) CUR_ASSETDET_TYPE, DEAL.SETTLE_DATE DEALDATE, DECODE(DEAL.PS,'T22',DEPOASSET.counter_id,'T23',DEPOASSET.counter_id,deal.counter_id) TRADE_COUNTER,/*资产交易对手*/ null UNIT_PRICE_FULL, NULL UNIT_PRICE_NET, DEPOASSET.INT_RATE END_RATE, DEAL.TRADE_ID CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEPOASSET.UPDATE_TIME,DEPOASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(ASSETCOUNTER.UPDATE_TIME,to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ null faceValue,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01')) DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT DEPOASSET ON DEAL.FINPROD_ID = DEPOASSET.FINPROD_ID and DEPOASSET.branch = 0 LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN ASSET_COUNTER ASSETCOUNTER/*资产交易对手*/ on assetcounter.asset_id = DEAL.FINPROD_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= DECODE(DEAL.PS,'T22',DEPOASSET.counter_id,'T23',DEPOASSET.counter_id,deal.counter_id) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= DECODE(DEAL.PS,'T22',DEPOASSET.counter_id,'T23',DEPOASSET.counter_id,deal.counter_id)
WHERE 1=1 and deal.BUSI_TYPE in( '04','05') /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEPOASSET.UPDATE_TIME,DEPOASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ASSETCOUNTER.UPDATE_TIME > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*基金资产*/ union all SELECT NULL TRADE_SEQNO, DEAL.TRADE_ID TRADE_ID, DECODE(FUNDASSET.PROFIT_TYPE,'01','14','03','13') INVEST_VARIETY, /*投资品种根据收益类型分类*/ DECODE(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE, /*投资目的 枚举值对应待处理TODO*/ NULL PROD_ID, /*取自从属表*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, decode(deal.ps,'T01',deal.prin_amt,'T11',deal.int_amt,'T12',deal.int_amt,NVL(DEAL.TRADE_AMT, 0)) AMT, NULL CNY_AMT, /*折算后人民币在街口中单独处理*/ DEAL.SHARE_AMT NUM, DECODE(FUNDASSET.PROFIT_TYPE,'01',DECODE(DEAL.PS,'T01','01','T02','02','T05','01','T64','01','T18','01','T19','02','T63','02','T12','01','T11','09'),'03',DECODE(DEAL.PS,'T01','01','T02','02','T05','01','T64','01','T18','01','T19','02','T63','02','T12','01','T11','09','C3','01','C6','02')) CUR_ASSET_TYPE, NULL CUR_ASSETDET_TYPE, DEAL.SETTLE_DATE DEALDATE, decode(deal.ps,'T22',custinfo.CUSTOMER_NAME,'T23',custinfo.CUSTOMER_NAME,'T11',custinfo.CUSTOMER_NAME,'T12',custinfo.CUSTOMER_NAME,'C3',custinfo.CUSTOMER_NAME,'C6',custinfo.CUSTOMER_NAME,DEAL.COUNTER_ID) TRADE_COUNTER, /*到期收息的对手方要为空*/ ROUND(DECODE(FUNDASSET.PROFIT_TYPE,'03',DECODE(DEAL.PS,'T01',1,'T02',1,'T05',1,'T64',1,'T18',1,'T19',1,'T63',1,'T12',1, 'C3', 1, 'C6', 1),'01',DECODE(DEAL.PS,'T01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T02',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T05',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T64',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T18',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T19',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T63',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T11',NULL,'T12',decode(nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT),0,0,DEAL.INT_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT)), 'C3', 1, 'C6', 1)),4) UNIT_PRICE_FULL, ROUND(DECODE(FUNDASSET.PROFIT_TYPE,'03',DECODE(DEAL.PS,'T01',1,'T02',1,'T05',1,'T64',1,'T18',1,'T19',1,'T63',1,'T12',1, 'C3', 1, 'C6', 1),'01',DECODE(DEAL.PS,'T01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.prin_amt/DEAL.SHARE_AMT),'T02',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T05',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T64',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T18',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T19',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T63',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT),'T11',NULL,'T12',decode(nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT),0,0,DEAL.INT_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT)), 'C3', 1, 'C6', 1)),4) UNIT_PRICE_NET, NULL END_RATE, nvl(sqdeal.F_TRADE_ID, DEAL.TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE, /*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, DECODE(NVL(DEAL.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE, /*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ /*有效状态默认有效*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(FUNDASSET.UPDATE_TIME,FUNDASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, /*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ NULL FACEVALUE, /*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T05','12','T18','12','T19','15','T12','05','T11','20','T64','12','T63','15','C3','08','C6','09') DEALTYPE /*收息具体类型在后续判断*/ , deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, DEALADD.REG_DATE_AMT INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID /* ASSETPOSITION.AMOUNT INTPAYAMT */ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT FUNDASSET ON DEAL.FINPROD_ID = FUNDASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO custinfo on FUNDASSET.MANAGER = custinfo.CUSTOMER_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join TRD_PRODUCT_DEAL sqdeal on sqdeal.TRADE_ID=DEAL.B_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,'C3',custinfo.CUSTOMER_ID,'C6',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,'C3',custinfo.CUSTOMER_ID,'C6',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID)
WHERE 1 =1 AND DEAL.BUSI_TYPE IN( '06','07') /*过滤货基中的计划类资产净值型*/ and deal.FINPROD_TYPE2 = 'F06' /*只取确认数据*/ AND DEAL.PS IN ('T01','T02','T05','T18','T19','T11','T12','T63','T64', 'C3', 'C6') /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(FUNDASSET.UPDATE_TIME,FUNDASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*债权类、权益类(项目)资产交易 - 非还本不带息*/ union all SELECT NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '15' INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, deal.trade_amt AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ decode(deal.ps,'T22',decode(totaldeal.ps,'T09',TOTALDEALPA.REMAIN_PRIN_AMT,TOTALDEAL.SHARE_AMT),'T23',TOTALDEAL.SHARE_AMT,DEAL.SHARE_AMT) NUM,
DECODE(DEAL.PS,'T01','01','T02','02','T22',DECODE(TOTALDEAL.PS,'T08','09','T09','09','T07','09'),'T23',DECODE(TOTALDEAL.PS,'T08','02','T07','02')) CUR_ASSET_TYPE,/*中间还本的利息需统计成11其他收入*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08','部分到期-收息','T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08','部分到期','T07','到期')) CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, decode(deal.ps,'T22',custinfo.CUSTOMER_NAME,'T23',custinfo.CUSTOMER_NAME,'T11',custinfo.CUSTOMER_NAME,'T12',custinfo.CUSTOMER_NAME,DEAL.COUNTER_ID) TRADE_COUNTER,/*到期收息的对手方要为空*/ DECODE(DEAL.PS,'T01',DEAL.UNIT_FPRICE,'T02',DEAL.UNIT_FPRICE,'T23',100) UNIT_PRICE_FULL, DECODE(DEAL.PS,'T01',DEAL.UNIT_CPRICE,'T02',DEAL.UNIT_CPRICE,'T23',decode(TOTALDEAL.SHARE_AMT,0,0,null,0,DEAL.trade_amt / TOTALDEAL.SHARE_AMT * 100)) UNIT_PRICE_NET, DECODE(DEAL.PS,'T01',DEAL.YIELD,'T02',DEAL.YIELD) END_RATE, nvl(PROJECTASSET.CONTRACT_NO,DEAL.TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(DEAL.IS_CANCEL, 'Y', 'D', 'E') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ NULL FACEVALUE,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01')) DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO custinfo on PROJECTASSET.FINANCIER = custinfo.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID)
WHERE 1=1 /*过滤项目类资产*/ AND DEAL.BUSI_TYPE in ('09', '37') AND DEAL.FINPROD_TYPE2 = 'F18' /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV'
/***非还本不带息数据筛选***/ AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = deal.TRADE_ID ) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP})
/*债权类、权益类(项目)资产交易 - 还本不带息*/ union all SELECT NULL TRADE_SEQNO, deal.TOTLE_TRADE_ID TRADE_ID, '15' INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ ORG.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, decode(deal.ps,'T23',totaldeal.trade_amt,DEAL.TRADE_AMT) AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ decode(deal.ps,'T22',decode(totaldeal.ps,'T09',TOTALDEALPA.REMAIN_PRIN_AMT,TOTALDEAL.SHARE_AMT),'T23',TOTALDEAL.SHARE_AMT,DEAL.SHARE_AMT) NUM, DECODE(DEAL.PS,'T01','01','T02','02','T22',DECODE(TOTALDEAL.PS,'T08','09','T09','09','T07','09'),'T23',DECODE(TOTALDEAL.PS,'T08','02','T07','02')) CUR_ASSET_TYPE,/*中间还本的利息需统计成11其他收入*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08','部分到期-收息','T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08','部分到期','T07','到期')) CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, decode(deal.ps,'T22',custinfo.CUSTOMER_NAME,'T23',custinfo.CUSTOMER_NAME,'T11',custinfo.CUSTOMER_NAME,'T12',custinfo.CUSTOMER_NAME,DEAL.COUNTER_ID) TRADE_COUNTER,/*到期收息的对手方要为空*/ DECODE(DEAL.PS,'T01',DEAL.UNIT_FPRICE,'T02',DEAL.UNIT_FPRICE,'T23',100) UNIT_PRICE_FULL, ROUND(DECODE(DEAL.PS,'T01',DEAL.UNIT_CPRICE,'T02',DEAL.UNIT_CPRICE,'T23',decode(TOTALDEAL.SHARE_AMT,0,0,null,0,DEAL.trade_amt / TOTALDEAL.SHARE_AMT * 100)),4) UNIT_PRICE_NET, DECODE(DEAL.PS,'T01',DEAL.YIELD,'T02',DEAL.YIELD) END_RATE, nvl(PROJECTASSET.CONTRACT_NO,DEAL.TOTLE_TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.P_TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ NULL FACEVALUE,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01')) DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL REVDL ON deal.TOTLE_TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO custinfo on PROJECTASSET.FINANCIER = custinfo.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN ( SELECT DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID,sum(nvl(DEALADD.REG_DATE_AMT,0)) REG_DATE_AMT FROM TRD_PRODUCT_DEAL_ADD DEALADD LEFT JOIN TRD_PRODUCT_DEAL DEAL ON DEALADD.TRADE_ID = DEAL.TRADE_ID group by DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID) DEALADD ON DEALADD.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID LEFT JOIN ( SELECT TOTLE_TRADE_ID ,regist_org FROM TRD_PRODUCT_DEAL GROUP BY TOTLE_TRADE_ID ,regist_org ) ORG ON ORG.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID)
WHERE 1=1 /***还本不带息数据筛选***/ AND EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID /*过滤项目类资产*/ AND A.BUSI_TYPE in ('09', '37') AND A.FINPROD_TYPE2 = 'F18' /*只接入原始交易数据*/ /*AND A.TRADE_STATUS = '01'*/ and nvL(A.p_trade_id,'NOREV') = 'NOREV' AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') /**TG_BUSI_TYPE141先不处理，下面一并处理*/ and (A.TG_BUSI_TYPE!='141' OR A.TG_BUSI_TYPE IS NULL) AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = a.TRADE_ID ) ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}
or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP})
/*增值税缴纳*/ union all select NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '22' INVEST_VARIETY,/*投资品种,营改增*/ deal.INV_AIM INVEST_TYPE,/*投资目的 枚举值对应待处理*/ null PROD_ID,/*产品代码*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ deal.FINPROD_ID ASSET_CODE,/*行内资产负债编码*/ deal.CCY CCY,/*币种*/ deal.trade_AMT AMT,/*发生金额*/ null CNY_AMT,/*折算人民币*/ 0 NUM,/*数量*/ '12' CUR_ASSET_TYPE,/*资金流动类型*/ '增值税缴纳' CUR_ASSETDET_TYPE,/*资金流动类型说明*/ deal.SETTLE_DATE DEALDATE,/*交易日期*/ null TRADE_COUNTER,/*交易对手*/ null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, deal.TRADE_ID CONTRACT_CODE, deal.REMARK REMARK, null CHL_CPCT_ID, ' 04' TRADE_TYPE,/*其他交易*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, NULL BASIS, NULL FACEVALUE,/*面值*/ '22' DEALTYPE/*交易类型：营改增缴纳*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,'' P_TYPE_TWO /*人行二级分类*/ from TRD_PRODUCT_DEAL deal LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD dealadd on dealadd.TRADE_ID = deal.TRADE_ID where 1= 1 and deal.BUSI_TYPE = '16' /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*通道费用交易*/ union all select NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '16' INVEST_VARIETY,/*投资品种,通道费用支付*/ deal.INV_AIM INVEST_TYPE,/*投资目的 枚举值对应待处理*/ null PROD_ID, deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ null ASSET_CODE,/*行内资产负债编码*/ deal.CCY CCY,/*币种*/ deal.trade_AMT AMT,/*发生金额*/ null CNY_AMT,/*折算人民币*/ 0 NUM,/*数量*/ '12' CUR_ASSET_TYPE,/*资金流动类型*/ '投资费用支出' CUR_ASSETDET_TYPE,/*资金流动类型说明*/ deal.TRADE_DATE DEALDATE,/*交易日期*/ custinfo.CUSTOMER_NAME TRADE_COUNTER,/*交易对手*/ null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, deal.TRADE_ID CONTRACT_CODE, deal.REMARK REMARK, null CHL_CPCT_ID, '06' TRADE_TYPE,/*通道费用交易*/ NULL CHL_AGRT_NAME, '02' IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, GREATEST(NVL(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), nvl(NVL(deal.UPDATE_TIME,deal.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(info.UPDATE_TIME,info.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, NULL BASIS, NULL FACEVALUE,/*面值*/ '16' DEALTYPE/*交易类型：通道费用支付*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ from TRD_PRODUCT_DEAL deal LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID left join fin_product info on info.FINPROD_ID = deal.CHL_ID left join MST_CUSTOMER_INFO custinfo on info.manager = custinfo.CUSTOMER_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=custinfo.CUSTOMER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=custinfo.CUSTOMER_ID
WHERE 1 =1 and deal.finprod_type2 = 'B09'/*金融产品分类（投管分类）*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND(NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} OR NVL(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*投资费用交易*/ union all select NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '17' INVEST_VARIETY,/*投资品种,通道费用支付*/ null INVEST_TYPE,/*投资目的 枚举值对应待处理*/ tda.PORTFOLIO_ID PROD_ID, deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ null ASSET_CODE,/*行内资产负债编码*/ deal.CCY CCY,/*币种*/ deal.trade_AMT AMT,/*发生金额*/ null CNY_AMT,/*折算人民币*/ 0 NUM,/*数量*/ '12' CUR_ASSET_TYPE,/*资金流动类型*/ decode(TTF.FEE_TYPE,'B05','佣金','B06','交易手续费','B08','结算服务费') CUR_ASSETDET_TYPE,/*资金流动类型说明*/ deal.TRADE_DATE DEALDATE,/*交易日期*/ NULL TRADE_COUNTER,/*交易对手*/ null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, deal.TRADE_ID CONTRACT_CODE, deal.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '04' TRADE_TYPE,/*通道费用交易*/ NULL CHL_AGRT_NAME, '02' IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, GREATEST(NVL(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), nvl(NVL(deal.UPDATE_TIME,deal.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(info.UPDATE_TIME,info.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, NULL BASIS, NULL FACEVALUE,/*面值*/ '06' DEALTYPE/*交易类型：通道费用支付*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,DECODE(PARTY.COUNTER_TYPE,'05','C0500',nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO)) P_TYPE_TWO/*人行二级分类*/ from TRD_PRODUCT_DEAL deal LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID left join TRD_PRODUCT_DEAL_ADD tda on tda.TRADE_ID=deal.TRADE_ID LEFT JOIN TRD_TRADE_FEE_DETAIL TTF ON TTF.TRADE_ID=deal.TRADE_ID left join fin_product info on info.FINPROD_ID = deal.CHL_ID left join MST_CUSTOMER_INFO custinfo on info.manager = custinfo.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TPD ON TPD.TOTLE_TRADE_ID=deal.TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=custinfo.CUSTOMER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=custinfo.CUSTOMER_ID
WHERE 1 =1 and deal.finprod_type2 = 'C11'/*金融产品分类（投管分类）*/ and TPD.TG_BUSI_TYPE='142' and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND(NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} OR NVL(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} OR NVL(TPD.UPDATE_TIME,TPD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP})
/*自定义现金流*/ union all select NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '21' INVEST_VARIETY,/*投资品种,自定义现金流*/ deal.INV_AIM INVEST_TYPE,/*投资目的 枚举值对应待处理*/ null PROD_ID,/*产品代码*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ deal.FINPROD_ID ASSET_CODE,/*行内资产负债编码*/ deal.CCY CCY,/*币种*/ deal.trade_amt AMT,/*发生金额*/ null CNY_AMT,/*折算人民币*/ nvl(deal.trade_amt,0) NUM,/*数量*/ DECODE(deal.PS,'T99','12','T98','11' ) CUR_ASSET_TYPE,/*资金流动类型*/ '无' CUR_ASSETDET_TYPE,/*资金流动类型说明*/ deal.SETTLE_DATE DEALDATE,/*交易日期*/ deal.COUNTER_ID TRADE_COUNTER,/*交易对手*/ null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, deal.TRADE_ID CONTRACT_CODE, deal.REMARK REMARK, null CHL_CPCT_ID, '04' TRADE_TYPE,/*其他交易*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, nvL(deal.UPDATE_TIME,deal.CREATE_TIME) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, NULL BASIS, NULL FACEVALUE,/*面值*/ DECODE(deal.PS,'T99','13','T98','14' ) DEALTYPE/*交易类型：13自定义现金流收入;14自定义现金流支出*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ from TRD_PRODUCT_DEAL deal LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=deal.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=deal.COUNTER_ID
where deal.finprod_type2 = 'F23' /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*理财托管户收息确认*/ union all select NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '19' INVEST_VARIETY,/*19理财托管户收息;20其他账户收息*/ deal.INV_AIM INVEST_TYPE,/*投资目的 枚举值对应待处理*/ null PROD_ID,/*产品代码*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ deal.FINPROD_ID ASSET_CODE,/*行内资产负债编码*/ deal.CCY CCY,/*币种*/ deal.trade_amt AMT,/*发生金额*/ null CNY_AMT,/*折算人民币*/ 0 NUM,/*数量*/ '11' CUR_ASSET_TYPE,/*资金流动类型*/ '理财账户收息' CUR_ASSETDET_TYPE,/*资金流动类型说明*/ deal.SETTLE_DATE DEALDATE,/*交易日期*/ STI.BANK_DEP TRADE_COUNTER,/*交易对手*/ null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, deal.TRADE_ID CONTRACT_CODE, NVL(deal.REMARK,'无') REMARK, null CHL_CPCT_ID, '04' TRADE_TYPE,/*其他交易*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, nvL(deal.UPDATE_TIME,deal.CREATE_TIME) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, NULL BASIS, NULL FACEVALUE,/*面值*/ '07' DEALTYPE/*交易类型：07理财托管户收息确认;11理财账户收息确认*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,'' P_TYPE_TWO /*人行二级分类*/ from TRD_PRODUCT_DEAL deal LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN STL_CAPACCT_INFO STI ON deal.FINPROD_ID = STI.ACCT_NO AND deal.CCY = STI.CCY where deal.BUSI_TYPE = '15' /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /* 增加股票和衍生品交易 add by gaojian 2019-07-19 begin */ /*股票交易*/ UNION ALL SELECT NULL TRADE_SEQNO, /*交易UUID*/ DEAL.TRADE_ID TRADE_ID, /*行内交易编码*/ '25' INVEST_VARIETY, /*投资品种*/ NULL INVEST_TYPE, /*投资类型*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ DEAL.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ DEAL.CCY CCY, /*币种*/ DECODE(DEAL.PS, 'T12', 0, NVL(DEAL.TRADE_AMT, 0)) AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ DECODE(DEAL.PS, 'T11', NVL(DEALADD.REG_DATE_AMT, 0), NVL(DEAL.SHARE_AMT, 0)) NUM, /*数量*/ CASE WHEN DEAL.PS IN ('T01', 'T46', 'T47', 'T48', 'T12') THEN '01' WHEN DEAL.PS = 'T02' THEN '02' WHEN DEAL.PS = 'T11' THEN '09' ELSE NULL END AS CUR_ASSET_TYPE, /*资金流动类型*/ CASE WHEN DEAL.PS IN ('T01', 'T02', 'T46', 'T47', 'T48', 'T12') THEN '无' WHEN DEAL.PS = 'T11' THEN '股票分红' ELSE NULL END AS CUR_ASSETDET_TYPE, /*资金流动类型说明*/ DEAL.SETTLE_DATE DEALDATE, /*交易日*/ CASE WHEN DEAL.PS IN ('T11', 'T12') THEN CUSTINFO.CUSTOMER_NAME ELSE DEAL.COUNTER_ID END AS TRADE_COUNTER, /*交易对手*/ CASE WHEN DEAL.PS IN ('T01', 'T02', 'T46', 'T47', 'T48') THEN ROUND(NVL(DEAL.TRADE_AMT, 0)/NVL(DEAL.SHARE_AMT, 1), 4) WHEN DEAL.PS = 'T12' THEN 0 ELSE NULL END AS UNIT_PRICE_FULL, /*单位成交价格（全价）*/ CASE WHEN DEAL.PS IN ('T01', 'T02', 'T46', 'T47', 'T48') THEN ROUND(NVL(DEAL.TRADE_AMT, 0)/NVL(DEAL.SHARE_AMT, 1), 4) WHEN DEAL.PS = 'T12' THEN 0 ELSE NULL END AS UNIT_PRICE_NET, /*单位成交价格（净价）*/ DEAL.YIELD END_RATE, /*到期收益率*/ DEAL.TRADE_ID CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ '01' TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(CUSTINFO.UPDATE_TIME,CUSTINFO.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ DECODE(DEAL.PS, 'T02', '09', 'T11', '20', 'T12', '05', '08') DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO CUSTINFO ON PROJECTASSET.ISSUER = CUSTINFO.CUSTOMER_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID =(CASE WHEN DEAL.PS IN ('T11', 'T12') THEN CUSTINFO.CUSTOMER_ID ELSE DEAL.COUNTER_ID END) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=(CASE WHEN DEAL.PS IN ('T11', 'T12') THEN CUSTINFO.CUSTOMER_ID ELSE DEAL.COUNTER_ID END)
WHERE DEAL.FINPROD_TYPE2 = 'F10' AND (NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /*买入利率互换交易*/ UNION ALL SELECT NULL TRADE_SEQNO, /*交易UUID*/ DEAL.TRADE_ID TRADE_ID, /*行内交易编码*/ '26' INVEST_VARIETY, /*投资品种*/ NULL INVEST_TYPE, /*投资类型*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ FTP.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ DEAL.CCY CCY, /*币种*/ DECODE(DEAL.PS, 'T01', 0, NVL(DEAL.TRADE_AMT, 0)) AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ /*NVL(DEAL.SHARE_AMT, 0) NUM, 数量*/ NVL(TOTAL.REMAIN_PRIN, 0) NUM, DECODE (DEAL.PS, 'T01', '01', 'T07', '02', 'T98', '09', 'T99', '10') CUR_ASSET_TYPE, /*资金流动类型*/ CASE WHEN DEAL.PS = 'T98' THEN '利率互换利息收入' WHEN DEAL.PS = 'T99' THEN '利率互换利息支出' ELSE '无' END AS CUR_ASSETDET_TYPE, /*资金流动类型说明*/ DEAL.SETTLE_DATE DEALDATE, /*交易日*/ DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_NAME) TRADE_COUNTER, /*交易对手*/ CASE WHEN DEAL.PS IN ('T01', 'T02') THEN 0 ELSE NULL END AS UNIT_PRICE_FULL, /*单位成交价格（全价）*/ CASE WHEN DEAL.PS IN ('T01', 'T02') THEN 0 ELSE NULL END AS UNIT_PRICE_NET, /*单位成交价格（净价）*/ /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ /*DEAL.YIELD END_RATE, 到期收益率*/ NULL END_RATE, /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/
DEAL.TRADE_ID CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ '01' TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(CUSTINFO.UPDATE_TIME,CUSTINFO.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ DECODE(DEAL.PS, 'T01', '08', 'T02', '09', '23') DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON DEAL.TOTLE_TRADE_ID=TOTAL.TOTLE_TRADE_ID /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.FINPROD_ID = FTP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY CUSTINFO ON FTP.COUNTER_ID = CUSTINFO.COUNTER_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_ID)
WHERE DEAL.FINPROD_TYPE2 = 'F14' AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ and deal.ps not in ('T01','T07') /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ /*债券借贷交易*/ UNION ALL SELECT NULL TRADE_SEQNO, /*交易UUID*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' ELSE DEAL.TRADE_ID END AS TRADE_ID, /*行内交易编码*/ '27' INVEST_VARIETY, /*投资品种*/ NULL INVEST_TYPE, /*投资类型*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ FTP.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ DEAL.CCY CCY, /*币种*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN 0 ELSE NVL(DEAL.TRADE_AMT, 0) END AS AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ DEAL.SHARE_AMT NUM, /*数量*/ CASE WHEN DEAL.PS = 'T01' THEN '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '02' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F29' THEN '10' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F30' THEN '09' ELSE NULL END AS CUR_ASSET_TYPE, /*资金流动类型*/ CASE WHEN DEAL.PS = 'T01' THEN '无' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '无' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F29' THEN '债券借贷费用支出' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F30' THEN '债券借贷费用收入' ELSE NULL END AS CUR_ASSETDET_TYPE, /*资金流动类型说明*/ DEAL.SETTLE_DATE DEALDATE, /*交易日*/ DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_NAME) TRADE_COUNTER, /*交易对手*/ CASE WHEN DEAL.PS = 'T01' THEN 0 WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN 0 ELSE NULL END AS UNIT_PRICE_FULL, /*单位成交价格（全价）*/ CASE WHEN DEAL.PS = 'T01' THEN 0 WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN 0 ELSE NULL END AS UNIT_PRICE_NET, /*单位成交价格（净价）*/ DEAL.YIELD END_RATE, /*到期收益率*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' WHEN DEAL.PS = 'T01' THEN nvl(DEAL.F_TRADE_ID,DEAL.TRADE_ID) ELSE DEAL.TRADE_ID END AS CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN '04' ELSE '01' END AS TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(CUSTINFO.UPDATE_TIME,CUSTINFO.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE, /*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '09' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN '10' ELSE '08' END AS DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TEMP_BOND_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.FINPROD_ID = FTP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY CUSTINFO ON FTP.COUNTER_ID = CUSTINFO.COUNTER_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_ID)
WHERE nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) UNION ALL /*可转债申购*/ select NULL TRADE_SEQNO , /* 交易UUID */ deal.TRADE_ID TRADE_CODE , /* 行内交易编码*/ '01' INVEST_VARIETY , /* 投资品种 */ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE ,/*投资类型*/ DEALADD.PORTFOLIO_ID PROD_ID , /*产品代码 */ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE,/*行内资产/负债编码 关联金融产品表得到市场代码 */ DEAL.CCY CCY, /* 币种 参考数据字典：CURRENCY_CHB */ DEAL.FPRICE_AMT AMT , /*发生金额 */ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DEAL.SHARE_AMT*100 NUM, /*数量 */ '01' CUR_ASSET_TYPE , /*资金流动类型 */ '无' CUR_ASSETDET_TYPE, /* 资金流动类型说明 */ DEAL.SETTLE_DATE DEALDATE, /*交易日*/ DEAL.COUNTER_ID TRADE_COUNTER, /*交易对手*/ 100 UNIT_PRICE_FULL , /* 单位成交价格（全价）*/ 100 UNIT_PRICE_NET, /*单位成交价格（净价）*/ DEAL.YIELD END_RATE ,/* 到期收益率 */ nvl(DEAL.F_TRADE_ID,DEAL.TRADE_ID) CONTRACT_CODE , /*成交编号/合同号 */ null REMARK ,/* 备注*/ null CHL_CPCT_ID , /*通道代码 */ '01' TRADE_TYPE,/* 交易类型 */ null CHL_AGRT_NAME ,/*通道名称*/ '02' IS_UNDER_TRADE , /*是否底层交易流水 01 是/ 02 否 */ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*数据状态 D 删除 A 待处理 E 有效*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ deal.CREATE_USER CREATE_USER, /*创建人*/ deal.CREATE_TIME CREATE_TIME, /* 创建时间 */ deal.UPDATE_USER UPDATE_USER, /* 更新人 */ greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME,/*更新时间*/ NULL STATUS_DATE,/*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ DEAL.PAR_VALUE FACEVALUE ,/*面值 */ '08' DEALTYPE , /*交易类型 */ deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, null F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DEAL.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DEAL.COUNTER_ID
where 1=1 and deal.PS='T05' and deal.finprod_type2='F01' and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) AND nvl(deal.p_trade_id,'NOREV')='NOREV'/*不取撤销交易*/ UNION ALL /*债转股(债券卖出)*/ select NULL TRADE_SEQNO ,/*交易UUID*/ DEAL.TRADE_ID||'01' TRADE_CODE,/*行内交易编码 */ '01' INVEST_VARIETY ,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资类型投资目的 枚举值对应待处理TODO*/ DEALADD.PORTFOLIO_ID PROD_ID , /* 产品代码 */ deal.regist_org REGIST_BANK_CODE,/*发行机构代码登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE , /*行内资产/负债编码 */ DEAL.CCY CCY ,/*币种 */ /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ BARTER.PRIN_AMT AMT ,/*发生金额 */ /* DEAL.SHARE_AMT*100-DEAL.TRADE_AMT AMT,发生金额 */ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DEAL.SHARE_AMT*100 NUM ,/*数量 */ '02' CUR_ASSET_TYPE,/*资金流动类型 */ '无' CUR_ASSETDET_TYPE,/*资金流动类型说明*/ DEAL.TRADE_DATE DEALDATE, /*交易日 */ /*DEAL.SETTLE_DATE DEALDATE, 交易日 */ /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ DEAL.COUNTER_ID TRADE_COUNTER, /*交易对手 */ ROUND((DEAL.SHARE_AMT*100-DEAL.TRADE_AMT)/DEAL.SHARE_AMT,4) UNIT_PRICE_FULL ,/*单位成交价格（全价）*/ ROUND((DEAL.SHARE_AMT*100-DEAL.TRADE_AMT)/DEAL.SHARE_AMT,4) UNIT_PRICE_NET ,/*单位成交价格（净价） */ NULL END_RATE ,/*到期收益率 */ DEAL.TRADE_ID||'01' CONTRACT_CODE ,/*成交编号/合同号 */ NULL REMARK ,/*备注 */ NULL CHL_CPCT_ID ,/* 通道代码 */ '01' TRADE_TYPE ,/* 交易类型 */ NULL CHL_AGRT_NAME,/* 通道名称 */ '02' IS_UNDER_TRADE ,/*是否底层交易流水 01 是/ 02 否 */ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*数据状态 D 删除 A 待处理 E 有效 */ NULL ORG_CODE, /*机构代码 */ NULL DEPT_CODE, /*部门代码 */ deal.CREATE_USER CREATE_USER, /*创建人 */ deal.CREATE_TIME CREATE_TIME, /* 创建时间 */ deal.UPDATE_USER UPDATE_USER, /* 更新人 */ greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME,/*更新时间*/ NULL STATUS_DATE,/*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*利率 */ NULL BASIS , /*计息基础 */ DEAL.PAR_VALUE FACEVALUE,/*面值 */ '09' DEALTYPE ,/*交易类型 */ deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, null F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ left join TRD_FIN_PRODUCT_BARTER BARTER on deal.TRADE_ID=BARTER.TRADE_ID /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DEAL.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DEAL.COUNTER_ID
where 1=1 and BARTER.TRADE_ID is not null /*存了一条股票的记录*/ and deal.PS='T49' and deal.finprod_type2='F01' and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) UNION ALL /*-债转股(股票买入)*/ select NULL TRADE_SEQNO ,/*交易UUID */ DEAL.TRADE_ID||'02' TRADE_CODE,/*行内交易编码 */ '25' INVEST_VARIETY ,/*投资品种 */ NULL INVEST_TYPE,/*投资类型投资目的 枚举值对应待处理TODO*/ DEALADD.PORTFOLIO_ID PROD_ID , /* 产品代码 */ deal.regist_org REGIST_BANK_CODE,/*发行机构代码登记银行编码*/ /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ secASSET.Finprod_Id ASSET_CODE , /*行内资产/负债编码 */ /*DEAL.FINPROD_ID ASSET_CODE , 行内资产/负债编码 */ secASSET.CCY CCY ,/*币种 */ BARTER.PRIN_AMT AMT ,/*发生金额 */ /* DEAL.SHARE_AMT*100-DEAL.TRADE_AMT AMT,发生金额 */ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ BARTER.SHARE_AMT NUM ,/*数量*/ '01' CUR_ASSET_TYPE,/*资金流动类型 */ '无' CUR_ASSETDET_TYPE,/*资金流动类型说明 */ DEAL.TRADE_DATE DEALDATE, /*交易日 */ /*DEAL.SETTLE_DATE DEALDATE, 交易日 */ DEAL.COUNTER_ID TRADE_COUNTER, /*交易对手 */
BARTER.UNIT_CPRICE UNIT_PRICE_FULL ,/*单`位成交价格（全价）*/ BARTER.UNIT_CPRICE UNIT_PRICE_NET ,/*单位成交价格（净价） */ /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ NULL END_RATE ,/*到期收益率 */ DEAL.TRADE_ID||'02' CONTRACT_CODE ,/*成交编号/合同号 */ NULL REMARK ,/*备注 */ NULL CHL_CPCT_ID ,/* 通道代码 */ '01' TRADE_TYPE ,/* 交易类型 */ NULL CHL_AGRT_NAME,/* 通道名称 */ '02' IS_UNDER_TRADE ,/*是否底层交易流水 01 是/ 02 否 */ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*数据状态 D 删除 A 待处理 E 有效 */ NULL ORG_CODE, /*机构代码 */
NULL DEPT_CODE, /*部门代码 */ deal.CREATE_USER CREATE_USER, /*创建人 */ deal.CREATE_TIME CREATE_TIME, /* 创建时间 */ deal.UPDATE_USER UPDATE_USER, /* 更新人 */ greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME,/*更新时间*/ NULL STATUS_DATE,/*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*利率 */ NULL BASIS , /*计息基础 */ NULL FACEVALUE,/*面值 */ '08' DEALTYPE ,/*交易类型 */ deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, null F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL left join TRD_FIN_PRODUCT_BARTER BARTER on deal.TRADE_ID=BARTER.TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on BARTER.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DEAL.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DEAL.COUNTER_ID
where 1=1 and BARTER.TRADE_ID is not null /*存了一条股票的记录*/ and deal.PS='T49' and deal.finprod_type2='F01' and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) UNION ALL /*债转股(投资收益)*/ select NULL TRADE_SEQNO ,/*交易UUID */ DEAL.TRADE_ID||'03' TRADE_CODE,/*行内交易编码 */ '01' INVEST_VARIETY ,/*投资品种*/ null INVEST_TYPE,/*投资类型 */ DEALADD.PORTFOLIO_ID PROD_ID , /* 产品代码*/ deal.regist_org REGIST_BANK_CODE,/*发行机构代码登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE , /*行内资产/负债编码 */ DEAL.CCY CCY ,/*币种 */ DEAL.TRADE_AMT AMT ,/*发生金额 */ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DEALADD.SPO_SHARE_NUM NUM ,/*数量 */ '09' CUR_ASSET_TYPE,/*资金流动类型*/ '零股折算现金' CUR_ASSETDET_TYPE,/*资金流动类型说明 */ DEAL.SETTLE_DATE DEALDATE, /*交易日 */ DEAL.COUNTER_ID TRADE_COUNTER, /*交易对手 */ NULL UNIT_PRICE_FULL ,/*单位成交价格（全价）*/ NULL UNIT_PRICE_NET ,/*单位成交价格（净价）*/ NULL END_RATE ,/*到期收益率 */ DEAL.TRADE_ID||'03' CONTRACT_CODE ,/*成交编号/合同号 */ NULL REMARK ,/*备注 */ NULL CHL_CPCT_ID ,/* 通道代码 */ '01' TRADE_TYPE ,/* 交易类型 */ NULL CHL_AGRT_NAME,/* 通道名称 */ '02' IS_UNDER_TRADE ,/*是否底层交易流水 01 是/ 02 否 */ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*数据状态 D 删除 A 待处理 E 有效 */ NULL ORG_CODE, /*机构代码 */ NULL DEPT_CODE, /*部门代码 */ deal.CREATE_USER CREATE_USER, /*创建人*/ deal.CREATE_TIME CREATE_TIME, /* 创建时间*/ deal.UPDATE_USER UPDATE_USER, /* 更新人 */ greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME,/*更新时间*/ NULL STATUS_DATE,/*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*利率 */ NULL BASIS , /*计息基础 */ NULL FACEVALUE,/*面值 */ '09' DEALTYPE ,/*交易类型 */ deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, null F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DEAL.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DEAL.COUNTER_ID
where 1=1 and deal.PS='T49' and DEAL.TRADE_AMT is not null and deal.finprod_type2='F01' and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*外汇放期交易*/ UNION ALL SELECT NULL TRADE_SEQNO, /*交易UUID*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' END AS TRADE_ID, /*行内交易编码*/ '28' INVEST_VARIETY, /*投资品种*/ NULL INVEST_TYPE, /*投资类型*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ FTP.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ FTP.CCY CCY, /*币种*/ 0 AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ 1 NUM, /*数量*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN '01' WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '02' THEN '02' END AS CUR_ASSET_TYPE, /*资金流动类型*/ '无' CUR_ASSETDET_TYPE, /*资金流动类型说明*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_DATE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.SETTLE_DATE END AS DEALDATE, /*交易日*/ DEAL.COUNTER_ID TRADE_COUNTER, /*交易对手*/ 0 UNIT_PRICE_FULL, /*单位成交价格（全价）*/ 0 UNIT_PRICE_NET, /*单位成交价格（净价）*/ NULL END_RATE, /*到期收益率*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' END AS CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ '01' TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')) , NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE, /*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ DECODE(DEAL.SPLIT_TYPE, '01', '08', '02', '09') DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TEMP_FES_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.FINPROD_ID = FTP.FINPROD_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DEAL.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DEAL.COUNTER_ID
WHERE nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*外汇远期交易*/ UNION ALL select * from( SELECT NULL TRADE_SEQNO, /*交易UUID*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' ELSE DEAL.TRADE_ID END AS TRADE_ID, /*行内交易编码*/ '29' INVEST_VARIETY, /*投资品种*/ 'F12' INVEST_TYPE, /*投资类型,此处实际应该为空，赋值主要是为了在代码层面作为计算发生金额的判断条件*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ FTP.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ CASE WHEN DEAL.PS = 'T01' THEN FTP.CCY WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN FTP.CCY ELSE SUBSTR(FTP.CUR_PAIR,INSTR(FTP.CUR_PAIR,'/',-1)+1) END AS CCY, /*币种*/ 0 AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN NVL(DEAL.PRIN_AMT, 0) ELSE 1 END AS NUM, /*数量*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '02' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN '09' ELSE '01' END AS CUR_ASSET_TYPE, /*资金流动类型*/ FTP.CUR_PAIR || ':' || FTP.CCY || ':' || DEAL.CCY || ':' || FTP.EXC_PS || ':' || DEAL.PS || ':' || NVL(DEAL.FPRICE_AMT, 0) || ':' || NVL(DEAL.PRIN_AMT, 0) || ':' || NVL(DEAL.UNIT_FPRICE, 1) || ':' || DEAL.DELIVERY_TYPE CUR_ASSETDET_TYPE, /*资金流动类型说明*/ DEAL.SETTLE_DATE DEALDATE, /*交易日*/ CASE WHEN DEAL.PS = 'T01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_NAME END AS TRADE_COUNTER, /*交易对手*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN NULL ELSE 0 END AS UNIT_PRICE_FULL, /*单位成交价格（全价）*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN NULL ELSE 0 END AS UNIT_PRICE_NET, /*单位成交价格（净价）*/ NULL END_RATE, /*到期收益率*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' ELSE DEAL.TRADE_ID END AS CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN '04' ELSE '01' END AS TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(MEQ.UPDATE_TIME,MEQ.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE, /*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '09' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN '10' ELSE '08' END AS DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TEMP_FEF_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.FINPROD_ID = FTP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCP ON FTP.COUNTER_ID = MCP.COUNTER_ID LEFT JOIN rate MEQ ON FTP.CUR_PAIR = MEQ.EXCHARGE_CODE left join MST_COUNTER_PARTY party on party.COUNTER_ID=(CASE WHEN DEAL.PS = 'T01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_ID END) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=(CASE WHEN DEAL.PS = 'T01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_ID END)
WHERE nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) )where to_char(dealdate,'yyyy-MM-dd')>=to_char(update_time,'yyyy-MM-dd') /*外汇掉期交易*/ UNION ALL select * from( SELECT NULL TRADE_SEQNO, /*交易UUID*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' END AS TRADE_ID, /*行内交易编码*/ '30' INVEST_VARIETY, /*投资品种*/ 'F13' INVEST_TYPE, /*投资类型,此处实际应该为空，赋值主要是为了在代码层面作为计算发生金额的判断条件*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ FTP.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN FTP.CCY WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN FTP.CCY ELSE SUBSTR(FTP.CUR_PAIR,INSTR(FTP.CUR_PAIR,'/',-1)+1) END AS CCY, /*币种*/ 0 AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN 1 WHEN DEAL.SPLIT_TYPE = '02' THEN DEAL.PRIN_AMT END AS NUM, /*数量*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '02' ELSE '09' END AS CUR_ASSET_TYPE, /*资金流动类型*/ FTP.CUR_PAIR || ':' || FTP.CCY || ':' || DEAL.CCY || ':' || FTP.EXC_PS || ':' || DEAL.PS || ':' || NVL(DEAL.FPRICE_AMT, 0) || ':' || NVL(DEAL.PRIN_AMT, 0) CUR_ASSETDET_TYPE, /*资金流动类型说明*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_DATE ELSE DEAL.SETTLE_DATE END AS DEALDATE, /*交易日*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_NAME END AS TRADE_COUNTER, /*交易对手*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN 0 ELSE NULL END AS UNIT_PRICE_FULL, /*单位成交价格（全价）*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN 0 ELSE NULL END AS UNIT_PRICE_NET, /*单位成交价格（净价）*/ NULL END_RATE, /*到期收益率*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' END AS CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN '01' WHEN DEAL.SPLIT_TYPE = '02' THEN '04' END AS TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(MEQ.UPDATE_TIME,MEQ.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(MCP.UPDATE_TIME,MCP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE, /*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN '08' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '09' ELSE '10' END AS DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TEMP_FESW_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.FINPROD_ID = FTP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCP ON FTP.COUNTER_ID = MCP.COUNTER_ID LEFT JOIN rate MEQ ON FTP.CUR_PAIR = MEQ.EXCHARGE_CODE left join MST_COUNTER_PARTY party on party.COUNTER_ID=(CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_ID END) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=(CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_ID END)
WHERE nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) )where to_char(dealdate,'yyyy-MM-dd')>=to_char(update_time,'yyyy-MM-dd') /**增加股票和衍生品交易 add by gaojian 2019-07-19 end**/ union all
SELECT DISTINCT NULL TRADE_SEQNO, DEAL.TOTLE_TRADE_ID TRADE_ID, /*DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01','04','02','03','03','05') INVEST_VARIETY,投资品种根据收益类型分类*/ CASE WHEN DEAL.FINPROD_TYPE2 = 'F01' THEN '01' WHEN DEAL.FINPROD_TYPE2 = 'F07' THEN '06' WHEN DEAL.FINPROD_TYPE2 = 'F17' THEN '03' WHEN DEAL.FINPROD_TYPE2 = 'F18' THEN '15' ELSE NULL END INVEST_VARIETY, DECODE(NVL(DEAL.INV_AIM,DEALADD.INV_AIM),'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ NULL PROD_ID,/*取自从属表*/ ORG.REGIST_ORG REGIST_BANK_CODE,/*登记银行编码*/ NVL(PLANASSET.FINPROD_ID,PLANASSETDETAIL.FINPROD_ID) ASSET_CODE, DEAL.CCY CCY, DECODE(DEAL.PS,'T01',DEAL.TRADE_AMT,'T11',DEAL.INT_AMT,'T12',DEAL.INT_AMT,'T23',TOTALDEAL.TRADE_AMT,DEAL.TRADE_AMT) AMT,/*对于计划类资产，红利再投及分红 发生金额直接取int_amt*/ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DECODE(DEAL.FINPROD_TYPE2,'F01', CASE WHEN FTPTRADE.BRANCH_TYPE='D01' THEN (CASE WHEN PLANASSETDETAIL.MDATE=FTPTRADE.MDATE THEN NVL((DEAL.PRIN_AMT/FTPTRADE.M_PRIN_AMT),0)*100 /**到期还本*/ ELSE 0 /**中间还本*/ END) ELSE 0 /**中间付息*/ END ,NVL(NVL(DEAL.SHARE_AMT,DEAL.PRIN_AMT),0) ) NUM, CASE WHEN DEAL.FINPROD_TYPE2 = 'F07' AND FPT.TYPE_6 = 'D01' THEN DECODE(DEAL.PS,'T01','05','T02','07') WHEN DEAL.FINPROD_TYPE2 = 'F07' AND FPT.TYPE_6 != 'D01' THEN DECODE(DEAL.PS,'T01','03','T02','04') ELSE DECODE(DEAL.PS,'T01','01','T02','02','T22','09','T23','02','T05','01','T19','02','T11','09','T12','01','C3','01','C06','02') END CUR_ASSET_TYPE,/*计划类资产红利再投另加一笔投资收益*/ DECODE(DEAL.PS,'T22',DECODE(TOTALDEAL.PS,'T08','部分到期-收息','T09','收息','T07','收息'),'T23',DECODE(TOTALDEAL.PS,'T08','部分到期','T07','到期'),'T11','资产分红') CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, DECODE(DEAL.PS,'T22',CUSTINFO.CUSTOMER_NAME,'T23',CUSTINFO.CUSTOMER_NAME,'T11',CUSTINFO.CUSTOMER_NAME,'T12',CUSTINFO.CUSTOMER_NAME,DEAL.COUNTER_ID) TRADE_COUNTER,/*对手方*/ ROUND(DECODE(DEAL.FINPROD_TYPE2,'F01', CASE WHEN FTPTRADE.BRANCH_TYPE='D01' THEN (CASE WHEN PLANASSETDETAIL.MDATE=FTPTRADE.MDATE THEN (DEAL.TRADE_AMT/((DEAL.PRIN_AMT/FTPTRADE.M_PRIN_AMT)*100))*100 /**到期还本*/ ELSE 0 /**中间还本*/ END ) ELSE 0 /**中间付息*/ END ,DECODE(DEAL.FINPROD_TYPE2 ,'F07',NULL, DECODE(NVL(NVL(DEAL.SHARE_AMT,DEAL.PRIN_AMT),0),0,0,DEAL.TRADE_AMT/NVL(NVL(DEAL.SHARE_AMT,DEAL.PRIN_AMT),0))*100) ),4) UNIT_PRICE_FULL, ROUND(DECODE(DEAL.FINPROD_TYPE2,'F01', CASE WHEN FTPTRADE.BRANCH_TYPE='D01' THEN (CASE WHEN PLANASSETDETAIL.MDATE=FTPTRADE.MDATE THEN (DEAL.TRADE_AMT/((DEAL.PRIN_AMT/FTPTRADE.M_PRIN_AMT)*100))*100 /**到期还本*/ ELSE 0 /**中间还本*/ END ) ELSE 0 /**中间付息*/ END ,DECODE(DEAL.FINPROD_TYPE2 ,'F07',NULL, DECODE(NVL(NVL(DEAL.SHARE_AMT,DEAL.PRIN_AMT),0),0,0,100))/*项目类计划类当数量为0时，单位净价取0，否则100*/ ),4) UNIT_PRICE_NET, DECODE(DEAL.PS,'T23',DECODE(TOTALDEAL.PS,'T07',DEAL.YIELD)) END_RATE, NVL(NVL(PLANASSET.CONTRACT_NO,PLANASSETDETAIL.CONTRACT_NO),DEAL.TOTLE_TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, DECODE(NVL(DEAL.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(DEAL.IS_CANCEL,'N','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, DEAL.CREATE_USER CREATE_USER, DEAL.CREATE_TIME CREATE_TIME, DEAL.UPDATE_USER UPDATE_USER, GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), NVL(NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), NVL(NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), NVL(NVL(CUSTINFO.UPDATE_TIME,CUSTINFO.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), NVL(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), NVL(PARTY.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.CREATE_TIME REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ NULL FACEVALUE,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',DECODE(TOTALDEAL.PS,'T08','25','T09','23','T07','02'),'T23',DECODE(TOTALDEAL.PS,'T08','24','T07','01'),'T05','12','T19','15','T11','20','T12','05','C3','04','C06','03') DEALTYPE/*收息具体类型在后续判断*/, DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, DEALADD.REG_DATE_AMT INTPAYAMT, DEAL.F_TRADE_ID F_TRADE_ID ,DECODE(PARTY.COUNTER_TYPE,'05','C0500',NVL(PARTY.P_TYPE_TWO,party2.P_TYPE_TWO)) P_TYPE_TWO/*人行二级分类*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL
LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL REVDL ON DEAL.TOTLE_TRADE_ID = REVDL.P_TRADE_ID
LEFT JOIN FIN_PRODUCT PLANASSETDETAIL ON DEAL.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID
LEFT JOIN FIN_PRODUCT PLANASSET ON PLANASSETDETAIL.P_FINPROD_ID = PLANASSET.FINPROD_ID
LEFT JOIN MST_CUSTOMER_INFO CUSTINFO ON NVL(PLANASSET.MANAGER,PLANASSETDETAIL.MANAGER) = CUSTINFO.CUSTOMER_ID
LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL ON DEAL.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID
LEFT JOIN ( SELECT DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID, SUM(NVL(DEALADD.REG_DATE_AMT,0)) REG_DATE_AMT, DEAL.INV_AIM FROM TRD_PRODUCT_DEAL_ADD DEALADD
LEFT JOIN TRD_PRODUCT_DEAL DEAL ON DEALADD.TRADE_ID = DEAL.TRADE_ID GROUP BY DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID,DEAL.INV_AIM ) DEALADD ON (DEALADD.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID OR DEAL.P_TOTLE_TRADE_ID= DEALADD.TOTLE_TRADE_ID)
LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON DEAL.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID
LEFT JOIN ( SELECT TOTLE_TRADE_ID ,REGIST_ORG FROM TRD_PRODUCT_DEAL GROUP BY TOTLE_TRADE_ID ,REGIST_ORG ) ORG ON ORG.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID
LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALREVDL ON DEAL.TOTLE_TRADE_ID = NVL(TOTALREVDL.P_TRADE_ID,TOTALREVDL.P_TOTLE_TRADE_ID)
LEFT JOIN TRD_PRODUCT_DEAL TPDEAL ON TPDEAL.TOTLE_TRADE_ID=DEAL.TOTLE_TRADE_ID OR DEAL.P_TOTLE_TRADE_ID=TPDEAL.TOTLE_TRADE_ID
INNER JOIN FIN_TRADE_PRODUCT FTPTRADE ON FTPTRADE.FINPROD_ID=TPDEAL.FINPROD_ID AND TPDEAL.BRANCH=FTPTRADE.BRANCH AND FTPTRADE.BRANCH_TYPE IN ('D01','D02')
LEFT JOIN FIN_PRODUCT_TYPE FPT ON DEAL.FINPROD_ID = FPT.FINPROD_ID
LEFT JOIN MST_COUNTER_PARTY MCP ON FTPTRADE.COUNTER_ID = MCP.COUNTER_ID
LEFT JOIN MST_COUNTER_PARTY PARTY ON PARTY.COUNTER_ID=DEAL.COUNTER_ID LEFT JOIN MST_COUNTER_PARTY PARTY2 ON PARTY2.LINK_ID=DEAL.COUNTER_ID
WHERE 1=1 AND DECODE (SIGN(DEAL.PRIN_AMT - 0),1,'D01','D02') = FTPTRADE.BRANCH_TYPE /*中间还本以及到期会出重复数据，修改为到期以及中间还本按照D01出一笔数据，收息按D02出一笔*/ /***筛选141数据***/ AND EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE (A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID OR DEAL.P_TOTLE_TRADE_ID=A.TOTLE_TRADE_ID ) /*只接入原始交易数据*/ AND NVL(A.P_TRADE_ID,'NOREV') = 'NOREV' AND A.TG_BUSI_TYPE='141' AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = A.TRADE_ID ) ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}
or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TPDEAL.UPDATE_TIME,TPDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(FTPTRADE.UPDATE_TIME,FTPTRADE.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) ) SELECT DISTINCT * FROM ( SELECT investdeal.TRADE_SEQNO TRADE_SEQNO, investdeal.TRADE_Id TRADE_CODE, investdeal.INVEST_VARIETY INVEST_VARIETY, INVESTDEAL.INVEST_TYPE INVEST_TYPE, NVL(nvl(ppf.parent_portfolio_id,dealtotal.PORTFOLIO_ID),dealadd.PORTFOLIO_ID) PROD_ID, investdeal.REGIST_BANK_CODE REGIST_BANK_CODE, CASE WHEN investdeal.INVEST_VARIETY IN ('26', '27', '28', '29', '30') THEN investdeal.ASSET_CODE ELSE nvl(fp.FINPROD_MARKET_ID, fp2.FINPROD_ID) END AS ASSET_CODE, investdeal.CCY CCY, investdeal.amt amt, investdeal.CNY_AMT CNY_AMT, nvl(investdeal.NUM,DEALTOtAL.share_amt) NUM,/*付息时取total*/ investdeal.CUR_ASSET_TYPE CUR_ASSET_TYPE, investdeal.CUR_ASSETDET_TYPE CUR_ASSETDET_TYPE, investdeal.DEALDATE DEALDATE, investdeal.TRADE_COUNTER TRADE_COUNTER, investdeal.UNIT_PRICE_FULL UNIT_PRICE_FULL, investdeal.UNIT_PRICE_NET UNIT_PRICE_NET, investdeal.END_RATE END_RATE, investdeal.CONTRACT_CODE CONTRACT_CODE, investdeal.REMARK REMARK, CHLINFO.FINPROD_MARKET_ID CHL_CPCT_ID, investdeal.TRADE_TYPE TRADE_TYPE, investdeal.CHL_AGRT_NAME CHL_AGRT_NAME, INVESTDEAL.IS_UNDER_TRADE IS_UNDER_TRADE, investdeal.STATUS, investdeal.ORG_CODE ORG_CODE, investdeal.DEPT_CODE DEPT_CODE, investdeal.CREATE_USER CREATE_USER, investdeal.CREATE_TIME CREATE_TIME, investdeal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(investdeal.UPDATE_TIME,investdeal.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(ppf.UPDATE_TIME,ppf.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(investdeal.REV_DATE,investdeal.REV_DATE),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALTOtAL.UPDATE_TIME,DEALTOtAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(CHLINFO.UPDATE_TIME,CHLINFO.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME, INVESTDEAL.STATUS_DATE STATUS_DATE, investdeal.REV_DATE REV_DATE,/*撤销日*/ investdeal.data_source data_source, investdeal.rate rate, investdeal.BASIS BASIS, investdeal.DEALTYPE DEALTYPE, INVESTDEAL.FACEVALUE FACEVALUE, investdeal.INTPAYAMT INTPAYAMT, investdeal.F_TRADE_ID F_TRADE_CODE ,FRA.PAY_TYPE ,case when investdeal.CUR_ASSET_TYPE not in ('01','02','03','04','05','06','07','08') then null else case when investdeal.INVEST_VARIETY = '01' /*债券*/ then decode(investdeal.INVEST_TYPE,'HTM','02','TRA','01','AFS','01') when investdeal.INVEST_VARIETY in ('03','06','07','08','09','10','11','12','15') then '02' when investdeal.INVEST_VARIETY in ('13','14','25','04','05','26','27','28','29','30','31') then '01' end end as ASSET_METHOD /*资产计量方式*/ ,case when investdeal.INVEST_VARIETY ='22' then '99' /*营改增缴纳，默认99*/ when investdeal.INVEST_VARIETY ='19' then case when investdeal.TRADE_COUNTER like '%银行%' then '04' else '06' end else decode(investdeal.P_TYPE_TWO,'C0100','01','C0200','02','C0300','03','C0400','04','C0401','05','C0402','06','C0500','07','C0501','08','C0502','09','C0503','10','C0504','11','C0505','12','C0506','13','C0507','14','C0508','15','C0509','16','C0600','17',null) end as RIVAL_PARTY_TYPE FROM INVESTDEAL investdeal LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD/*交易从属表*/ /*ON DEALADD.TRADE_ID = INVESTDEAL.TRADE_ID*/ ON (DEALADD.TRADE_ID = INVESTDEAL.TRADE_ID OR DEALADD.TRADE_ID || '01' = INVESTDEAL.TRADE_ID OR DEALADD.TRADE_ID || '02' = INVESTDEAL.TRADE_ID ) /*关联FIN_PRODUCT及FIN_TRADE_PRODUCT重新获取资产代码*/
left join FIN_PRODUCT fp on fp.FINPROD_ID = investdeal.ASSET_CODE left join FIN_TRADE_PRODUCT fp2 on fp2.FINPROD_ID = investdeal.ASSET_CODE and fp2.branch = 0 LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL DEALTOtAL/*产品代码取不到取total表如：买断式回购*/ on INVESTDEAL.TOTLE_TRADE_ID = DEALTOtAL.TOTLE_TRADE_ID left join ptl_portfolio ppf on ppf.portfolio_id=nvl(DEALTOtAL.Portfolio_Id,dealadd.Portfolio_Id) LEFT JOIN FIN_PRODUCT CHLINFO/*通道信息*/ on CHLINFO.FINPROD_ID = investdeal.CHL_CPCT_ID LEFT JOIN FIN_PRODUCT_ADD FRA ON investdeal.CHL_CPCT_ID = FRA.FINPROD_ID LEFT JOIN (select DISTINCT FINPROD_MARKET_ID from FIN_PRODUCT where FINPROD_TYPE2='F16') fpd ON fpd.FINPROD_MARKET_ID=NVL(ppf.parent_portfolio_id,ppf.portfolio_id) where 1= 1 AND( NVL(investdeal.UPDATE_TIME,investdeal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(ppf.UPDATE_TIME,ppf.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(investdeal.REV_DATE,to_date('1900-01-01','yyyy-MM-dd')) > #{interfDate,jdbcType=TIMESTAMP} or NVL(CHLINFO.UPDATE_TIME,CHLINFO.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*过滤估值生成交易*/ AND (EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = investdeal.TRADE_ID ) /*可转债交易编号拼接特殊处理 start*/ OR EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND busi_type ='TRD63' AND (PTLTRADE.BUSI_NO||'01' = investdeal.TRADE_ID OR PTLTRADE.BUSI_NO||'02' = investdeal.TRADE_ID OR PTLTRADE.BUSI_NO||'03' = investdeal.TRADE_ID ) ) /*可转债交易编号拼接特殊处理 end*/ /***添加项目类及债权类筛选..过滤估值生成交易在基础查询时已经过滤**/ /**add by xuyang 投资品种添加 22 增值税出交易登记 投资品种为21 自定义现金流出交易登记*/ OR investdeal.INVEST_VARIETY IN ('21','22', '27', '28', '29', '30','31','15','03','04','05') OR (investdeal.INVEST_VARIETY IN ('01','06') and DEALTOtAL.TG_BUSI_TYPE='141') ) /* 去除估值核算自动生成交易 */ AND NVL(investdeal.CUR_ASSET_TYPE,'NOTYPE') != 'NOTYPE' and fpd.FINPROD_MARKET_ID is not null
/* 产品代码不为空时 */
#{prodCode,jdbcType=VARCHAR}
)

WITH rate as( SELECT info.* FROM MST_EXCHARGE_QUOTE info where info.QUOT_CYY = 'CNY' and info.DATASOURCE_TYPE='SAFE' and info.TRADE_DATE = (select max(t.TRADE_DATE) from MST_EXCHARGE_QUOTE t where t.EXCHARGE_CODE = info.EXCHARGE_CODE and t.DATASOURCE_TYPE='SAFE' ) ), ASSET_COUNTER AS( /*拆借*/ SELECT asset.REP_FINPROD_ID ASSET_ID, decode(infotp.TYPE_6,'D01',mstinfo.customer_id,depodetail.COUNTER_ID) COUNTER_ID, asset.REP_RATE_YEAR/100 asset_yeild, greatest(nvl(NVL(asset.UPDATE_TIME,asset.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(depodetail.UPDATE_TIME,depodetail.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME,decode(infotp.TYPE_6,'D01',asset.REP_TRADE_TARGET,depodetail.COUNTER_ID) countername FROM REP_ASSET_INTER_LEND asset left join fin_trade_product depodetail on depodetail.FINPROD_ID = asset.REP_FINPROD_ID and depodetail.branch = 0 AND depodetail.finprod_type2 IS NOT NULL left join REP_ASSET_DEPT assetdept on asset.REP_FINPROD_ID = assetdept.REP_FINPROD_ID left join fin_product info on info.FINPROD_ID=asset.REP_FINPROD_ID left join FIN_PRODUCT_TYPE infotp on nvl(info.P_FINPROD_ID,assetdept.REP_FINPROD_ID)=infotp.FINPROD_ID left join mst_customer_info mstinfo on info.issuer=mstinfo.customer_id where (infotp.TYPE_6!='D01' and depodetail.branch = 0 AND depodetail.finprod_type2 IS NOT NULL) or infotp.TYPE_6='D01' /*回购*/ union all SELECT asset.REP_FINPROD_ID ASSET_ID, depodetail.COUNTER_ID COUNTER_ID, asset.REP_ANNUAL_INTEREST_RATE/100 asset_yeild, greatest(nvl(NVL(asset.UPDATE_TIME,asset.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(depodetail.UPDATE_TIME,depodetail.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME,depodetail.COUNTER_ID countername FROM REP_LIABILITIES asset left join fin_trade_product depodetail on depodetail.FINPROD_ID = asset.REP_FINPROD_ID where depodetail.branch = 0 /*存放*/ UNION ALL SELECT asset.REP_FINPROD_ID ASSET_ID, assettail.ISSUER COUNTER_ID, asset.REP_RATE_YEAR/100 asset_yeild, greatest(nvl(NVL(asset.UPDATE_TIME,asset.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(assettail.UPDATE_TIME,assettail.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME,assettail.ISSUER countername FROM REP_ASSET_BANK_DEPOSIT asset left join fin_product assettail on assettail.FINPROD_ID = asset.REP_FINPROD_ID ), /* 增加股票和衍生品交易 add by gaojian 2019-07-19 begin */ /*债券借贷交易拆分临时表*/ TEMP_BOND_DEAL AS ( SELECT * FROM ( /*债券借贷交易买入*/ SELECT DEAL.*, '00' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN FIN_TRADE_PRODUCT ASET ON DEAL.FINPROD_ID=ASET.FINPROD_ID WHERE DEAL.FINPROD_TYPE2 IN ('F29', 'F30') AND DEAL.PS = 'T01' AND ASET.BRANCH=0 /*债券借贷到期本金交易*/ UNION ALL SELECT DEAL.*, '01' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 IN ('F29', 'F30') AND DEAL.PS = 'T07' /*债券借贷到期费用交易*/ UNION ALL SELECT DEAL.*, '02' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 IN ('F29', 'F30') AND DEAL.PS = 'T07' ) TEMP WHERE 1 = 1 AND EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = TEMP.TRADE_ID ) ), /*外汇即期交易拆分临时表*/ TEMP_FES_DEAL AS ( SELECT * FROM ( /*拆分的买入交易*/ SELECT DEAL.*, '01' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F11' AND DEAL.PS = 'T01' /*拆分的卖出交易*/ UNION ALL SELECT DEAL.*, '02' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F11' AND DEAL.PS = 'T01' /*其余交易(理论上没有数据)*/ UNION ALL SELECT DEAL.*, '00' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F11' AND DEAL.PS != 'T01' ) TEMP WHERE 1 = 1 AND EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = TEMP.TRADE_ID ) ), /*外汇远期交易拆分临时表*/ TEMP_FEF_DEAL AS ( SELECT * FROM ( /*外汇远期交易买入*/ SELECT DEAL.*, '00' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F12' AND DEAL.PS != 'T07' /*外汇远期到期本金交易*/ UNION ALL SELECT DEAL.*, '01' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F12' AND DEAL.PS = 'T07' /*外汇远期到期费用交易*/ UNION ALL SELECT DEAL.*, '02' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F12' AND DEAL.PS = 'T07' ) TEMP WHERE 1 = 1 AND EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = TEMP.TRADE_ID ) ), /*外汇掉期交易拆分临时表*/ TEMP_FESW_DEAL AS ( SELECT * FROM ( /*外汇掉期买入卖出交易*/ SELECT DEAL.*, '01' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F13' /*外汇掉期收益交易*/ UNION ALL SELECT DEAL.*, '02' SPLIT_TYPE FROM TRD_PRODUCT_DEAL DEAL WHERE DEAL.FINPROD_TYPE2 = 'F13' ) TEMP WHERE 1 = 1 AND EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = TEMP.TRADE_ID ) ), /* 增加股票和衍生品交易 add by gaojian 2019-07-19 end */ INVESTDEAL AS( /*增加期权 add by zhengxiaolian 2020-01-15 start*/ select NULL TRADE_SEQNO/*交易UUID*/ ,DEAL.TRADE_ID TRADE_ID/*行内交易编码*/ ,'31' INVEST_VARIETY/*投资品种*/ ,NULL INVEST_TYPE/*投资类型*/ ,DEALADD.PORTFOLIO_ID PROD_ID/*产品代码*/ ,DEAL.regist_org REGIST_BANK_CODE/*登记银行编码*/ ,DEAL.FINPROD_ID ASSET_CODE /*行内资产/负债编码*/ ,DEAL.CCY CCY/*币种*/ ,NVL(DEAL.TRADE_AMT,0) AMT /*发生金额*/ ,NULL CNY_AMT/*折算人民币金额*/ ,DEAL.SHARE_AMT NUM/*数量*/ /****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ ,CASE WHEN DEAL.TG_BUSI_TYPE = '145' THEN '10' WHEN DEAL.TG_BUSI_TYPE = '146' THEN '09' WHEN DEAL.TG_BUSI_TYPE IN ('148','149') AND DEAL.PS_PAYMENT = '01' THEN '09' WHEN DEAL.TG_BUSI_TYPE IN ('148','149') AND DEAL.PS_PAYMENT = '02' THEN '10' END CUR_ASSET_TYPE/*资金流动类型*/ ,CASE WHEN DEAL.TG_BUSI_TYPE = '145' THEN '支付期权费用' WHEN DEAL.TG_BUSI_TYPE = '146' THEN '卖方收取期权费用' WHEN DEAL.TG_BUSI_TYPE IN ('148','149') AND DEAL.PS_PAYMENT = '01' THEN '场外期权收入' WHEN DEAL.TG_BUSI_TYPE IN ('148','149') AND DEAL.PS_PAYMENT = '02' THEN '场外期权支出' end CUR_ASSETDET_TYPE /*资金流动类型说明*/ /*,DECODE(DEAL.PS,'T01','01','T59','02','T60','02','T61','02') CUR_ASSET_TYPE资金流动类型 ,'无' CUR_ASSETDET_TYPE 资金流动类型说明*/ /****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ ,DEAL.SETTLE_DATE DEALDATE /*交易日*/ ,DECODE(DEAL.PS,'T22',SECASSET.REGIST_ORG,'T23',SECASSET.REGIST_ORG,TOTALDEAL.COUNTER_ID) TRADE_COUNTER/*交易对手*/
/****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ ,NULL UNIT_PRICE_FULL /*单位成交价格（全价）*/ ,NULL UNIT_PRICE_NET /*单位成交价格（净价）*/ ,DEAL.YIELD END_RATE /*到期收益率*/ ,DEAL.TRADE_ID CONTRACT_CODE /*成交编号/合同号*/ ,NULL REMARK /*备注*/ ,NULL CHL_CPCT_ID /*通道代码*/ ,'04' TRADE_TYPE /*交易类型*/ ,NULL CHL_AGRT_NAME /*通道名称*/ ,'02' IS_UNDER_TRADE /*是否底层交易流水 01 是/ 02 否*/ ,DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS /*数据状态*/ ,NULL ORG_CODE /*机构代码*/ ,NULL DEPT_CODE /*部门代码*/ ,deal.CREATE_USER CREATE_USER /*创建人*/ ,deal.CREATE_TIME CREATE_TIME /*创建时间*/ ,deal.UPDATE_USER UPDATE_USER /*更新人*/ ,greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME /*更新时间*/ ,NULL STATUS_DATE /*数据日期*/ ,REVDL.create_time REV_DATE/*撤销日*/ ,NULL DATA_SOURCE /*数据来源*/ ,NULL RATE /*利率*/ ,NULL BASIS /*计息基础*/ ,NULL FACEVALUE /*面值*/ ,DECODE(DEAL.PS,'T01','08','T59','09','T60','09','T61','09') DEALTYPE /*交易类型*/ ,deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID /****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ left join MST_COUNTER_PARTY party on DECODE(DEAL.PS,'T22',SECASSET.REGIST_ORG,'T23',SECASSET.REGIST_ORG,TOTALDEAL.COUNTER_ID) = party.COUNTER_ID left join MST_COUNTER_PARTY party2 on DECODE(DEAL.PS,'T22',SECASSET.REGIST_ORG,'T23',SECASSET.REGIST_ORG,TOTALDEAL.COUNTER_ID) = party2.LINK_ID
/****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.DATA_TYPE in( 'MST15','PTL01') AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 and T23.INSTITUTION_CODE IS NOT NULL and DEAL.FINPROD_TYPE2='F35' AND nvl(deal.p_trade_id,'NOREV')='NOREV'/*不取撤销交易*/ /****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/ and NVL(DEAL.TRADE_AMT,0) > 0 /****TOS-269 【交易信息登记-集成测试】：场外期权交易，交易信息登记不正确，详见描述 leipeng 20210227***/
AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*增加期权 add by zhengxiaolian 2020-01-15 end*/ union all
/*债券+abs+行权 - 非还本不带息*/ SELECT NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '01' INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS','SELL','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/
NVL(fpd.FINPROD_ID,DEAL.FINPROD_ID) ASSET_CODE, DEAL.CCY CCY, deal.trade_amt AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ /*DECODE(DEAL.PS,'T29',NVL(DEAL.ACCR_NUM,0),NVL(DEAL.SHARE_AMT,0))*100 NUM,债券借贷按照计提份额*/ CASE WHEN DEAL.TG_BUSI_TYPE = '144' THEN CASE WHEN DEAL.PS = 'T22' THEN NVL(NVL(DEAL.ACCR_NUM,DEAL.SHARE_AMT),0) * 100 ELSE NVL(DEAL.SHARE_AMT,0) / NVL(PRODUCTASSET.M_PRIN_AMT,100) * 100 END ELSE NVL(NVL(DEAL.ACCR_NUM,DEAL.SHARE_AMT),0) * 100 END NUM, DECODE(DEAL.PS,'T01','01','T02','02','T03','02','T39','02','T22',DECODE(TOTALDEAL.PS,'T08','09','T09','09','T07','09'),'T23',DECODE(TOTALDEAL.PS,'T08','11','T07','02'),'T29','12') CUR_ASSET_TYPE,/*中间还本的利息需统计成11其他收入*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08','债券收息交易','T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08','债券中间还本交易','T07','到期'),'T29','融入债券付息还本') CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T29',DEAL.COUNTER_ID,'T39',party2.COUNTER_ID,'T22',party2.COUNTER_ID,'T23',party2.COUNTER_ID, 'T29', party2.COUNTER_ID, 'T32', party2.COUNTER_ID) TRADE_COUNTER, ROUND(DECODE(DEAL.PS,'T01',DEAL.UNIT_FPRICE,'T02',DEAL.UNIT_FPRICE,'T03',DEAL.UNIT_FPRICE,'T39',NVL(DEAL.UNIT_FPRICE, DECODE(DEAL.SHARE_AMT, 0, 0, DEAL.TRADE_AMT/DEAL.SHARE_AMT)),'T23',DECODE(TOTALDEAL.PS,'T08',DECODE(DEAL.TG_BUSI_TYPE,'144',NVL(PRODUCTASSET.M_PRIN_AMT,0) * -1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT*-1)),'T07',DECODE(DEAL.TG_BUSI_TYPE,'144',NVL(PRODUCTASSET.M_PRIN_AMT,0),DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)))),4) UNIT_PRICE_FULL, ROUND(DECODE(DEAL.PS,'T01',DEAL.UNIT_CPRICE,'T02',DEAL.UNIT_CPRICE,'T03',DEAL.UNIT_CPRICE,'T39',NVL(DEAL.UNIT_CPRICE, DECODE(DEAL.SHARE_AMT, 0, 0, DEAL.CPRICE_AMT/DEAL.SHARE_AMT)),'T23',DECODE(TOTALDEAL.PS,'T08',DECODE(DEAL.TG_BUSI_TYPE,'144',NVL(PRODUCTASSET.M_PRIN_AMT,0) * -1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT*-1)),'T07',DECODE(DEAL.TG_BUSI_TYPE,'144',NVL(PRODUCTASSET.M_PRIN_AMT,0),DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)))),4) UNIT_PRICE_NET, DECODE(DEAL.PS,'T01',DEAL.YIELD,'T02',DEAL.YIELD,'T03',DEAL.YIELD,'T39',DEAL.YIELD,'T23',decode(TOTALDEAL.ps,'T07',DEAL.YIELD)) END_RATE, DEAL.TRADE_ID CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(DEAL.IS_CANCEL, 'Y', 'D', 'E') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ decode(deal.ps,'T23',decode(totaldeal.ps,'T07',decode(deal.SHARE_AMT,0,0,DEAL.TRADE_AMT/deal.SHARE_AMT),deal.par_value),DEAL.PAR_VALUE) FACEVALUE,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T03','09','T39','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01')) DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID left join mst_customer_info customer on SECASSET.ISSUER = customer.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT PRODUCTASSET ON PRODUCTASSET.FINPROD_ID=TOTALDEAL.FINPROD_ID AND PRODUCTASSET.BRANCH=DEAL.BRANCH
LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T39',DEAL.COUNTER_ID,'T22',customer.customer_id,'T23',customer.customer_id) left join (select P.*,D.INSTITUTION_CODE,D.DATA_TYPE FROM MST_COUNTER_PARTY P LEFT JOIN DATA_AUTH_NOTIFY_INST D ON P.COUNTER_ID=D.BUSINESS_ID WHERE D.MODEL_TYPE = '02' AND D.DATA_TYPE in ('MST15','PTL01')) party2 on party2.LINK_ID=DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T39',DEAL.COUNTER_ID,'T22',customer.customer_id,'T23',customer.customer_id)
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.DATA_TYPE in ('MST15','PTL01') AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE left join FIN_PRODUCT_ADD fpd on secASSET.finprod_market_id = fpd.appear_market_id LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fpd.FINPROD_ID WHERE 1=1 and T23.INSTITUTION_CODE IS NOT NULL /*债券借贷现金交易融出券生成的交易暂时先放这里统计*/ AND (DEAL.BUSI_TYPE IN( '02','29') or (DEAL.BUSI_TYPE = '14' and DEAL.PS = 'T02') or (DEAL.BUSI_TYPE = '37' and DEAL.FINPROD_TYPE2 = 'F01')) and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' and (DEAL.TG_BUSI_TYPE!='141' OR DEAL.TG_BUSI_TYPE IS NULL) /***非还本不带息数据筛选***/ AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = deal.TRADE_ID ) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26','T41') ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) union all /*债券+abs+行权 -还本不带息数据*/ SELECT NULL TRADE_SEQNO, deal.TOTLE_TRADE_ID TRADE_ID, '01' INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS','SELL','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ ORG.regist_org REGIST_BANK_CODE,/*登记银行编码*/
NVL(fpd.FINPROD_ID,DEAL.FINPROD_ID) ASSET_CODE, DEAL.CCY CCY, deal.trade_amt AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DEAL.SHARE_AMT*100 NUM, DECODE(DEAL.PS,'T01','01','T02','02','T03','02','T39','02','T22',DECODE(TOTALDEAL.PS,'T08',DECODE(SIGN(PSP.AMOUNT),1,'11','09'),'T09','09','T07','09'),'T23',DECODE(TOTALDEAL.PS,'T08',DECODE(SIGN(PSP.AMOUNT),1,'11','02'),'T07','02')) CUR_ASSET_TYPE,/*中间还本的利息需统计成11其他收入*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08',DECODE(SIGN(PSP.AMOUNT),1,'部分到期-收息','收息'),'T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08',DECODE(SIGN(PSP.AMOUNT),1,'部分到期','到期'),'T07','到期')) CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE,
DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T39',DEAL.COUNTER_ID,'T22',customer.CUSTOMER_NAME,'T23',customer.CUSTOMER_NAME) TRADE_COUNTER, DECODE(DEAL.PS,'T01',DEAL.UNIT_FPRICE,'T02',DEAL.UNIT_FPRICE,'T03',DEAL.UNIT_FPRICE,'T39',DEAL.UNIT_FPRICE,'T23',DECODE(TOTALDEAL.PS,'T08',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT*-1),'T07',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT))) UNIT_PRICE_FULL, DECODE(DEAL.PS,'T01',DEAL.UNIT_CPRICE,'T02',DEAL.UNIT_CPRICE,'T03',DEAL.UNIT_CPRICE,'T39',DEAL.UNIT_CPRICE,'T23',DECODE(TOTALDEAL.PS,'T08',decode(deal.SHARE_AMT,0,0,DEAL.trade_amt/DEAL.SHARE_AMT*-1),'T07',decode(deal.SHARE_AMT,0,0,DEAL.trade_amt/DEAL.SHARE_AMT))) UNIT_PRICE_NET, DECODE(DEAL.PS,'T01',DEAL.YIELD,'T02',DEAL.YIELD,'T03',DEAL.YIELD,'T39',DEAL.YIELD,'T23',decode(TOTALDEAL.ps,'T07',DEAL.YIELD)) END_RATE, DEAL.TOTLE_TRADE_ID CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.P_TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ decode(deal.ps,'T23',decode(totaldeal.ps,'T07',decode(deal.SHARE_AMT,0,0,DEAL.TRADE_AMT/deal.SHARE_AMT),deal.par_value),DEAL.PAR_VALUE) FACEVALUE,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T03','09','T39','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01')) DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL REVDL ON deal.TOTLE_TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID left join mst_customer_info customer on SECASSET.ISSUER = customer.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT PRODUCTASSET ON PRODUCTASSET.FINPROD_ID=TOTALDEAL.FINPROD_ID AND PRODUCTASSET.BRANCH=0 LEFT JOIN trd_deal_total_add TRDADD ON TRDADD.TOTLE_TRADE_ID=TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT PRODUCTASSET1 ON PRODUCTASSET1.FINPROD_ID=TRDADD.MP_FINPROD_ID AND PRODUCTASSET1.BRANCH=0 LEFT JOIN (SELECT DEAL.TOTLE_TRADE_ID, DEALADD.PORTFOLIO_ID, SUM(NVL(DEALADD.REG_DATE_AMT,0)) REG_DATE_AMT FROM TRD_PRODUCT_DEAL_ADD DEALADD LEFT JOIN TRD_PRODUCT_DEAL DEAL ON DEALADD.TRADE_ID = DEAL.TRADE_ID GROUP BY DEAL.TOTLE_TRADE_ID, DEALADD.PORTFOLIO_ID ) DEALADD ON DEALADD.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID LEFT JOIN (SELECT TOTLE_TRADE_ID , regist_org FROM TRD_PRODUCT_DEAL GROUP BY TOTLE_TRADE_ID , regist_org ) ORG ON ORG.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T39',DEAL.COUNTER_ID,'T22',customer.customer_id,'T23',customer.customer_id) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= DECODE(DEAL.PS,'T01',DEAL.COUNTER_ID,'T02',DEAL.COUNTER_ID,'T03',DEAL.COUNTER_ID,'T39',DEAL.COUNTER_ID,'T22',customer.customer_id,'T23',customer.customer_id)
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.DATA_TYPE in ('MST15','PTL01') AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE left join FIN_PRODUCT_ADD fpd on secASSET.finprod_market_id = fpd.appear_market_id LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fpd.FINPROD_ID LEFT JOIN PTL_SEC_POSITION PSP ON PSP.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND PSP.FINPROD_ID=FP.FINPROD_ID AND DEAL.SETTLE_DATE = PSP.CDATE AND DEAL.INV_AIM=PSP.INV_AIM AND PSP.HODING_TYPE = '03' WHERE 1=1 and T23.INSTITUTION_CODE IS NOT NULL AND EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID /*债券借贷现金交易融出券生成的交易暂时先放这里统计*/ AND (DEAL.BUSI_TYPE IN ( '02', '29') or (DEAL.BUSI_TYPE = '14' and DEAL.PS = 'T02') or (DEAL.BUSI_TYPE = '37' and DEAL.FINPROD_TYPE2 = 'F01')) and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') AND NVL(AD.UPDATE_TIME,AD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = a.TRADE_ID ) and (A.TG_BUSI_TYPE!='141' OR A.TG_BUSI_TYPE IS NULL) ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*计划类资产-非还本不带息数据*/ union all SELECT NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01','04','02','03','03','05') INVEST_VARIETY,/*投资品种根据收益类型分类*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ nvl(PLANASSET.FINPROD_ID,PLANASSETDETAIL.FINPROD_ID) ASSET_CODE, DEAL.CCY CCY, /*decode(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01',decode(deal.ps,'T12',deal.int_amt,DEAL.TRADE_AMT),DEAL.TRADE_AMT) AMT,*/ /*利率型单独一类、货币性和净值型一类*/ decode(deal.ps,'T01',deal.trade_amt,'T11',deal.int_amt,'T12',deal.int_amt,DEAL.TRADE_AMT) AMT,/*对于计划类资产，红利再投及分红 发生金额直接取int_amt*/ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ decode(deal.ps,'T22',decode(totaldeal.ps,'T09',TOTALDEALPA.REMAIN_PRIN_AMT,TOTALDEAL.SHARE_AMT),'T23',TOTALDEAL.SHARE_AMT,DEAL.SHARE_AMT) NUM,
DECODE(DEAL.PS,'T01','01','T02','02','T22','09','T23','02','T05','01','T19','02','T11','09','T12','01','C3','01','C06','02') CUR_ASSET_TYPE,/*计划类资产红利再投另加一笔投资收益*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08','部分到期-收息','T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08','部分到期','T07','到期'),'T11','资产分红') CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, decode(deal.ps,'T22',custinfo.CUSTOMER_NAME,'T23',custinfo.CUSTOMER_NAME,'T11',custinfo.CUSTOMER_NAME,'T12',custinfo.CUSTOMER_NAME,DEAL.COUNTER_ID) TRADE_COUNTER,/*对手方*/
ROUND(DECODE( DEAL.PS, 'T01',DECODE( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)*100), 'T02',DECODE( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE), '03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)*100), 'T23',100, 'T05',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T19',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T12',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01',decode(nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT),0,0,DEAL.INT_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT)),'03',1,DEAL.TRADE_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.TRADE_AMT,DEAL.SHARE_AMT),deal.TRADE_AMT)) ),4) UNIT_PRICE_FULL,
ROUND(DECODE( DEAL.PS, 'T01',decode( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',100 ), 'T02',decode( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',100),
'T23',100, 'T05',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T19',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T12',decode(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01',decode(nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT),0,0,DEAL.INT_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT)),'03',1,DEAL.TRADE_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.TRADE_AMT,DEAL.SHARE_AMT),deal.TRADE_AMT)) ),4) UNIT_PRICE_NET, DECODE(DEAL.PS,'T23',DECODE(TOTALDEAL.PS,'T07',DEAL.YIELD)) END_RATE, nvl(nvl(PLANASSET.CONTRACT_NO,PLANASSETDETAIL.CONTRACT_NO),DEAL.TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(DEAL.IS_CANCEL,'N','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ null faceValue,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01'),'T05','12','T19','15','T11','20','T12','05','C3','04','C06','03') DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, DEALADD.REG_DATE_AMT INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID /* ASSETPOSITION.AMOUNT INTPAYAMT */ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT PLANASSETDETAIL on deal.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID LEFT JOIN FIN_PRODUCT PLANASSET on PLANASSETDETAIL.P_FINPROD_ID = PLANASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO custinfo on nvl(PLANASSET.MANAGER,PLANASSETDETAIL.MANAGER) = custinfo.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID)
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.Data_Type = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.Data_Type in( 'MST15','PTL01') AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 AND T23.MODEL_TYPE IS NOT NULL /*过滤项目类资产、计划类资产、基金重复项*/ AND DEAL.BUSI_TYPE IN( '07','09','06', '37') AND DEAL.FINPROD_TYPE2 = 'F17' /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /***添加非还本不带息拆分数据***/
AND (DEAL.PS = 'T22' OR (DEAL.PS != 'T22' and EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = deal.TRADE_ID )))
AND not EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') ) and (DEAL.TG_BUSI_TYPE!='141' OR DEAL.TG_BUSI_TYPE IS NULL) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP})
/*计划类资产-还本不带息数据*/ union all
