ARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T12',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01',decode(nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT),0,0,DEAL.INT_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT)),'03',1,DEAL.TRADE_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.TRADE_AMT,DEAL.SHARE_AMT),deal.TRADE_AMT)) ),4) UNIT_PRICE_FULL, ROUND(DECODE( DEAL.PS, 'T01',decode( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',100 ), 'T02',decode( nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE) ,'03',1 ,'01',DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT) ,'02',100),
'T23',100, 'T05',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T19',DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'03',1,DECODE(DEAL.SHARE_AMT,0,0,DEAL.TRADE_AMT/DEAL.SHARE_AMT)), 'T12',decode(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01',decode(nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT),0,0,DEAL.INT_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.INT_AMT,DEAL.SHARE_AMT),deal.INT_AMT)),'03',1,DEAL.TRADE_AMT/nvl(decode(DEAL.SHARE_AMT,0,deal.TRADE_AMT,DEAL.SHARE_AMT),deal.TRADE_AMT)) ),4) UNIT_PRICE_NET, DECODE(DEAL.PS,'T23',DECODE(TOTALDEAL.PS,'T07',DEAL.YIELD)) END_RATE, nvl(nvl(PLANASSET.CONTRACT_NO,PLANASSETDETAIL.CONTRACT_NO),DEAL.TOTLE_TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.P_TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ null faceValue,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01'),'T05','12','T19','15','T11','20','T12','05','C3','04','C06','03') DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, DEALADD.REG_DATE_AMT INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ /* ASSETPOSITION.AMOUNT INTPAYAMT */ FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL REVDL ON deal.TOTLE_TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT PLANASSETDETAIL on deal.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID LEFT JOIN FIN_PRODUCT PLANASSET on PLANASSETDETAIL.P_FINPROD_ID = PLANASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO custinfo on nvl(PLANASSET.MANAGER,PLANASSETDETAIL.MANAGER) = custinfo.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN ( SELECT DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID,sum(nvl(DEALADD.REG_DATE_AMT,0)) REG_DATE_AMT FROM TRD_PRODUCT_DEAL_ADD DEALADD LEFT JOIN TRD_PRODUCT_DEAL DEAL ON DEALADD.TRADE_ID = DEAL.TRADE_ID group by DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID) DEALADD ON DEALADD.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID LEFT JOIN ( SELECT TOTLE_TRADE_ID ,regist_org FROM TRD_PRODUCT_DEAL GROUP BY TOTLE_TRADE_ID ,regist_org ) ORG ON ORG.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID)
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.Data_Type = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.Data_Type in( 'MST15','PTL01') AND T22.MODEL_TYPE='02' AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 AND T23.MODEL_TYPE IS NOT NULL
/***添加还本不带息拆分数据***/ AND EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID /*过滤项目类资产、计划类资产、基金重复项*/ AND A.BUSI_TYPE IN( '07','09','06', '37') AND A.FINPROD_TYPE2 = 'F17' /*只接入原始交易数据*/ /*AND A.TRADE_STATUS = '01'*/ /**TG_BUSI_TYPE141先不处理，下面一并处理*/ and (A.TG_BUSI_TYPE!='141' OR A.TG_BUSI_TYPE IS NULL) and nvL(A.p_trade_id,'NOREV') = 'NOREV' AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') AND NVL(AD.UPDATE_TIME,AD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = a.TRADE_ID )) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}
or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP})
/*存款类资产、拆借类资产 -非还本不带息数据*/ union all SELECT NULL TRADE_SEQNO, DEAL.TRADE_ID TRADE_ID, DECODE(DEAL.FINPROD_TYPE2,'F08','07','F09','08','F21','08','F25','07','06') INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, decode(deal.ps,'T12',deal.int_amt,DEAL.TRADE_AMT) AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ nvl(DEAL.SHARE_AMT,t3.amount) NUM, /*01 拆借(包含F08 普通拆借拆入 和 F25 特拆拆入) 03 存款 37 逾期*/ CASE WHEN DEAL.BUSI_TYPE = '01' THEN (CASE WHEN DEAL.FINPROD_TYPE2 = 'F08' or DEAL.FINPROD_TYPE2 = 'F25' THEN DECODE(DEAL.PS,'T01','06','T02','08','T23','08','T22','10') ELSE DECODE(DEAL.PS,'T01','05','T02','07','T23','07','T22','09') END) WHEN DEAL.BUSI_TYPE = '03' THEN DECODE(DEAL.PS,'T01','03','T02','04','T12','03','T22','09','T23',DECODE(TOTALDEAL.PS,'T08','04','T07','04'),'T38','04') WHEN DEAL.BUSI_TYPE = '37' THEN '09' ELSE NULL END AS CUR_ASSET_TYPE,
DECODE(DEAL.BUSI_TYPE,'01',DECODE(DEAL.PS,'T22',DECODE(DEAL.FINPROD_TYPE2,'F08','付息','收息'),'T23','到期'),DECODE(DEAL.PS,'T22',DECODE(TOTALDEAL.PS,'T08','收息','T09','收息','T07','收息'),'T23',DECODE(TOTALDEAL.PS,'T08','部分到期','T07','到期'))) CUR_ASSETDET_TYPE, DEAL.SETTLE_DATE DEALDATE,
case when DEAL.BUSI_TYPE = '03' then DECODE(DEAL.PS,'T22',mst.customer_name,'T23',mst.customer_name,'T38',mst.customer_name,'T12',mst.customer_name,DECODE(TOTALDEAL.PS,'T09',mst.customer_name,deal.counter_id)) when DEAL.BUSI_TYPE = '37' then DECODE(DEAL.PS,'T22',mst.customer_name,'T23',mst.customer_name,'T38',mst.customer_name,'T12',mst.customer_name,DECODE(TOTALDEAL.PS,'T09',mst.customer_name,deal.counter_id)) when DEAL.BUSI_TYPE = '01' and DEAL.FINPROD_TYPE2 = 'F07' then NVL(deal.counter_id,party2.COUNTER_ID) when DEAL.BUSI_TYPE = '01' and DEAL.FINPROD_TYPE2 != 'F07' then NVL(deal.counter_id,assetcounter.COUNTER_ID) else null end as TRADE_COUNTER,
/* DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T22',assetcounter.COUNTER_ID,'T23',assetcounter.COUNTER_ID,'T38',assetcounter.COUNTER_ID,decode(TOTALDEAL.PS,'T09',assetcounter.COUNTER_ID,deal.counter_id)),'01',decode(deal.finprod_id,'F07',DECODE(DEAL.PS,'T22',assetcounter.COUNTER_ID,'T23',assetcounter.COUNTER_ID,'T38',assetcounter.COUNTER_ID,decode(TOTALDEAL.PS,'T09',assetcounter.COUNTER_ID,deal.counter_id),DECODE(DEAL.PS,'T22',assetcounter.COUNTER_ID,'T23',assetcounter.COUNTER_ID,deal.counter_id)))) TRADE_COUNTER, */ /*到期收息的对手方要为空*/ NULL UNIT_PRICE_FULL, NULL UNIT_PRICE_NET, DECODE(DEAL.BUSI_TYPE,'01',assetcounter.asset_yeild,'03',assetcounter.asset_yeild) END_RATE, nvl(DEPOASSET.CONTRACT_NO,DEAL.TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(DEAL.IS_CANCEL, 'Y', 'D', 'E') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEPOASSET.UPDATE_TIME,DEPOASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(ASSETCOUNTER.UPDATE_TIME,to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ null faceValue,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T38','09','T22',DECODE(TOTALDEAL.PS,'T08','25','T09','23','T07','02','C7','23'),'T23',DECODE(TOTALDEAL.PS,'T08','24','T07','01'),'T12','05') DEALTYPE, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, DECODE(DEAL.PS,'T12',AMOUNT,null) INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN ASSET_COUNTER ASSETCOUNTER/*资产交易对手*/ on assetcounter.asset_id = DEAL.FINPROD_ID LEFT JOIN FIN_PRODUCT DEPOASSET ON DEPOASSET.FINPROD_ID = DEAL.FINPROD_ID left join MST_CUSTOMER_INFO mst on DEPOASSET.ISSUER = mst.customer_id LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON deal.TRADE_ID = T2.TRADE_ID LEFT JOIN ptl_sec_position T3 ON deal.mdate -1 = T3.CDATE AND deal.FINPROD_ID = T3.FINPROD_ID and T2.PORTFOLIO_ID = T3.PORTFOLIO_ID and T3.HODING_TYPE='03' left join MST_COUNTER_PARTY party on party.COUNTER_ID= DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T22',mst.customer_id,'T23',mst.customer_id,'T38',mst.customer_id,decode(TOTALDEAL.PS,'T09',mst.customer_id,deal.counter_id)),'01',NVL(deal.counter_id,assetcounter.COUNTER_ID)) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T22',mst.customer_id,'T23',mst.customer_id,'T38',mst.customer_id,decode(TOTALDEAL.PS,'T09',mst.customer_id,deal.counter_id)),'01',NVL(deal.counter_id,assetcounter.COUNTER_ID))
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON T2.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.Data_Type in( 'MST15','PTL01') AND T22.MODEL_TYPE='02' AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 and T23.INSTITUTION_CODE IS NOT NULL and (deal.BUSI_TYPE in( '03','01') or (DEAL.BUSI_TYPE = '37' and DEAL.FINPROD_TYPE2 = 'F07')) /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /***添加非还本不带息拆分数据***/ AND EXISTS (SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = deal.TRADE_ID ) AND NOT EXISTS (SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID AND AD.PORTFOLIO_ID =T2.PORTFOLIO_ID AND A.PS IN ('T25','T26') ) and (DEAL.TG_BUSI_TYPE!='141' OR DEAL.TG_BUSI_TYPE IS NULL) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEPOASSET.UPDATE_TIME,DEPOASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ASSETCOUNTER.UPDATE_TIME > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) union all /*存款类资产、拆借类资产 -还本不带息数据*/ SELECT NULL TRADE_SEQNO, DEAL.TOTLE_TRADE_ID TRADE_ID, DECODE(DEAL.FINPROD_TYPE2,'F08','07','F09','08','F21','08','F25','07','06') INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ org.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, decode(deal.ps,'T12',deal.int_amt,DEAL.TRADE_AMT) AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ nvl(DEAL.SHARE_AMT,t3.amount) NUM, DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T01','03','T02','04','T12','01','T22','09','T23',DECODE(TOTALDEAL.PS,'T08','04','T07','04'),'T38','04'),'01',DECODE(DEAL.FINPROD_TYPE2,'F08',DECODE(DEAL.PS,'T01','06','T02','08','T22','10','T23','08'),DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07'))) CUR_ASSET_TYPE, DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T22',DECODE(TOTALDEAL.PS,'T08','收息','T09','收息','T07','收息'),'T23',DECODE(TOTALDEAL.PS,'T08','部分到期','T07','到期')),'01',DECODE(DEAL.PS,'T22',DECODE(DEAL.FINPROD_TYPE2,'F08','付息','收息'),'T23','到期')) CUR_ASSETDET_TYPE, DEAL.SETTLE_DATE DEALDATE, DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T22',mst.customer_name,'T23',mst.customer_name,'T38',mst.customer_name,'T12',mst.customer_name,DECODE(TOTALDEAL.PS,'T09',mst.customer_name,deal.counter_id)),'01',NVL(deal.counter_id,assetcounter.COUNTER_ID)) TRADE_COUNTER,
/*到期收息的对手方要为空*/ NULL UNIT_PRICE_FULL, NULL UNIT_PRICE_NET, DECODE(DEAL.BUSI_TYPE,'01',assetcounter.asset_yeild,'03',assetcounter.asset_yeild) END_RATE, nvl(DEPOASSET.CONTRACT_NO,DEAL.TOTLE_TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.P_TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEPOASSET.UPDATE_TIME,DEPOASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(ASSETCOUNTER.UPDATE_TIME,to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ null faceValue,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T38','09','T22',DECODE(TOTALDEAL.PS,'T08','25','T09','23','T07','02','C7','23'),'T23',DECODE(TOTALDEAL.PS,'T08','24','T07','01'),'T12','05') DEALTYPE, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, DECODE(DEAL.PS,'T12',AMOUNT,null) INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL REVDL ON deal.TOTLE_TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN ASSET_COUNTER ASSETCOUNTER/*资产交易对手*/ on assetcounter.asset_id = DEAL.FINPROD_ID LEFT JOIN FIN_PRODUCT DEPOASSET ON DEPOASSET.FINPROD_ID = DEAL.FINPROD_ID left join MST_CUSTOMER_INFO mst on DEPOASSET.ISSUER = mst.customer_id LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON deal.TOTLE_TRADE_ID = T2.TRADE_ID LEFT JOIN ptl_sec_position T3 ON deal.mdate -1 = T3.CDATE AND deal.FINPROD_ID = T3.FINPROD_ID and T2.PORTFOLIO_ID = T3.PORTFOLIO_ID and T3.HODING_TYPE='03' LEFT JOIN (SELECT DEAL.TOTLE_TRADE_ID, DEALADD.PORTFOLIO_ID, SUM(NVL(DEALADD.REG_DATE_AMT,0)) REG_DATE_AMT FROM TRD_PRODUCT_DEAL_ADD DEALADD LEFT JOIN TRD_PRODUCT_DEAL DEAL ON DEALADD.TRADE_ID = DEAL.TRADE_ID GROUP BY DEAL.TOTLE_TRADE_ID, DEALADD.PORTFOLIO_ID ) DEALADD ON DEALADD.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID LEFT JOIN (SELECT TOTLE_TRADE_ID , regist_org FROM TRD_PRODUCT_DEAL GROUP BY TOTLE_TRADE_ID , regist_org ) ORG ON ORG.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID= DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T22',mst.customer_id,'T23',mst.customer_id,'T38',mst.customer_id,decode(TOTALDEAL.PS,'T09',mst.customer_id,deal.counter_id)),'01',NVL(deal.counter_id,assetcounter.COUNTER_ID)) left join MST_COUNTER_PARTY party2 on party2.LINK_ID= DECODE(DEAL.BUSI_TYPE,'03',DECODE(DEAL.PS,'T22',mst.customer_id,'T23',mst.customer_id,'T38',mst.customer_id,decode(TOTALDEAL.PS,'T09',mst.customer_id,deal.counter_id)),'01',NVL(deal.counter_id,assetcounter.COUNTER_ID))
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON T2.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.Data_Type in( 'MST15','PTL01') AND T22.MODEL_TYPE='02' AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 and T23.INSTITUTION_CODE IS NOT NULL /***添加还本不带息拆分数据***/ AND EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID and (deal.BUSI_TYPE in( '03','01') or (DEAL.BUSI_TYPE = '37' and DEAL.FINPROD_TYPE2 = 'F07')) /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ /**TG_BUSI_TYPE141先不处理，下面一并处理*/ and (A.TG_BUSI_TYPE!='141' OR A.TG_BUSI_TYPE IS NULL) and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND AD.PORTFOLIO_ID =DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') AND NVL(AD.UPDATE_TIME,AD.CREATE_TIME) > #{interfDate, jdbcType=TIMESTAMP} AND EXISTS (SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = a.TRADE_ID ) ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEPOASSET.UPDATE_TIME,DEPOASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ASSETCOUNTER.UPDATE_TIME > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*回购交易*/ union all SELECT NULL TRADE_SEQNO, DEAL.TRADE_ID TRADE_ID, DECODE(DEAL.FINPROD_TYPE2,'F02','09','F03','10','F04','11','F05','12') INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, deal.TRADE_AMT AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DEA