UNDER_TRADE, /*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ /*有效状态默认有效*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(FUNDASSET.UPDATE_TIME,FUNDASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, /*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ NULL FACEVALUE, /*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T05','12','T18','12','T19','15','T12','05','T11','20','T64','12','T63','15','C3','08','C6','09') DEALTYPE /*收息具体类型在后续判断*/ , deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, DEALADD.REG_DATE_AMT INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID /* ASSETPOSITION.AMOUNT INTPAYAMT */ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT FUNDASSET ON DEAL.FINPROD_ID = FUNDASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO custinfo on FUNDASSET.MANAGER = custinfo.CUSTOMER_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join TRD_PRODUCT_DEAL sqdeal on sqdeal.TRADE_ID=DEAL.B_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,'C3',custinfo.CUSTOMER_ID,'C6',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,'C3',custinfo.CUSTOMER_ID,'C6',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID)
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.Data_Type in( 'MST15','PTL01') AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 and T23.INSTITUTION_CODE IS NOT NULL AND DEAL.BUSI_TYPE IN( '06','07') /*过滤货基中的计划类资产净值型*/ and deal.FINPROD_TYPE2 = 'F06' /*只取确认数据*/ AND DEAL.PS IN ('T01','T02','T05','T18','T19','T11','T12','T63','T64', 'C3', 'C6') /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(FUNDASSET.UPDATE_TIME,FUNDASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*债权类、权益类(项目)资产交易 - 非还本不带息*/ union all SELECT NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '15' INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, deal.trade_amt AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ decode(deal.ps,'T22',decode(totaldeal.ps,'T09',TOTALDEALPA.REMAIN_PRIN_AMT,TOTALDEAL.SHARE_AMT),'T23',TOTALDEAL.SHARE_AMT,DEAL.SHARE_AMT) NUM,
DECODE(DEAL.PS,'T01','01','T02','02','T22',DECODE(TOTALDEAL.PS,'T08','09','T09','09','T07','09'),'T23',DECODE(TOTALDEAL.PS,'T08','02','T07','02')) CUR_ASSET_TYPE,/*中间还本的利息需统计成11其他收入*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08','部分到期-收息','T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08','部分到期','T07','到期')) CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, decode(deal.ps,'T22',custinfo.CUSTOMER_NAME,'T23',custinfo.CUSTOMER_NAME,'T11',custinfo.CUSTOMER_NAME,'T12',custinfo.CUSTOMER_NAME,DEAL.COUNTER_ID) TRADE_COUNTER,/*到期收息的对手方要为空*/ DECODE(DEAL.PS,'T01',DEAL.UNIT_FPRICE,'T02',DEAL.UNIT_FPRICE,'T23',100) UNIT_PRICE_FULL, DECODE(DEAL.PS,'T01',DEAL.UNIT_CPRICE,'T02',DEAL.UNIT_CPRICE,'T23',decode(TOTALDEAL.SHARE_AMT,0,0,null,0,DEAL.trade_amt / TOTALDEAL.SHARE_AMT * 100)) UNIT_PRICE_NET, DECODE(DEAL.PS,'T01',DEAL.YIELD,'T02',DEAL.YIELD) END_RATE, nvl(PROJECTASSET.CONTRACT_NO,DEAL.TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(DEAL.IS_CANCEL, 'Y', 'D', 'E') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ NULL FACEVALUE,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01')) DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO custinfo on PROJECTASSET.FINANCIER = custinfo.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID)
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.Data_Type in( 'MST15','PTL01') AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 and T23.INSTITUTION_CODE IS NOT NULL /*过滤项目类资产*/ AND DEAL.BUSI_TYPE in ('09', '37') AND DEAL.FINPROD_TYPE2 = 'F18' /*只接入原始交易数据*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV'
/***非还本不带息数据筛选***/ AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = deal.TRADE_ID ) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP})
/*债权类、权益类(项目)资产交易 - 还本不带息*/ union all SELECT NULL TRADE_SEQNO, deal.TOTLE_TRADE_ID TRADE_ID, '15' INVEST_VARIETY,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ ORG.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, decode(deal.ps,'T23',totaldeal.trade_amt,DEAL.TRADE_AMT) AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ decode(deal.ps,'T22',decode(totaldeal.ps,'T09',TOTALDEALPA.REMAIN_PRIN_AMT,TOTALDEAL.SHARE_AMT),'T23',TOTALDEAL.SHARE_AMT,DEAL.SHARE_AMT) NUM, DECODE(DEAL.PS,'T01','01','T02','02','T22',DECODE(TOTALDEAL.PS,'T08','09','T09','09','T07','09'),'T23',DECODE(TOTALDEAL.PS,'T08','02','T07','02')) CUR_ASSET_TYPE,/*中间还本的利息需统计成11其他收入*/ DECODE(DEAL.PS,'T22',decode(TOTALDEAL.ps,'T08','部分到期-收息','T09','收息','T07','收息'),'T23',decode(TOTALDEAL.ps,'T08','部分到期','T07','到期')) CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, decode(deal.ps,'T22',custinfo.CUSTOMER_NAME,'T23',custinfo.CUSTOMER_NAME,'T11',custinfo.CUSTOMER_NAME,'T12',custinfo.CUSTOMER_NAME,DEAL.COUNTER_ID) TRADE_COUNTER,/*到期收息的对手方要为空*/ DECODE(DEAL.PS,'T01',DEAL.UNIT_FPRICE,'T02',DEAL.UNIT_FPRICE,'T23',100) UNIT_PRICE_FULL, ROUND(DECODE(DEAL.PS,'T01',DEAL.UNIT_CPRICE,'T02',DEAL.UNIT_CPRICE,'T23',decode(TOTALDEAL.SHARE_AMT,0,0,null,0,DEAL.trade_amt / TOTALDEAL.SHARE_AMT * 100)),4) UNIT_PRICE_NET, DECODE(DEAL.PS,'T01',DEAL.YIELD,'T02',DEAL.YIELD) END_RATE, nvl(PROJECTASSET.CONTRACT_NO,DEAL.TOTLE_TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.P_TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ NULL FACEVALUE,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',decode(TOTALDEAL.ps,'T08','25','T09','23','T07','02'),'T23',decode(TOTALDEAL.ps,'T08','24','T07','01')) DEALTYPE/*收息具体类型在后续判断*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL REVDL ON deal.TOTLE_TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO custinfo on PROJECTASSET.FINANCIER = custinfo.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN ( SELECT DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID,sum(nvl(DEALADD.REG_DATE_AMT,0)) REG_DATE_AMT FROM TRD_PRODUCT_DEAL_ADD DEALADD LEFT JOIN TRD_PRODUCT_DEAL DEAL ON DEALADD.TRADE_ID = DEAL.TRADE_ID group by DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID) DEALADD ON DEALADD.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON deal.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID LEFT JOIN ( SELECT TOTLE_TRADE_ID ,regist_org FROM TRD_PRODUCT_DEAL GROUP BY TOTLE_TRADE_ID ,regist_org ) ORG ON ORG.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=decode(deal.ps,'T22',custinfo.CUSTOMER_ID,'T23',custinfo.CUSTOMER_ID,'T11',custinfo.CUSTOMER_ID,'T12',custinfo.CUSTOMER_ID,DEAL.COUNTER_ID)
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.Data_Type in( 'MST15','PTL01') AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 and T23.INSTITUTION_CODE IS NOT NULL /***还本不带息数据筛选***/ AND EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID /*过滤项目类资产*/ AND A.BUSI_TYPE in ('09', '37') AND A.FINPROD_TYPE2 = 'F18' /*只接入原始交易数据*/ /*AND A.TRADE_STATUS = '01'*/ and nvL(A.p_trade_id,'NOREV') = 'NOREV' AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') /**TG_BUSI_TYPE141先不处理，下面一并处理*/ and (A.TG_BUSI_TYPE!='141' OR A.TG_BUSI_TYPE IS NULL) AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = a.TRADE_ID ) ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}
or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP})
/*增值税缴纳*/ union all select NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '22' INVEST_VARIETY,/*投资品种,营改增*/ deal.INV_AIM INVEST_TYPE,/*投资目的 枚举值对应待处理*/ null PROD_ID,/*产品代码*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ deal.FINPROD_ID ASSET_CODE,/*行内资产负债编码*/ deal.CCY CCY,/*币种*/ deal.trade_AMT AMT,/*发生金额*/ null CNY_AMT,/*折算人民币*/ 0 NUM,/*数量*/ '12' CUR_ASSET_TYPE,/*资金流动类型*/ '增值税缴纳' CUR_ASSETDET_TYPE,/*资金流动类型说明*/ deal.SETTLE_DATE DEALDATE,/*交易日期*/ null TRADE_COUNTER,/*交易对手*/ null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, deal.TRADE_ID CONTRACT_CODE, deal.REMARK REMARK, null CHL_CPCT_ID, ' 04' TRADE_TYPE,/*其他交易*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, NULL BASIS, NULL FACEVALUE,/*面值*/ '22' DEALTYPE/*交易类型：营改增缴纳*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,'' P_TYPE_TWO /*人行二级分类*/ from TRD_PRODUCT_DEAL deal LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD dealadd on dealadd.TRADE_ID = deal.TRADE_ID where 1= 1 and deal.BUSI_TYPE = '16' /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*通道费用交易*/ union all select NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '16' INVEST_VARIETY,/*投资品种,通道费用支付*/ deal.INV_AIM INVEST_TYPE,/*投资目的 枚举值对应待处理*/ null PROD_ID, deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ null ASSET_CODE,/*行内资产负债编码*/ deal.CCY CCY,/*币种*/ deal.trade_AMT AMT,/*发生金额*/ null CNY_AMT,/*折算人民币*/ 0 NUM,/*数量*/ '12' CUR_ASSET_TYPE,/*资金流动类型*/ '投资费用支出' CUR_ASSETDET_TYPE,/*资金流动类型说明*/ deal.TRADE_DATE DEALDATE,/*交易日期*/ custinfo.CUSTOMER_NAME TRADE_COUNTER,/*交易对手*/ null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, deal.TRADE_ID CONTRACT_CODE, deal.REMARK REMARK, null CHL_CPCT_ID, '06' TRADE_TYPE,/*通道费用交易*/ NULL CHL_AGRT_NAME, '02' IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, GREATEST(NVL(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), nvl(NVL(deal.UPDATE_TIME,deal.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(info.UPDATE_TIME,info.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, NULL BASIS, NULL FACEVALUE,/*面值*/ '16' DEALTYPE/*交易类型：通道费用支付*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ from TRD_PRODUCT_DEAL deal LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON deal.TRADE_ID = DEALADD.TRADE_ID left join fin_product info on info.FINPROD_ID = deal.CHL_ID left join MST_CUSTOMER_INFO custinfo on info.manager = custinfo.CUSTOMER_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=custinfo.CUSTOMER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=custinfo.CUSTOMER_ID
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.Data_Type in( 'MST15','PTL01') AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 and T23.INSTITUTION_CODE IS NOT NULL and deal.finprod_type2 = 'B09'/*金融产品分类（投管分类）*/ /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND(NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} OR NVL(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*投资费用交易*/ union all select NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '17' INVEST_VARIETY,/*投资品种,通道费用支付*/ null INVEST_TYPE,/*投资目的 枚举值对应待处理*/ tda.PORTFOLIO_ID PROD_ID, deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ null ASSET_CODE,/*行内资产负债编码*/ deal.CCY CCY,/*币种*/ deal.trade_AMT AMT,/*发生金额*/ null CNY_AMT,/*折算人民币*/ 0 NUM,/*数量*/ '12' CUR_ASSET_TYPE,/*资金流动类型*/ decode(TTF.FEE_TYPE,'B05','佣金','B06','交易手续费','B08','结算服务费') CUR_ASSETDET_TYPE,/*资金流动类型说明*/ deal.TRADE_DATE DEALDATE,/*交易日期*/ NULL TRADE_COUNTER,/*交易对手*/ null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, deal.TRADE_ID CONTRACT_CODE, deal.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '04' TRADE_TYPE,/*通道费用交易*/ NULL CHL_AGRT_NAME, '02' IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, GREATEST(NVL(NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), nvl(NVL(deal.UPDATE_TIME,deal.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(info.UPDATE_TIME,info.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, NULL BASIS, NULL FACEVALUE,/*面值*/ '06' DEALTYPE/*交易类型：通道费用支付*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,NVL(decode(acct2.ACCOUNT_NATURE, '01', 'C0400', '02', 'C0402'), decode(acct1.ACCOUNT_NATURE, '01', 'C0400', '02', 'C0402')) P_TYPE_TWO/*人行二级分类*/ from TRD_PRODUCT_DEAL deal LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID left join TRD_PRODUCT_DEAL_ADD tda on tda.TRADE_ID=deal.TRADE_ID LEFT JOIN TRD_TRADE_FEE_DETAIL TTF ON TTF.TRADE_ID=deal.TRADE_ID left join fin_product info on info.FINPROD_ID = deal.CHL_ID left join MST_CUSTOMER_INFO custinfo on info.manager = custinfo.CUSTOMER_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TPD ON TPD.TOTLE_TRADE_ID=deal.TOTLE_TRADE_ID
LEFT JOIN STL_PAY_ORDERS ORDERS2 ON deal.TOTLE_TRADE_ID = ORDERS2.TRADE_ID AND ORDERS2.PAY_TYPE = '02' LEFT JOIN STL_CAPACCT_INFO ACCT2 ON ORDERS2.COUNTER_ACCT_NO = ACCT2.ACCT_NO LEFT JOIN STL_PAY_ORDERS ORDERS1 ON deal.TOTLE_TRADE_ID = ORDERS1.TRADE_ID AND ORDERS1.PAY_TYPE = '01' LEFT JOIN STL_CAPACCT_INFO ACCT1 ON ORDERS1.COUNTER_ACCT_NO = ACCT1.ACCT_NO
left join MST_COUNTER_PARTY party on party.COUNTER_ID=custinfo.CUSTOMER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=custinfo.CUSTOMER_ID
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON tda.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(tda.PORTFOLIO_ID ,NVL(party.counter_id,party2.counter_id)) = T23.BUSINESS_ID AND T23.Data_Type in( 'MST15','PTL01') AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1 =1 and T23.INSTITUTION_CODE IS NOT NULL and deal.finprod_type2 = 'C11'/*金融产品分类（投管分类）*/ and TPD.TG_BUSI_TYPE='142' and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND(NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} OR NVL(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} OR NVL(TPD.UPDATE_TIME,TPD.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP})
/*自定义现金流*/ union all select NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '21' INVEST_VARIETY,/*投资品种,自定义现金流*/ deal.INV_AIM INVEST_TYPE,/*投资目的 枚举值对应待处理*/ null PROD_ID,/*产品代码*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ deal.FINPROD_ID ASSET_CODE,/*行内资产负债编码*/ deal.CCY CCY,/*币种*/ deal.trade_amt AMT,/*发生金额*/ null CNY_AMT,/*折算人民币*/ nvl(deal.trade_amt,0) NUM,/*数量*/ DECODE(deal.PS,'T99','12','T98','11' ) CUR_ASSET_TYPE,/*资金流动类型*/ '无' CUR_ASSETDET_TYPE,/*资金流动类型说明*/ deal.SETTLE_DATE DEALDATE,/*交易日期*/ deal.COUNTER_ID TRADE_COUNTER,/*交易对手*/ null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, deal.TRADE_ID CONTRACT_CODE, deal.REMARK REMARK, null CHL_CPCT_ID, '04' TRADE_TYPE,/*其他交易*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, nvL(deal.UPDATE_TIME,deal.CREATE_TIME) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, NULL BASIS, NULL FACEVALUE,/*面值*/ DECODE(deal.PS,'T99','13','T98','14' ) DEALTYPE/*交易类型：13自定义现金流收入;14自定义现金流支出*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ from TRD_PRODUCT_DEAL deal LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=deal.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=deal.COUNTER_ID
where deal.finprod_type2 = 'F23' /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*理财托管户收息确认*/ union all select NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '19' INVEST_VARIETY,/*19理财托管户收息;20其他账户收息*/ deal.INV_AIM INVEST_TYPE,/*投资目的 枚举值对应待处理*/ null PROD_ID,/*产品代码*/ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ deal.FINPROD_ID ASSET_CODE,/*行内资产负债编码*/ deal.CCY CCY,/*币种*/ deal.trade_amt AMT,/*发生金额*/ null CNY_AMT,/*折算人民币*/ 0 NUM,/*数量*/ '11' CUR_ASSET_TYPE,/*资金流动类型*/ '理财账户收息' CUR_ASSETDET_TYPE,/*资金流动类型说明*/ deal.SETTLE_DATE DEALDATE,/*交易日期*/ STI.BANK_DEP TRADE_COUNTER,/*交易对手*/ null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, deal.TRADE_ID CONTRACT_CODE, deal.REMARK REMARK, null CHL_CPCT_ID, '04' TRADE_TYPE,/*其他交易*/ NULL CHL_AGRT_NAME, decode(nvl(deal.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, nvL(deal.UPDATE_TIME,deal.CREATE_TIME) UPDATE_TIME, NULL STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE, NULL BASIS, NULL FACEVALUE,/*面值*/ '07' DEALTYPE/*交易类型：07理财托管户收息确认;11理财账户收息确认*/, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID ,'' P_TYPE_TWO /*人行二级分类*/ from TRD_PRODUCT_DEAL deal LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN STL_CAPACCT_INFO STI ON deal.FINPROD_ID = STI.ACCT_NO AND deal.CCY = STI.CCY where deal.BUSI_TYPE = '15' /*AND DEAL.TRADE_STATUS = '01'*/ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /* 增加股票和衍生品交易 add by gaojian 2019-07-19 begin */ /*股票交易*/ UNION ALL SELECT NULL TRADE_SEQNO, /*交易UUID*/ DEAL.TRADE_ID TRADE_ID, /*行内交易编码*/ '25' INVEST_VARIETY, /*投资品种*/ NULL INVEST_TYPE, /*投资类型*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ DEAL.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ DEAL.CCY CCY, /*币种*/ DECODE(DEAL.PS, 'T12', 0, NVL(DEAL.TRADE_AMT, 0)) AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ DECODE(DEAL.PS, 'T11', NVL(DEALADD.REG_DATE_AMT, 0), NVL(DEAL.SHARE_AMT, 0)) NUM, /*数量*/ CASE WHEN DEAL.PS IN ('T01', 'T46', 'T47', 'T48', 'T12') THEN '01' WHEN DEAL.PS = 'T02' THEN '02' WHEN DEAL.PS = 'T11' THEN '09' ELSE NULL END AS CUR_ASSET_TYPE, /*资金流动类型*/ CASE WHEN DEAL.PS IN ('T01', 'T02', 'T46', 'T47', 'T48', 'T12') THEN '无' WHEN DEAL.PS = 'T11' THEN '股票分红' ELSE NULL END AS CUR_ASSETDET_TYPE, /*资金流动类型说明*/ DEAL.SETTLE_DATE DEALDATE, /*交易日*/ CASE WHEN DEAL.PS IN ('T11', 'T12') THEN CUSTINFO.CUSTOMER_NAME ELSE DEAL.COUNTER_ID END AS TRADE_COUNTER, /*交易对手*/ CASE WHEN DEAL.PS IN ('T01', 'T02', 'T46', 'T47', 'T48') THEN ROUND(NVL(DEAL.TRADE_AMT, 0)/NVL(DEAL.SHARE_AMT, 1), 4) WHEN DEAL.PS = 'T12' THEN 0 ELSE NULL END AS UNIT_PRICE_FULL, /*单位成交价格（全价）*/ CASE WHEN DEAL.PS IN ('T01', 'T02', 'T46', 'T47', 'T48') THEN ROUND(NVL(DEAL.TRADE_AMT, 0)/NVL(DEAL.SHARE_AMT, 1), 4) WHEN DEAL.PS = 'T12' THEN 0 ELSE NULL END AS UNIT_PRICE_NET, /*单位成交价格（净价）*/ DEAL.YIELD END_RATE, /*到期收益率*/ DEAL.TRADE_ID CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ '01' TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(CUSTINFO.UPDATE_TIME,CUSTINFO.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ DECODE(DEAL.PS, 'T02', '09', 'T11', '20', 'T12', '05', '08') DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO CUSTINFO ON PROJECTASSET.ISSUER = CUSTINFO.CUSTOMER_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID =(CASE WHEN DEAL.PS IN ('T11', 'T12') THEN CUSTINFO.CUSTOMER_ID ELSE DEAL.COUNTER_ID END) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=(CASE WHEN DEAL.PS IN ('T11', 'T12') THEN CUSTINFO.CUSTOMER_ID ELSE DEAL.COUNTER_ID END)
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON nvl(party.counter_id,party2.counter_id) = T23.BUSINESS_ID AND T23.Data_Type in( 'MST15','PTL01') AND T22.MODEL_TYPE='02' AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 and T23.INSTITUTION_CODE IS NOT NULL and DEAL.FINPROD_TYPE2 = 'F10' AND (NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /*买入利率互换交易*/ UNION ALL SELECT NULL TRADE_SEQNO, /*交易UUID*/ DEAL.TRADE_ID TRADE_ID, /*行内交易编码*/ '26' INVEST_VARIETY, /*投资品种*/ NULL INVEST_TYPE, /*投资类型*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ FTP.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ DEAL.CCY CCY, /*币种*/ DECODE(DEAL.PS, 'T01', 0, NVL(DEAL.TRADE_AMT, 0)) AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ /*NVL(DEAL.SHARE_AMT, 0) NUM, 数量*/ NVL(TOTAL.REMAIN_PRIN, 0) NUM, DECODE (DEAL.PS, 'T01', '01', 'T07', '02', 'T98', '09', 'T99', '10') CUR_ASSET_TYPE, /*资金流动类型*/ CASE WHEN DEAL.PS = 'T98' THEN '利率互换利息收入' WHEN DEAL.PS = 'T99' THEN '利率互换利息支出' ELSE '无' END AS CUR_ASSETDET_TYPE, /*资金流动类型说明*/ DEAL.SETTLE_DATE DEALDATE, /*交易日*/ DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_NAME) TRADE_COUNTER, /*交易对手*/ CASE WHEN DEAL.PS IN ('T01', 'T02') THEN 0 ELSE NULL END AS UNIT_PRICE_FULL, /*单位成交价格（全价）*/ CASE WHEN DEAL.PS IN ('T01', 'T02') THEN 0 ELSE NULL END AS UNIT_PRICE_NET, /*单位成交价格（净价）*/ /***利率互换交易的到期收益率改成空，现在是取的trd_product_deal.YIELD(利率互换交易投管该字段存了0，不是空，导致交易信息登记该字段值为0)； leipeng 20210225****/ /*DEAL.YIELD END_RATE, 到期收益率*/ NULL END_RATE, /***利率互换交易的到期收益率改成空，现在是取的trd_product_deal.YIELD(利率互换交易投管该字段存了0，不是空，导致交易信息登记该字段值为0)； leipeng 20210225****/ DEAL.TRADE_ID CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ '01' TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(CUSTINFO.UPDATE_TIME,CUSTINFO.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ DECODE(DEAL.PS, 'T01', '08', 'T02', '09', '23') DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON DEAL.TOTLE_TRADE_ID=TOTAL.TOTLE_TRADE_ID /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.FINPROD_ID = FTP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY CUSTINFO ON FTP.COUNTER_ID = CUSTINFO.COUNTER_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_ID)
WHERE DEAL.FINPROD_TYPE2 = 'F14' AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) and nvL(deal.p_trade_id,'NOREV') = 'NOREV' /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ and deal.ps not in ('T01','T07') /***TOS-253 【交易信息登记-集成测试】：利率互换交易信息登记相关问题，详见附件 leipeng 20210225****/ /*债券借贷交易*/ UNION ALL SELECT NULL TRADE_SEQNO, /*交易UUID*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' ELSE DEAL.TRADE_ID END AS TRADE_ID, /*行内交易编码*/ '27' INVEST_VARIETY, /*投资品种*/ NULL INVEST_TYPE, /*投资类型*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ FTP.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ DEAL.CCY CCY, /*币种*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN 0 ELSE NVL(DEAL.TRADE_AMT, 0) END AS AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ DEAL.SHARE_AMT NUM, /*数量*/ CASE WHEN DEAL.PS = 'T01' THEN '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '02' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F29' THEN '10' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F30' THEN '09' ELSE NULL END AS CUR_ASSET_TYPE, /*资金流动类型*/ CASE WHEN DEAL.PS = 'T01' THEN '无' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '无' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F29' THEN '债券借贷费用支出' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F30' THEN '债券借贷费用收入' ELSE NULL END AS CUR_ASSETDET_TYPE, /*资金流动类型说明*/ DEAL.SETTLE_DATE DEALDATE, /*交易日*/ DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_NAME) TRADE_COUNTER, /*交易对手*/ CASE WHEN DEAL.PS = 'T01' THEN 0 WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN 0 ELSE NULL END AS UNIT_PRICE_FULL, /*单位成交价格（全价）*/ CASE WHEN DEAL.PS = 'T01' THEN 0 WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN 0 ELSE NULL END AS UNIT_PRICE_NET, /*单位成交价格（净价）*/ DEAL.YIELD END_RATE, /*到期收益率*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' WHEN DEAL.PS = 'T01' THEN nvl(DEAL.F_TRADE_ID,DEAL.TRADE_ID) ELSE DEAL.TRADE_ID END AS CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN '04' ELSE '01' END AS TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(CUSTINFO.UPDATE_TIME,CUSTINFO.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(PROJECTASSET.UPDATE_TIME,PROJECTASSET.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE, /*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '09' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN '10' ELSE '08' END AS DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TEMP_BOND_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.FINPROD_ID = FTP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY CUSTINFO ON FTP.COUNTER_ID = CUSTINFO.COUNTER_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_ID) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DECODE (DEAL.PS, 'T01', DEAL.COUNTER_ID, CUSTINFO.COUNTER_ID)
WHERE nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) UNION ALL /*可转债申购*/ select NULL TRADE_SEQNO , /* 交易UUID */ deal.TRADE_ID TRADE_CODE , /* 行内交易编码*/ '01' INVEST_VARIETY , /* 投资品种 */ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE ,/*投资类型*/ DEALADD.PORTFOLIO_ID PROD_ID , /*产品代码 */ deal.regist_org REGIST_BANK_CODE,/*登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE,/*行内资产/负债编码 关联金融产品表得到市场代码 */ DEAL.CCY CCY, /* 币种 参考数据字典：CURRENCY_CHB */ DEAL.FPRICE_AMT AMT , /*发生金额 */ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DEAL.SHARE_AMT*100 NUM, /*数量 */ '01' CUR_ASSET_TYPE , /*资金流动类型 */ '无' CUR_ASSETDET_TYPE, /* 资金流动类型说明 */ DEAL.SETTLE_DATE DEALDATE, /*交易日*/ DEAL.COUNTER_ID TRADE_COUNTER, /*交易对手*/ 100 UNIT_PRICE_FULL , /* 单位成交价格（全价）*/ 100 UNIT_PRICE_NET, /*单位成交价格（净价）*/ DEAL.YIELD END_RATE ,/* 到期收益率 */ nvl(DEAL.F_TRADE_ID,DEAL.TRADE_ID) CONTRACT_CODE , /*成交编号/合同号 */ null REMARK ,/* 备注*/ null CHL_CPCT_ID , /*通道代码 */ '01' TRADE_TYPE,/* 交易类型 */ null CHL_AGRT_NAME ,/*通道名称*/ '02' IS_UNDER_TRADE , /*是否底层交易流水 01 是/ 02 否 */ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*数据状态 D 删除 A 待处理 E 有效*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ deal.CREATE_USER CREATE_USER, /*创建人*/ deal.CREATE_TIME CREATE_TIME, /* 创建时间 */ deal.UPDATE_USER UPDATE_USER, /* 更新人 */ greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME,/*更新时间*/ NULL STATUS_DATE,/*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ DEAL.PAR_VALUE FACEVALUE ,/*面值 */ '08' DEALTYPE , /*交易类型 */ deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, null F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DEAL.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DEAL.COUNTER_ID
where 1=1 and deal.PS='T05' and deal.finprod_type2='F01' and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) AND nvl(deal.p_trade_id,'NOREV')='NOREV'/*不取撤销交易*/ UNION ALL /*债转股(债券卖出)*/ select NULL TRADE_SEQNO ,/*交易UUID*/ DEAL.TRADE_ID||'01' TRADE_CODE,/*行内交易编码 */ '01' INVEST_VARIETY ,/*投资品种*/ decode(DEAL.INV_AIM,'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资类型投资目的 枚举值对应待处理TODO*/ DEALADD.PORTFOLIO_ID PROD_ID , /* 产品代码 */ deal.regist_org REGIST_BANK_CODE,/*发行机构代码登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE , /*行内资产负债编码 */ DEAL.CCY CCY ,/*币种 */ /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ BARTER.PRIN_AMT AMT ,/*发生金额 */ /* DEAL.SHARE_AMT*100-DEAL.TRADE_AMT AMT,发生金额 */ /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DEAL.SHARE_AMT*100 NUM ,/*数量 */ '02' CUR_ASSET_TYPE，/*资金流动类型 */ '无' CUR_ASSETDET_TYPE，/*资金流动类型说明*/
/****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ DEAL.TRADE_DATE DEALDATE, /*交易日 */ /*DEAL.SETTLE_DATE DEALDATE, 交易日 */ /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ DEAL.COUNTER_ID TRADE_COUNTER, /*交易对手 */ ROUND((DEAL.SHARE_AMT*100-DEAL.TRADE_AMT)/DEAL.SHARE_AMT,4) UNIT_PRICE_FULL ,/*单位成交价格（全价）*/ ROUND((DEAL.SHARE_AMT*100-DEAL.TRADE_AMT)/DEAL.SHARE_AMT,4) UNIT_PRICE_NET ,/*单位成交价格（净价） */ NULL END_RATE ,/*到期收益率 */ DEAL.TRADE_ID||'01' CONTRACT_CODE ,/*成交编号/合同号 */ NULL REMARK ,/*备注 */ NULL CHL_CPCT_ID ,/* 通道代码 */ '01' TRADE_TYPE ,/* 交易类型 */ NULL CHL_AGRT_NAME,/* 通道名称 */ '02' IS_UNDER_TRADE ,/*是否底层交易流水 01 是/ 02 否 */ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*数据状态 D 删除 A 待处理 E 有效 */ NULL ORG_CODE, /*机构代码 */ NULL DEPT_CODE, /*部门代码 */ deal.CREATE_USER CREATE_USER, /*创建人 */ deal.CREATE_TIME CREATE_TIME, /* 创建时间 */ deal.UPDATE_USER UPDATE_USER, /* 更新人 */ greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME,/*更新时间*/ NULL STATUS_DATE,/*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*利率 */ NULL BASIS , /*计息基础 */ DEAL.PAR_VALUE FACEVALUE,/*面值 */ '09' DEALTYPE ,/*交易类型 */ deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, null F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ left join TRD_FIN_PRODUCT_BARTER BARTER on deal.TRADE_ID=BARTER.TRADE_ID /****TOS-260 【交易信息登记-集成测试】：可转债转股交易，交易信息登记不正确，详见描述 leipeng 20210227****/ LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DEAL.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DEAL.COUNTER_ID
