DEAL.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DEAL.COUNTER_ID
where 1=1 and BARTER.TRADE_ID is not null /*存了一条股票的记录*/ and deal.PS='T49' and deal.finprod_type2='F01' and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) UNION ALL /*债转股(投资收益)*/ select NULL TRADE_SEQNO ,/*交易UUID */ DEAL.TRADE_ID||'03' TRADE_CODE,/*行内交易编码 */ '01' INVEST_VARIETY ,/*投资品种*/ null INVEST_TYPE,/*投资类型 */ DEALADD.PORTFOLIO_ID PROD_ID , /* 产品代码*/ deal.regist_org REGIST_BANK_CODE,/*发行机构代码登记银行编码*/ DEAL.FINPROD_ID ASSET_CODE , /*行内资产/负债编码 */ DEAL.CCY CCY ,/*币种 */ DEAL.TRADE_AMT AMT ,/*发生金额 */ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DEALADD.SPO_SHARE_NUM NUM ,/*数量 */ '09' CUR_ASSET_TYPE,/*资金流动类型*/ '零股折算现金' CUR_ASSETDET_TYPE,/*资金流动类型说明 */ DEAL.SETTLE_DATE DEALDATE, /*交易日 */ DEAL.COUNTER_ID TRADE_COUNTER, /*交易对手 */ NULL UNIT_PRICE_FULL ,/*单位成交价格（全价）*/ NULL UNIT_PRICE_NET ,/*单位成交价格（净价）*/ NULL END_RATE ,/*到期收益率 */ DEAL.TRADE_ID||'03' CONTRACT_CODE ,/*成交编号/合同号 */ NULL REMARK ,/*备注 */ NULL CHL_CPCT_ID ,/* 通道代码 */ '01' TRADE_TYPE ,/* 交易类型 */ NULL CHL_AGRT_NAME,/* 通道名称 */ '02' IS_UNDER_TRADE ,/*是否底层交易流水 01 是/ 02 否 */ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*数据状态 D 删除 A 待处理 E 有效 */ NULL ORG_CODE, /*机构代码 */ NULL DEPT_CODE, /*部门代码 */ deal.CREATE_USER CREATE_USER, /*创建人*/ deal.CREATE_TIME CREATE_TIME, /* 创建时间*/ deal.UPDATE_USER UPDATE_USER, /* 更新人 */ greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME,/*更新时间*/ NULL STATUS_DATE,/*数据日期*/ REVDL.create_time REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*利率 */ NULL BASIS , /*计息基础 */ NULL FACEVALUE,/*面值 */ '09' DEALTYPE ,/*交易类型 */ deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, null F_TRADE_ID ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DEAL.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DEAL.COUNTER_ID
where 1=1 and deal.PS='T49' and DEAL.TRADE_AMT is not null and deal.finprod_type2='F01' and (ABS(nvl(deal.share_amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*外汇放期交易*/ UNION ALL SELECT NULL TRADE_SEQNO, /*交易UUID*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' END AS TRADE_ID, /*行内交易编码*/ '28' INVEST_VARIETY, /*投资品种*/ NULL INVEST_TYPE, /*投资类型*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ FTP.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ FTP.CCY CCY, /*币种*/ 0 AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ 1 NUM, /*数量*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN '01' WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '02' THEN '02' END AS CUR_ASSET_TYPE, /*资金流动类型*/ '无' CUR_ASSETDET_TYPE, /*资金流动类型说明*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_DATE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.SETTLE_DATE END AS DEALDATE, /*交易日*/ DEAL.COUNTER_ID TRADE_COUNTER, /*交易对手*/ 0 UNIT_PRICE_FULL, /*单位成交价格（全价）*/ 0 UNIT_PRICE_NET, /*单位成交价格（净价）*/ NULL END_RATE, /*到期收益率*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' END AS CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ '01' TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')) , NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE, /*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ DECODE(DEAL.SPLIT_TYPE, '01', '08', '02', '09') DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TEMP_FES_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.FINPROD_ID = FTP.FINPROD_ID left join MST_COUNTER_PARTY party on party.COUNTER_ID=DEAL.COUNTER_ID left join MST_COUNTER_PARTY party2 on party2.LINK_ID=DEAL.COUNTER_ID
WHERE nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*外汇远期交易*/ UNION ALL select * from( SELECT NULL TRADE_SEQNO, /*交易UUID*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' ELSE DEAL.TRADE_ID END AS TRADE_ID, /*行内交易编码*/ '29' INVEST_VARIETY, /*投资品种*/ 'F12' INVEST_TYPE, /*投资类型,此处实际应该为空，赋值主要是为了在代码层面作为计算发生金额的判断条件*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ FTP.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ CASE WHEN DEAL.PS = 'T01' THEN FTP.CCY WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN FTP.CCY ELSE SUBSTR(FTP.CUR_PAIR,INSTR(FTP.CUR_PAIR,'/',-1)+1) END AS CCY, /*币种*/ 0 AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN NVL(DEAL.PRIN_AMT, 0) ELSE 1 END AS NUM, /*数量*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '02' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN '09' ELSE '01' END AS CUR_ASSET_TYPE, /*资金流动类型*/ FTP.CUR_PAIR || ':' || FTP.CCY || ':' || DEAL.CCY || ':' || FTP.EXC_PS || ':' || DEAL.PS || ':' || NVL(DEAL.FPRICE_AMT, 0) || ':' || NVL(DEAL.PRIN_AMT, 0) || ':' || NVL(DEAL.UNIT_FPRICE, 1) || ':' || DEAL.DELIVERY_TYPE CUR_ASSETDET_TYPE, /*资金流动类型说明*/ DEAL.SETTLE_DATE DEALDATE, /*交易日*/ CASE WHEN DEAL.PS = 'T01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_NAME END AS TRADE_COUNTER, /*交易对手*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN NULL ELSE 0 END AS UNIT_PRICE_FULL, /*单位成交价格（全价）*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN NULL ELSE 0 END AS UNIT_PRICE_NET, /*单位成交价格（净价）*/ NULL END_RATE, /*到期收益率*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' ELSE DEAL.TRADE_ID END AS CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN '04' ELSE '01' END AS TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(MEQ.UPDATE_TIME,MEQ.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE, /*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ CASE WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '09' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '02' THEN '10' ELSE '08' END AS DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TEMP_FEF_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.FINPROD_ID = FTP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCP ON FTP.COUNTER_ID = MCP.COUNTER_ID LEFT JOIN rate MEQ ON FTP.CUR_PAIR = MEQ.EXCHARGE_CODE left join MST_COUNTER_PARTY party on party.COUNTER_ID=(CASE WHEN DEAL.PS = 'T01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_ID END) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=(CASE WHEN DEAL.PS = 'T01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_ID END)
WHERE nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) )where to_char(dealdate,'yyyy-MM-dd')>=to_char(update_time,'yyyy-MM-dd') /*外汇掉期交易*/ UNION ALL select * from( SELECT NULL TRADE_SEQNO, /*交易UUID*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' END AS TRADE_ID, /*行内交易编码*/ '30' INVEST_VARIETY, /*投资品种*/ 'F13' INVEST_TYPE, /*投资类型,此处实际应该为空，赋值主要是为了在代码层面作为计算发生金额的判断条件*/ DEALADD.PORTFOLIO_ID PROD_ID, /*产品代码*/ DEAL.REGIST_ORG REGIST_BANK_CODE, /*发行机构代码*/ FTP.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN FTP.CCY WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN FTP.CCY ELSE SUBSTR(FTP.CUR_PAIR,INSTR(FTP.CUR_PAIR,'/',-1)+1) END AS CCY, /*币种*/ 0 AMT, /*发生金额*/ NULL CNY_AMT, /*折算人民币金额*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN 1 WHEN DEAL.SPLIT_TYPE = '02' THEN DEAL.PRIN_AMT END AS NUM, /*数量*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN '01' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '02' ELSE '09' END AS CUR_ASSET_TYPE, /*资金流动类型*/ FTP.CUR_PAIR || ':' || FTP.CCY || ':' || DEAL.CCY || ':' || FTP.EXC_PS || ':' || DEAL.PS || ':' || NVL(DEAL.FPRICE_AMT, 0) || ':' || NVL(DEAL.PRIN_AMT, 0) CUR_ASSETDET_TYPE, /*资金流动类型说明*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_DATE ELSE DEAL.SETTLE_DATE END AS DEALDATE, /*交易日*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_NAME END AS TRADE_COUNTER, /*交易对手*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN 0 ELSE NULL END AS UNIT_PRICE_FULL, /*单位成交价格（全价）*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN 0 ELSE NULL END AS UNIT_PRICE_NET, /*单位成交价格（净价）*/ NULL END_RATE, /*到期收益率*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN DEAL.TRADE_ID || '01' WHEN DEAL.SPLIT_TYPE = '02' THEN DEAL.TRADE_ID || '02' END AS CONTRACT_CODE, /*成交编号/合同号*/ NULL REMARK, /*备注*/ NULL CHL_CPCT_ID, /*通道代码*/ CASE WHEN DEAL.SPLIT_TYPE = '01' THEN '01' WHEN DEAL.SPLIT_TYPE = '02' THEN '04' END AS TRADE_TYPE, /*交易类型*/ NULL CHL_AGRT_NAME, /*通道名称*/ '02' IS_UNDER_TRADE, /*是否底层交易流水 01 是/ 02 否*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, /*机构代码*/ NULL DEPT_CODE, /*部门代码*/ DEAL.CREATE_USER CREATE_USER, /*创建人*/ DEAL.CREATE_TIME CREATE_TIME, /*创建时间*/ DEAL.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(MEQ.UPDATE_TIME,MEQ.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(MCP.UPDATE_TIME,MCP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(party.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, /*更新时间*/ NULL STATUS_DATE, /*数据日期*/ REVDL.create_time REV_DATE, /*撤销日*/ NULL DATA_SOURCE, /*数据来源*/ NULL RATE, /*利率*/ NULL BASIS, /*计息基础*/ NULL FACEVALUE, /*面值*/ CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN '08' WHEN DEAL.PS = 'T07' AND DEAL.SPLIT_TYPE = '01' THEN '09' ELSE '10' END AS DEALTYPE, /*交易类型*/ DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, /*汇总交易编号*/ DEALADD.REG_DATE_AMT INTPAYAMT, /*当日分红累计份额*/ DEAL.F_TRADE_ID F_TRADE_ID /*关联系统交易编号*/ ,nvl(party.P_TYPE_TWO,party2.P_TYPE_TWO) P_TYPE_TWO/*人行二级分类*/ FROM TEMP_FESW_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.FINPROD_ID = FTP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCP ON FTP.COUNTER_ID = MCP.COUNTER_ID LEFT JOIN rate MEQ ON FTP.CUR_PAIR = MEQ.EXCHARGE_CODE left join MST_COUNTER_PARTY party on party.COUNTER_ID=(CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_ID END) left join MST_COUNTER_PARTY party2 on party2.LINK_ID=(CASE WHEN DEAL.PS = 'T01' AND DEAL.SPLIT_TYPE = '01' THEN DEAL.COUNTER_ID ELSE MCP.COUNTER_ID END)
WHERE nvL(deal.p_trade_id,'NOREV') = 'NOREV' AND (NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) )where to_char(dealdate,'yyyy-MM-dd')>=to_char(update_time,'yyyy-MM-dd') /**增加股票和衍生品交易 add by gaojian 2019-07-19 end**/ union all
SELECT DISTINCT NULL TRADE_SEQNO, DEAL.TOTLE_TRADE_ID TRADE_ID, /*DECODE(nvl(PLANASSET.PROFIT_TYPE,PLANASSETDETAIL.PROFIT_TYPE),'01','04','02','03','03','05') INVEST_VARIETY,投资品种根据收益类型分类*/ CASE WHEN DEAL.FINPROD_TYPE2 = 'F01' THEN '01' WHEN DEAL.FINPROD_TYPE2 = 'F07' THEN '06' WHEN DEAL.FINPROD_TYPE2 = 'F17' THEN '03' WHEN DEAL.FINPROD_TYPE2 = 'F18' THEN '15' ELSE NULL END INVEST_VARIETY, DECODE(NVL(DEAL.INV_AIM,DEALADD.INV_AIM),'FVTPL','TRA','AC','HTM','FVOCI','AFS') INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ NULL PROD_ID,/*取自从属表*/ ORG.REGIST_ORG REGIST_BANK_CODE,/*登记银行编码*/ NVL(PLANASSET.FINPROD_ID,PLANASSETDETAIL.FINPROD_ID) ASSET_CODE, DEAL.CCY CCY, DECODE(DEAL.PS,'T01',DEAL.TRADE_AMT,'T11',DEAL.INT_AMT,'T12',DEAL.INT_AMT,'T23',TOTALDEAL.TRADE_AMT,DEAL.TRADE_AMT) AMT,/*对于计划类资产，红利再投及分红 发生金额直接取int_amt*/ NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DECODE(DEAL.FINPROD_TYPE2,'F01', CASE WHEN FTPTRADE.BRANCH_TYPE='D01' THEN (CASE WHEN PLANASSETDETAIL.MDATE=FTPTRADE.MDATE THEN NVL((DEAL.PRIN_AMT/FTPTRADE.M_PRIN_AMT),0)*100 /**到期还本*/ ELSE 0 /**中间还本*/ END) ELSE 0 /**中间付息*/ END ,NVL(NVL(DEAL.SHARE_AMT,DEAL.PRIN_AMT),0) ) NUM, CASE WHEN DEAL.FINPROD_TYPE2 = 'F07' AND FPT.TYPE_6 = 'D01' THEN DECODE(DEAL.PS,'T01','05','T02','07') WHEN DEAL.FINPROD_TYPE2 = 'F07' AND FPT.TYPE_6 != 'D01' THEN DECODE(DEAL.PS,'T01','03','T02','04') ELSE DECODE(DEAL.PS,'T01','01','T02','02','T22','09','T23','02','T05','01','T19','02','T11','09','T12','01','C3','01','C06','02') END CUR_ASSET_TYPE,/*计划类资产红利再投另加一笔投资收益*/ DECODE(DEAL.PS,'T22',DECODE(TOTALDEAL.PS,'T08','部分到期-收息','T09','收息','T07','收息'),'T23',DECODE(TOTALDEAL.PS,'T08','部分到期','T07','到期'),'T11','资产分红') CUR_ASSETDET_TYPE,/*针对不同的收息：中间收息：债券收息交易，部分还本收息：债券中间还本交易，到期收息：债券到期利息收入*/ DEAL.SETTLE_DATE DEALDATE, DECODE(DEAL.PS,'T22',CUSTINFO.CUSTOMER_NAME,'T23',CUSTINFO.CUSTOMER_NAME,'T11',CUSTINFO.CUSTOMER_NAME,'T12',CUSTINFO.CUSTOMER_NAME,DEAL.COUNTER_ID) TRADE_COUNTER,/*对手方*/ ROUND(DECODE(DEAL.FINPROD_TYPE2,'F01', CASE WHEN FTPTRADE.BRANCH_TYPE='D01' THEN (CASE WHEN PLANASSETDETAIL.MDATE=FTPTRADE.MDATE THEN (DEAL.TRADE_AMT/((DEAL.PRIN_AMT/FTPTRADE.M_PRIN_AMT)*100))*100 /**到期还本*/ ELSE 0 /**中间还本*/ END ) ELSE 0 /**中间付息*/ END ,DECODE(DEAL.FINPROD_TYPE2 ,'F07',NULL, DECODE(NVL(NVL(DEAL.SHARE_AMT,DEAL.PRIN_AMT),0),0,0,DEAL.TRADE_AMT/NVL(NVL(DEAL.SHARE_AMT,DEAL.PRIN_AMT),0))*100) ),4) UNIT_PRICE_FULL, ROUND(DECODE(DEAL.FINPROD_TYPE2,'F01', CASE WHEN FTPTRADE.BRANCH_TYPE='D01' THEN (CASE WHEN PLANASSETDETAIL.MDATE=FTPTRADE.MDATE THEN (DEAL.TRADE_AMT/((DEAL.PRIN_AMT/FTPTRADE.M_PRIN_AMT)*100))*100 /**到期还本*/ ELSE 0 /**中间还本*/ END ) ELSE 0 /**中间付息*/ END ,DECODE(DEAL.FINPROD_TYPE2 ,'F07',NULL, DECODE(NVL(NVL(DEAL.SHARE_AMT,DEAL.PRIN_AMT),0),0,0,100))/*项目类计划类当数量为0时，单位净价取0，否则100*/ ),4) UNIT_PRICE_NET, DECODE(DEAL.PS,'T23',DECODE(TOTALDEAL.PS,'T07',DEAL.YIELD)) END_RATE, NVL(NVL(PLANASSET.CONTRACT_NO,PLANASSETDETAIL.CONTRACT_NO),DEAL.TOTLE_TRADE_ID) CONTRACT_CODE, DEAL.REMARK REMARK, DEAL.CHL_ID CHL_CPCT_ID, '01' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, DECODE(NVL(DEAL.CHL_ID,'NCHL'),'NCHL','02') IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(DEAL.IS_CANCEL,'N','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, DEAL.CREATE_USER CREATE_USER, DEAL.CREATE_TIME CREATE_TIME, DEAL.UPDATE_USER UPDATE_USER, GREATEST(NVL(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), NVL(NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), NVL(NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), NVL(NVL(CUSTINFO.UPDATE_TIME,CUSTINFO.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), NVL(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),TO_DATE('1900-01-01','yyyy-MM-dd')), NVL(PARTY.UPDATE_TIME,party2.UPDATE_TIME) ) UPDATE_TIME, NULL STATUS_DATE, REVDL.CREATE_TIME REV_DATE,/*撤销日*/ NULL DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ NULL FACEVALUE,/*面值*/ DECODE(DEAL.PS,'T01','08','T02','09','T22',DECODE(TOTALDEAL.PS,'T08','25','T09','23','T07','02'),'T23',DECODE(TOTALDEAL.PS,'T08','24','T07','01'),'T05','12','T19','15','T11','20','T12','05','C3','04','C06','03') DEALTYPE/*收息具体类型在后续判断*/, DEAL.TOTLE_TRADE_ID TOTLE_TRADE_ID, DEALADD.REG_DATE_AMT INTPAYAMT, DEAL.F_TRADE_ID F_TRADE_ID ,DECODE(PARTY.COUNTER_TYPE,'05','C0500',NVL(PARTY.P_TYPE_TWO,party2.P_TYPE_TWO)) P_TYPE_TWO/*人行二级分类*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL
LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL REVDL ON DEAL.TOTLE_TRADE_ID = REVDL.P_TRADE_ID
LEFT JOIN FIN_PRODUCT PLANASSETDETAIL ON DEAL.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID
LEFT JOIN FIN_PRODUCT PLANASSET ON PLANASSETDETAIL.P_FINPROD_ID = PLANASSET.FINPROD_ID
LEFT JOIN MST_CUSTOMER_INFO CUSTINFO ON NVL(PLANASSET.MANAGER,PLANASSETDETAIL.MANAGER) = CUSTINFO.CUSTOMER_ID
LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL ON DEAL.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID
LEFT JOIN ( SELECT DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID, SUM(NVL(DEALADD.REG_DATE_AMT,0)) REG_DATE_AMT, DEAL.INV_AIM FROM TRD_PRODUCT_DEAL_ADD DEALADD
LEFT JOIN TRD_PRODUCT_DEAL DEAL ON DEALADD.TRADE_ID = DEAL.TRADE_ID GROUP BY DEAL.TOTLE_TRADE_ID,DEALADD.PORTFOLIO_ID,DEAL.INV_AIM ) DEALADD ON (DEALADD.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID OR DEAL.P_TOTLE_TRADE_ID= DEALADD.TOTLE_TRADE_ID)
LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEALPA ON DEAL.TOTLE_TRADE_ID = TOTALDEALPA.TOTLE_TRADE_ID
LEFT JOIN ( SELECT TOTLE_TRADE_ID ,REGIST_ORG FROM TRD_PRODUCT_DEAL GROUP BY TOTLE_TRADE_ID ,REGIST_ORG ) ORG ON ORG.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID
LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALREVDL ON DEAL.TOTLE_TRADE_ID = NVL(TOTALREVDL.P_TRADE_ID,TOTALREVDL.P_TOTLE_TRADE_ID)
LEFT JOIN TRD_PRODUCT_DEAL TPDEAL ON TPDEAL.TOTLE_TRADE_ID=DEAL.TOTLE_TRADE_ID OR DEAL.P_TOTLE_TRADE_ID=TPDEAL.TOTLE_TRADE_ID
INNER JOIN FIN_TRADE_PRODUCT FTPTRADE ON FTPTRADE.FINPROD_ID=TPDEAL.FINPROD_ID AND TPDEAL.BRANCH=FTPTRADE.BRANCH AND FTPTRADE.BRANCH_TYPE IN ('D01','D02')
LEFT JOIN FIN_PRODUCT_TYPE FPT ON DEAL.FINPROD_ID = FPT.FINPROD_ID
LEFT JOIN MST_COUNTER_PARTY MCP ON FTPTRADE.COUNTER_ID = MCP.COUNTER_ID
LEFT JOIN MST_COUNTER_PARTY PARTY ON PARTY.COUNTER_ID=DEAL.COUNTER_ID LEFT JOIN MST_COUNTER_PARTY PARTY2 ON PARTY2.LINK_ID=DEAL.COUNTER_ID
LEFT JOIN DATA_AUTH_NOTIFY_INST T22 ON DEALADD.PORTFOLIO_ID = T22.BUSINESS_ID AND T22.DATA_TYPE = 'PTL01' AND T22.MODEL_TYPE='02' LEFT JOIN DATA_AUTH_NOTIFY_INST T23 ON NVL(party.counter_id, party2.counter_id) = T23.BUSINESS_ID AND T23.DATA_TYPE = 'PTL01' AND T23.MODEL_TYPE='02' AND T22.INSTITUTION_CODE=T23.INSTITUTION_CODE WHERE 1=1 AND T23.INSTITUTION_CODE IS NOT NULL AND DECODE (SIGN(DEAL.PRIN_AMT - 0),1,'D01','D02') = FTPTRADE.BRANCH_TYPE /*中间还本以及到期会出重复数据，修改为到期以及中间还本按照D01出一笔数据，收息按D02出一笔*/ /***筛选141数据***/ AND EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL A LEFT JOIN TRD_PRODUCT_DEAL_ADD AD ON A.TRADE_ID = AD.TRADE_ID WHERE (A.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID OR DEAL.P_TOTLE_TRADE_ID=A.TOTLE_TRADE_ID ) /*只接入原始交易数据*/ AND NVL(A.P_TRADE_ID,'NOREV') = 'NOREV' AND A.TG_BUSI_TYPE='141' AND AD.PORTFOLIO_ID=DEALADD.PORTFOLIO_ID AND A.PS IN ('T25','T26') AND EXISTS( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = A.TRADE_ID ) ) /*根据交割日和接口接入时间接入数据*/ AND( NVL(deal.UPDATE_TIME,deal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSETDETAIL.UPDATE_TIME,PLANASSETDETAIL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(PLANASSET.UPDATE_TIME,PLANASSET.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(custinfo.UPDATE_TIME,custinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}
or NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(TPDEAL.UPDATE_TIME,TPDEAL.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(FTPTRADE.UPDATE_TIME,FTPTRADE.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(party.UPDATE_TIME,party2.UPDATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) ) SELECT DISTINCT * FROM ( SELECT investdeal.TRADE_SEQNO TRADE_SEQNO, investdeal.TRADE_Id TRADE_CODE, investdeal.INVEST_VARIETY INVEST_VARIETY, INVESTDEAL.INVEST_TYPE INVEST_TYPE, NVL(nvl(ppf.parent_portfolio_id,dealtotal.PORTFOLIO_ID),dealadd.PORTFOLIO_ID) PROD_ID, investdeal.REGIST_BANK_CODE REGIST_BANK_CODE, CASE WHEN investdeal.INVEST_VARIETY IN ('26', '27', '28', '29', '30') THEN investdeal.ASSET_CODE ELSE nvl(fp.FINPROD_MARKET_ID, fp2.FINPROD_ID) END AS ASSET_CODE, investdeal.CCY CCY, investdeal.amt amt, investdeal.CNY_AMT CNY_AMT, nvl(investdeal.NUM,DEALTOtAL.share_amt) NUM,/*付息时取total*/ investdeal.CUR_ASSET_TYPE CUR_ASSET_TYPE, investdeal.CUR_ASSETDET_TYPE CUR_ASSETDET_TYPE, investdeal.DEALDATE DEALDATE, investdeal.TRADE_COUNTER TRADE_COUNTER, investdeal.UNIT_PRICE_FULL UNIT_PRICE_FULL, investdeal.UNIT_PRICE_NET UNIT_PRICE_NET, investdeal.END_RATE END_RATE, investdeal.CONTRACT_CODE CONTRACT_CODE, investdeal.REMARK REMARK, CHLINFO.FINPROD_MARKET_ID CHL_CPCT_ID, investdeal.TRADE_TYPE TRADE_TYPE, investdeal.CHL_AGRT_NAME CHL_AGRT_NAME, INVESTDEAL.IS_UNDER_TRADE IS_UNDER_TRADE, investdeal.STATUS, investdeal.ORG_CODE ORG_CODE, investdeal.DEPT_CODE DEPT_CODE, investdeal.CREATE_USER CREATE_USER, investdeal.CREATE_TIME CREATE_TIME, investdeal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(investdeal.UPDATE_TIME,investdeal.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(ppf.UPDATE_TIME,ppf.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(investdeal.REV_DATE,investdeal.REV_DATE),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALTOtAL.UPDATE_TIME,DEALTOtAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(CHLINFO.UPDATE_TIME,CHLINFO.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME, INVESTDEAL.STATUS_DATE STATUS_DATE, investdeal.REV_DATE REV_DATE,/*撤销日*/ investdeal.data_source data_source, investdeal.rate rate, investdeal.BASIS BASIS, investdeal.DEALTYPE DEALTYPE, INVESTDEAL.FACEVALUE FACEVALUE, investdeal.INTPAYAMT INTPAYAMT, investdeal.F_TRADE_ID F_TRADE_CODE ,FRA.PAY_TYPE ,case when investdeal.CUR_ASSET_TYPE not in ('01','02','03','04','05','06','07','08') then null else case when investdeal.INVEST_VARIETY = '01' /*债券*/ then decode(investdeal.INVEST_TYPE,'HTM','02','TRA','01','AFS','01') when investdeal.INVEST_VARIETY in ('03','06','07','08','09','10','11','12','15') then '02' when investdeal.INVEST_VARIETY in ('13','14','25','04','05','26','27','28','29','30','31') then '01' end end as ASSET_METHOD /*资产计量方式*/ ,case when investdeal.INVEST_VARIETY ='22' then '99' /*营改增缴纳，默认99*/ when investdeal.INVEST_VARIETY ='19' then case when investdeal.TRADE_COUNTER like '%银行%' then '04' else '06' end else decode(investdeal.P_TYPE_TWO,'C0100','01','C0200','02','C0300','03','C0400','04','C0401','05','C0402','06','C0500','07','C0501','08','C0502','09','C0503','10','C0504','11','C0505','12','C0506','13','C0507','14','C0508','15','C0509','16','C0600','17',null) end as RIVAL_PARTY_TYPE FROM INVESTDEAL investdeal LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD/*交易从属表*/ /*ON DEALADD.TRADE_ID = INVESTDEAL.TRADE_ID*/ ON (DEALADD.TRADE_ID = INVESTDEAL.TRADE_ID OR DEALADD.TRADE_ID || '01' = INVESTDEAL.TRADE_ID OR DEALADD.TRADE_ID || '02' = INVESTDEAL.TRADE_ID ) /*关联FIN_PRODUCT及FIN_TRADE_PRODUCT重新获取资产代码*/
left join FIN_PRODUCT fp on fp.FINPROD_ID = investdeal.ASSET_CODE left join FIN_TRADE_PRODUCT fp2 on fp2.FINPROD_ID = investdeal.ASSET_CODE and fp2.branch = 0 LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL DEALTOtAL/*产品代码取不到取total表如：买断式回购*/ on INVESTDEAL.TOTLE_TRADE_ID = DEALTOtAL.TOTLE_TRADE_ID left join ptl_portfolio ppf on ppf.portfolio_id=nvl(DEALTOtAL.Portfolio_Id,dealadd.Portfolio_Id) LEFT JOIN FIN_PRODUCT CHLINFO/*通道信息*/ on CHLINFO.FINPROD_ID = investdeal.CHL_CPCT_ID LEFT JOIN FIN_PRODUCT_ADD FRA ON investdeal.CHL_CPCT_ID = FRA.FINPROD_ID LEFT JOIN (select DISTINCT FINPROD_MARKET_ID from FIN_PRODUCT where FINPROD_TYPE2='F16') fpd ON fpd.FINPROD_MARKET_ID=NVL(ppf.parent_portfolio_id,ppf.portfolio_id) where 1= 1 AND( NVL(investdeal.UPDATE_TIME,investdeal.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(ppf.UPDATE_TIME,ppf.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(investdeal.REV_DATE,to_date('1900-01-01','yyyy-MM-dd')) > #{interfDate,jdbcType=TIMESTAMP} or NVL(CHLINFO.UPDATE_TIME,CHLINFO.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*过滤估值生成交易*/ AND (EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND (case when investdeal.INVEST_VARIETY = '17' then investdeal.TOTLE_TRADE_ID else investdeal.TRADE_ID end) = PTLTRADE.BUSI_NO ) /*可转债交易编号拼接特殊处理 start*/ OR EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND busi_type ='TRD63' AND (PTLTRADE.BUSI_NO||'01' = investdeal.TRADE_ID OR PTLTRADE.BUSI_NO||'02' = investdeal.TRADE_ID OR PTLTRADE.BUSI_NO||'03' = investdeal.TRADE_ID ) ) /*可转债交易编号拼接特殊处理 end*/ /***添加项目类及债权类筛选..过滤估值生成交易在基础查询时已经过滤**/ OR investdeal.INVEST_VARIETY IN ('27', '28', '29', '30','31','15','03','04','05') OR (investdeal.INVEST_VARIETY IN ('01','06') and DEALTOtAL.TG_BUSI_TYPE='141') ) /* 去除估值核算自动生成交易 */ AND NVL(investdeal.CUR_ASSET_TYPE,'NOTYPE') != 'NOTYPE' and fpd.FINPROD_MARKET_ID is not null
/* 产品代码不为空时 */
#{prodCode,jdbcType=VARCHAR}
)

WITH INVESTDEAL AS( SELECT NULL TRADE_SEQNO, deal.TRADE_ID TRADE_ID, '05' INVEST_VARIETY,/*投资品种*/ null INVEST_TYPE,/*投资目的 枚举值对应待处理TODO*/ null PROD_ID,/*取自从属表*/ cpb.ISSUE_PARTY_ID REGIST_BANK_CODE,/*登记银行编码*/ chl.FINPROD_MARKET_ID ASSET_CODE, DEAL.CCY CCY, deal.trade_amt AMT, NULL CNY_AMT,/*折算后人民币在街口中单独处理*/ DECODE(DEAL.PS,'HK09',DEAL.TRADE_AMT,DEAL.PRIN_AMT) NUM, DECODE(DEAL.PS,'HK09','01',decode(DEAL.PRIN_AMT,'0','09','02')) CUR_ASSET_TYPE,/*还款是买入，回款是卖出*/ DECODE(DEAL.PS,'HK09','无',decode(DEAL.PRIN_AMT,'0','通道收益','无')) CUR_ASSETDET_TYPE,/*默认为无*/ DEAL.SETTLE_DATE DEALDATE, chl.manager TRADE_COUNTER, DECODE(DEAL.PS,'HK09','1',DECODE(DEAL.PRIN_AMT,'0',null,deal.trade_amt/DEAL.PRIN_AMT)) UNIT_PRICE_FULL, decode(DEAL.PRIN_AMT,'0',null,'1') UNIT_PRICE_NET, '' END_RATE, DEAL.TRADE_ID CONTRACT_CODE, DEAL.REMARK REMARK, '' CHL_CPCT_ID, '05' TRADE_TYPE,/*后续判断是否为资管计划交易,即资产一级分类为资管计划*/ NULL CHL_AGRT_NAME, '02' IS_UNDER_TRADE,/*资产交易才为底层（通道投资）,资管计划交易不为底层*/ DECODE(NVL(REVDL.TRADE_ID,'NCANCEL'),'NCANCEL','E','D') STATUS,/*撤销的数据改变有效状态*/ NULL ORG_CODE, NULL DEPT_CODE, deal.CREATE_USER CREATE_USER, deal.CREATE_TIME CREATE_TIME, deal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(DEAL.UPDATE_TIME,DEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(secASSET.UPDATE_TIME,secASSET.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(REVDL.UPDATE_TIME,REVDL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(TOTALDEAL.UPDATE_TIME,TOTALDEAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME, sysdate STATUS_DATE, REVDL.create_time REV_DATE,/*撤销日*/ 'DB' DATA_SOURCE, NULL RATE,/*取中债系统中的资产收益率*/ NULL BASIS, /*取中债系统中的资产计息基础*/ '' FACEVALUE,/*面值*/ DECODE(DEAL.PS,'HK09','17',decode(DEAL.PRIN_AMT,'0','23','18')) DEALTYPE, deal.TOTLE_TRADE_ID TOTLE_TRADE_ID, null INTPAYAMT, deal.F_TRADE_ID F_TRADE_ID FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN FIN_PRODUCT secASSET on deal.FINPROD_ID = secASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID left join fin_product chl on chl.finprod_id=DEAL.Chl_Id LEFT JOIN TRD_PRODUCT_DEAL REVDL /*ON INVESTDEAL.TRADE_ID = REVDL.P_TRADE_ID*/ ON (deal.TRADE_ID = REVDL.P_TRADE_ID ) left join CHB_PRD_BASEINFO cpb on cpb.PROD_ID = secASSET.FINPROD_MARKET_ID WHERE 1=1 AND DEAL.PS in ( 'HK09','HK10') and (ABS(nvl(deal.Prin_Amt,0)) + ABS(nvl(deal.trade_amt,0)) != 0)/* 去除面额和金额同时为空的情况 */ and nvL(deal.p_trade_id,'NOREV') = 'NOREV' )
SELECT DISTINCT * FROM ( SELECT investdeal.TRADE_SEQNO TRADE_SEQNO, investdeal.TRADE_Id TRADE_CODE, investdeal.INVEST_VARIETY INVEST_VARIETY, INVESTDEAL.INVEST_TYPE INVEST_TYPE, nvl(DEALADD.PORTFOLIO_ID,dealtotal.PORTFOLIO_ID) PROD_ID, investdeal.REGIST_BANK_CODE REGIST_BANK_CODE, investdeal.ASSET_CODE ASSET_CODE, investdeal.CCY CCY, investdeal.amt amt, investdeal.CNY_AMT CNY_AMT, nvl(investdeal.NUM,DEALTOtAL.share_amt) NUM,/*付息时取total*/ investdeal.CUR_ASSET_TYPE CUR_ASSET_TYPE, investdeal.CUR_ASSETDET_TYPE CUR_ASSETDET_TYPE, investdeal.DEALDATE DEALDATE, CUSTINFO.CUSTOMER_NAME TRADE_COUNTER, investdeal.UNIT_PRICE_FULL UNIT_PRICE_FULL, investdeal.UNIT_PRICE_NET UNIT_PRICE_NET, investdeal.END_RATE END_RATE, investdeal.CONTRACT_CODE CONTRACT_CODE, investdeal.REMARK REMARK, null CHL_CPCT_ID, investdeal.TRADE_TYPE TRADE_TYPE, investdeal.CHL_AGRT_NAME CHL_AGRT_NAME, INVESTDEAL.IS_UNDER_TRADE IS_UNDER_TRADE, investdeal.STATUS STATUS,/*撤销的数据改变有效状态*/ investdeal.ORG_CODE ORG_CODE, investdeal.DEPT_CODE DEPT_CODE, investdeal.CREATE_USER CREATE_USER, investdeal.CREATE_TIME CREATE_TIME, investdeal.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(investdeal.UPDATE_TIME,investdeal.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALADD.UPDATE_TIME,DEALADD.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')), nvl(NVL(DEALTOtAL.UPDATE_TIME,DEALTOtAL.CREATE_TIME),to_date('1900-01-01','yyyy-MM-dd')) ) UPDATE_TIME, INVESTDEAL.STATUS_DATE STATUS_DATE, INVESTDEAL.REV_DATE REV_DATE,/*撤销日*/ investdeal.data_source data_source, investdeal.rate rate, investdeal.BASIS BASIS, investdeal.DEALTYPE DEALTYPE, INVESTDEAL.FACEVALUE FACEVALUE, investdeal.INTPAYAMT INTPAYAMT, investdeal.F_TRADE_ID F_TRADE_CODE FROM INVESTDEAL investdeal LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD/*交易从属表*/ /*ON DEALADD.TRADE_ID = INVESTDEAL.TRADE_ID*/ ON (DEALADD.TRADE_ID = INVESTDEAL.TRADE_ID)
/*关联FIN_PRODUCT及FIN_TRADE_PRODUCT重新获取资产代码*/ left join FIN_PRODUCT fp on fp.FINPROD_ID = investdeal.ASSET_CODE LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL DEALTOtAL/*产品代码取不到取total表如：买断式回购*/ on INVESTDEAL.TOTLE_TRADE_ID = DEALTOtAL.TOTLE_TRADE_ID LEFT JOIN (select DISTINCT FINPROD_MARKET_ID from FIN_PRODUCT where FINPROD_TYPE2='F16') fpd on fpd.FINPROD_MARKET_ID=nvl(DEALADD.PORTFOLIO_ID,dealtotal.PORTFOLIO_ID) left join MST_CUSTOMER_INFO CUSTINFO ON CUSTINFO.CUSTOMER_ID=investdeal.TRADE_COUNTER where 1= 1 /*过滤估值生成交易*/ AND (EXISTS ( SELECT 1 FROM PTL_TRADE PTLTRADE WHERE 1 =1 AND PTLTRADE.BUSI_NO = investdeal.TRADE_ID )OR investdeal.INVEST_VARIETY IN ('27', '28', '29', '30')) /* 去除估值核算自动生成交易 */ AND NVL(investdeal.CUR_ASSET_TYPE,'NOTYPE') != 'NOTYPE' and fpd.FINPROD_MARKET_ID is not null )
where 1=1 and UPDATE_TIME > #{interfDate,jdbcType=TIMESTAMP}
/* 产品代码不为空时 */ and PROD_ID in
#{prodCode,jdbcType=VARCHAR}

select DISTINCT fp.finprod_market_id assetCode,fp1.finprod_market_id chlCpctId,FRA.PAY_TYPE payType from fin_cash_info ca left join fin_product fp on FP.FINPROD_ID=CA.FINPROD_ID left join fin_product fp1 on FP1.FINPROD_ID=CA.CHL_FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FRA ON FP1.FINPROD_ID = FRA.FINPROD_ID left join fin_product_type tp on tp.FINPROD_ID=FP.FINPROD_ID where TP.TYPE_8 IN('F06','F03'
,'F05'
) and CA.CHL_FINPROD_ID is not null
